local cjson = require("cjson")

local function decodeJsonSafe(value)
	if type(value) ~= "string" or value == "" then
		return nil, "invalid_json_input"
	end

	local ok, decoded = pcall(decodeJson, value)
	if not ok then
		return nil, decoded
	end

	return decoded
end

local function encodeJsonSafe(value, encoder)
	local ok, encoded = pcall(encoder or encodeJson, value)
	if not ok or type(encoded) ~= "string" then
		return nil, ok and "encoder_returned_" .. type(encoded) or encoded
	end

	return encoded
end

local function writeEncodedFile(path, encoded)
	if type(path) ~= "string" or path == "" or type(encoded) ~= "string" then
		return false, "invalid_write_arguments"
	end

	local file, openError = io.open(path, "w")
	if not file then
		return false, openError
	end

	local writeOk, writeError = pcall(function()
		file:write(encoded)
		file:flush()
	end)
	local closeOk, closeError = pcall(file.close, file)

	if not writeOk then
		return false, writeError
	end
	if not closeOk then
		return false, closeError
	end

	return true, "ok"
end

function readJsonFile(path, defaults)
	return gojson(path):Load(defaults or {})
end

function gojson(path, configType, backupName)
	local jsonFile = {}

	if not doesDirectoryExist(getWorkingDirectory() .. "\\ArzMarket") then
		createDirectory(getWorkingDirectory() .. "\\ArzMarket")
	end

	function jsonFile.Save(self, data)
		if data == nil then
			return false, "table = nil"
		end

		local encoded, encodeError = encodeJsonSafe(data, encodeJson)
		if not encoded then
			return false, "config encode error | " .. tostring(encodeError)
		end

		local saved, saveError = writeEncodedFile(path, encoded)
		if not saved then
			return false, "config write error | " .. tostring(saveError)
		end

		if (configType == "sell-cfg" or configType == "buy-cfg") and backupName ~= nil then
			local backupDirectory = getWorkingDirectory() .. "\\ArzMarket\\" .. configType .. "\\backups\\" .. os.date("%d.%m.%Y")
			if not doesDirectoryExist(backupDirectory) then
				createDirectory(backupDirectory)
			end

			writeEncodedFile(backupDirectory .. "\\" .. backupName, encoded)
		end

		return true, "ok"
	end

	function jsonFile.Load(self, defaults)
		defaults = type(defaults) == "table" and defaults or {}

		local function copyDefaults()
			local result = {}
			for key, defaultValue in pairs(defaults) do
				result[key] = defaultValue
			end
			return result
		end

		if not doesFileExist(path) then
			local initial = copyDefaults()
			jsonFile:Save(initial)
			return initial
		end

		local file = io.open(path, "r")
		if not file then
			return copyDefaults()
		end

		local rawJson = file:read("*a") or ""
		file:close()

		if rawJson == "" then
			return copyDefaults()
		end

		if rawJson:find("null,") then
			rawJson = rawJson:gsub("null,", "")
		end

		local decoded = decodeJsonSafe(rawJson)
		if type(decoded) ~= "table" then
			return copyDefaults()
		end

		for key, defaultValue in pairs(defaults) do
			if decoded[key] == nil then
				decoded[key] = defaultValue
			end
		end

		return decoded
	end

	return jsonFile
end

function saveLog(text)
	if doesDirectoryExist("moonloader/ArzMarket/UsersInfo/logs") then
		local cleanText = text:gsub("{......}", "")
		local file, openError = io.open(getWorkingDirectory() .. "/ArzMarket/UsersInfo/logs/" .. os.date("%d.%m.%Y") .. ".txt", "a")

		if file then
			file:write(cleanText .. "\n")
			file:flush()
			file:close()
		end
	end
end

function writeJsonFile(data, path)
	local encoded = encodeJsonSafe(data, cjson.encode)
	if not encoded or not (encoded:find("%{") or encoded:find("%[")) then
		return false
	end

	return writeEncodedFile(path, encoded) == true
end
