ARZ_RELEASE_NOTES_STATE = {
	pending = false,
	loaded = false,
	persisted = {}
}

function arzReleaseNotesInit()
	local state = readJsonFile(ARZ_RELEASE_NOTES_PATH, { last_shown_build = "" })
	if type(state) ~= "table" then
		state = { last_shown_build = "" }
	end
	ARZ_RELEASE_NOTES_STATE.persisted = state
	ARZ_RELEASE_NOTES_STATE.pending = tostring(state.last_shown_build or "") ~= tostring(ARZ_LOCAL_BUILD_ID)
	ARZ_RELEASE_NOTES_STATE.loaded = true
end

function arzReleaseNotesMarkShown()
	ARZ_RELEASE_NOTES_STATE.pending = false
	ARZ_RELEASE_NOTES_STATE.persisted = type(ARZ_RELEASE_NOTES_STATE.persisted) == "table" and ARZ_RELEASE_NOTES_STATE.persisted or {}
	ARZ_RELEASE_NOTES_STATE.persisted.last_shown_build = ARZ_LOCAL_BUILD_ID
	ARZ_RELEASE_NOTES_STATE.persisted.shown_at = os.time()
	local ok = writeJsonFile(ARZ_RELEASE_NOTES_STATE.persisted, ARZ_RELEASE_NOTES_PATH)
	if not ok then
		deAFKMessage("release notes state save failed")
	end
end

function arzRenderReleaseNotesWindow()
	if not ARZ_RELEASE_NOTES_STATE.pending then
		return
	end

	local io = imgui.GetIO()
	local display = io.DisplaySize
	local width = math.min(720, math.max(460, display.x - 60))
	local height = math.min(480, math.max(320, display.y - 80))

	imgui.SetNextWindowPos(imgui.ImVec2(display.x / 2, display.y / 2), imgui.Cond.Always, imgui.ImVec2(0.5, 0.5))
	imgui.SetNextWindowSize(imgui.ImVec2(width, height), imgui.Cond.Always)
	imgui.Begin("arz_release_notes_window", nil, imgui.WindowFlags.NoResize + imgui.WindowFlags.NoMove + imgui.WindowFlags.NoCollapse + imgui.WindowFlags.NoTitleBar)

	imgui.PushFont(fonts[17])
	imgui.CenterText(ARZ_RELEASE_NOTES.title)
	imgui.PopFont()
	imgui.SetCursorPosY(imgui.GetCursorPos().y + 4)
	imgui.CenterText("Версия изменений: " .. tostring(ARZ_LOCAL_BUILD_ID))
	imgui.CustomSeparator(imgui.GetWindowWidth())

	imgui.BeginChild("arz_release_notes_list", imgui.ImVec2(-1, height - 115), true)
	for i = 1, #ARZ_RELEASE_NOTES.items do
		imgui.TextWrapped(tostring(i) .. ". " .. ARZ_RELEASE_NOTES.items[i])
		imgui.SetCursorPosY(imgui.GetCursorPos().y + 5)
	end
	imgui.EndChild()

	local previousFrameBorderSize = imgui.GetStyle().FrameBorderSize
	imgui.GetStyle().FrameBorderSize = 0
	if imgui.Button("Понятно", imgui.ImVec2(imgui.GetWindowWidth(), 32)) then
		arzReleaseNotesMarkShown()
	end
	imgui.GetStyle().FrameBorderSize = previousFrameBorderSize
	imgui.End()
end

HEIGHT_CALCULATOR_UNITS = {
	{ id = "mm", label = "Миллиметры (мм)", meters = 0.001, digits = 1 },
	{ id = "cm", label = "Сантиметры (см)", meters = 0.01, digits = 2 },
	{ id = "dm", label = "Дециметры (дм)", meters = 0.1, digits = 3 },
	{ id = "m", label = "Метры (м)", meters = 1.0, digits = 4 },
	{ id = "in", label = "Дюймы", meters = 0.0254, digits = 2 },
	{ id = "ft", label = "Футы", meters = 0.3048, digits = 3 },
	{ id = "ftin", label = "Футы + дюймы", meters = nil, digits = 2 },
	{ id = "yd", label = "Ярды", meters = 0.9144, digits = 3 }
}
HEIGHT_CALCULATOR = {
	input = imguiNew.char[64](""),
	input_unit = 2,
	output_unit = 2,
	last_error = ""
}

function heightCalculatorTrim(text)
	return tostring(text or ""):match("^%s*(.-)%s*$") or ""
end

function heightCalculatorParseNumber(text)
	text = heightCalculatorTrim(text):gsub(",", ".")
	if text == "" or not text:match("^%d*%.?%d+$") then
		return nil
	end
	local value = tonumber(text)
	if not value or value ~= value or value == math.huge or value == -math.huge or value <= 0 then
		return nil
	end
	return value
end

function heightCalculatorParseInput()
	local unit = HEIGHT_CALCULATOR_UNITS[HEIGHT_CALCULATOR.input_unit]
	if not unit then
		return nil, "Неизвестная единица измерения."
	end
	local text = ffi.string(HEIGHT_CALCULATOR.input)

	if unit.id == "ftin" then
		local normalized = heightCalculatorTrim(text):gsub(",", ".")
		local feet, inches = normalized:match("^(%d+)%s*'%s*(%d*%.?%d+)%s*\"?$")
		if not feet then feet, inches = normalized:match("^(%d+)%s*:%s*(%d*%.?%d+)$") end
		if not feet then feet, inches = normalized:match("^(%d+)%s+(%d*%.?%d+)$") end
		feet, inches = tonumber(feet), tonumber(inches)
		if not feet or not inches or feet < 0 or inches < 0 or inches >= 12 then
			return nil, "Для футов и дюймов используйте формат 5 11 или 5:11."
		end
		local meters = feet * 0.3048 + inches * 0.0254
		if meters <= 0 then
			return nil, "Рост должен быть больше нуля."
		end
		return meters
	end

	local value = heightCalculatorParseNumber(text)
	if not value then
		return nil, "Введите корректное положительное число."
	end
	return value * unit.meters
end

function heightCalculatorFormatNumber(value, digits)
	local text = string.format("%." .. tostring(digits or 2) .. "f", tonumber(value) or 0)
	text = text:gsub("(%..-)0+$", "%1"):gsub("%.$", "")
	return text
end

function heightCalculatorFeetInches(meters)
	local totalInches = meters / 0.0254
	local feet = math.floor(totalInches / 12)
	local inches = totalInches - feet * 12
	if inches >= 11.995 then
		feet = feet + 1
		inches = 0
	end
	return tostring(feet) .. " " .. heightCalculatorFormatNumber(inches, 2)
end

function heightCalculatorFormatOutput(meters, unit)
	if not unit then return "" end
	if unit.id == "ftin" then
		return heightCalculatorFeetInches(meters) .. " " .. "фут. дюйм."
	end
	return heightCalculatorFormatNumber(meters / unit.meters, unit.digits) .. " " .. unit.label
end

function heightCalculatorRenderUnitCombo(id, selectedField)
	local selected = tonumber(HEIGHT_CALCULATOR[selectedField]) or 1
	local preview = HEIGHT_CALCULATOR_UNITS[selected] and HEIGHT_CALCULATOR_UNITS[selected].label or "?"
	if imgui.BeginCombo(id, preview) then
		for i = 1, #HEIGHT_CALCULATOR_UNITS do
			local unit = HEIGHT_CALCULATOR_UNITS[i]
			if imgui.Selectable(unit.label, i == selected) then
				HEIGHT_CALCULATOR[selectedField] = i
			end
		end
		imgui.EndCombo()
	end
end

function renderHeightCalculatorPage()
	imgui.PushFont(fonts[18])

	local startPos = imgui.GetCursorPos()
	local avail = imgui.GetContentRegionAvail()
	local contentWidth = math.max(0, tonumber(avail.x) or 0)
	local contentHeight = math.max(0, tonumber(avail.y) or 0)
	local fieldWidth = math.min(420, math.max(220, contentWidth - 40))
	local labelHeight = math.max(imgui.GetTextLineHeight(), 18)
	local fieldHeight = math.max(imgui.GetFrameHeight(), 28)
	local buttonHeight = math.max(imgui.GetFrameHeight(), 30)
	local spacingY = math.max(6, tonumber(imgui.GetStyle().ItemSpacing.y) or 0)
	local blockHeight = labelHeight + spacingY + fieldHeight + spacingY + buttonHeight
	local fieldX = startPos.x + math.max(0, (contentWidth - fieldWidth) * 0.5)
	local blockY = startPos.y + math.max(0, (contentHeight - blockHeight) * 0.5)

	local label = "Введите ваш рост:"
	local labelWidth = imgui.CalcTextSize(label).x
	imgui.SetCursorPos(imgui.ImVec2(fieldX + math.max(0, (fieldWidth - labelWidth) * 0.5), blockY))
	imgui.Text(label)

	imgui.SetCursorPos(imgui.ImVec2(fieldX, blockY + labelHeight + spacingY))

	-- Enter remains supported because some users submit directly from the input.
	local submitByEnter = HEIGHT_CALCULATOR.input_active == true and isKeyJustPressed(0x0D)

	imgui.PushItemWidth(fieldWidth)
	imgui.InputTextWithHintD(
		"##height_calculator_input",
		"",
		HEIGHT_CALCULATOR.input,
		ffi.sizeof(HEIGHT_CALCULATOR.input)
	)
	imgui.PopItemWidth()

	local inputActive = false
	if imgui.IsItemActive ~= nil then
		local ok, value = pcall(imgui.IsItemActive)
		inputActive = ok and value == true
	end
	if not inputActive and imgui.IsItemFocused ~= nil then
		local ok, value = pcall(imgui.IsItemFocused)
		inputActive = ok and value == true
	end
	HEIGHT_CALCULATOR.input_active = inputActive

	imgui.SetCursorPos(imgui.ImVec2(
		fieldX,
		blockY + labelHeight + spacingY + fieldHeight + spacingY
	))
	local submitByButton = imgui.Button("Отправить##height_calculator_submit", imgui.ImVec2(fieldWidth, buttonHeight))

	if submitByEnter or submitByButton then
		local centimeters = heightCalculatorParseNumber(ffi.string(HEIGHT_CALCULATOR.input))
		if centimeters then
			local meters = centimeters * 0.01
			local resultText =
				heightCalculatorFormatNumber(centimeters, 2) .. " " .. "см"
				.. " = " .. heightCalculatorFormatNumber(meters, 4) .. " " .. "м"
				.. " = " .. heightCalculatorFeetInches(meters) .. " " .. "фут. дюйм."
			local notificationText = "Рост: " .. resultText
			sendNotify(notificationText)
			if isSampAvailable() then
				sampAddChatMessage(u8:decode(notificationText), 0xFFFFFFFF)
			end
		else
			local errorText = "Введите корректный рост в сантиметрах."
			sendNotify(errorText)
			if isSampAvailable() then
				sampAddChatMessage(u8:decode(errorText), 0xFFFFFFFF)
			end
		end
	end

	imgui.PopFont()
end

