    imgui.SetCursorPosX(math.max(16, (imgui.GetWindowWidth() - titleSize.x) * 0.5))
    imgui.TextColored(imgui.ImVec4(0.20, 0.78, 0.95, 1.0), title)
    imgui.Separator()
    imgui.Dummy(imgui.ImVec2(1, 5))

    local count = type(state.snapshot) == "table" and #snapshotToItems(state.snapshot) or 0
    imgui.Text("Сканирование завершено")
    imgui.SameLine()
    imgui.TextDisabled("Найдено предметов: " .. safeString(count))
    imgui.Dummy(imgui.ImVec2(1, 5))

    imgui.Text("Тип хранилища:")
    imgui.SetNextItemWidth(-1)
    renderCombo("##storage_capture_kind", STORAGE_CAPTURE_KIND_OPTIONS, state.selected_kind, function(value)
        state.selected_kind = value
        state.suggested_name = getManualScanSuggestedName(value, state.snapshot)
        state.name_initialized = false
        state.error = nil
    end)

    imgui.Dummy(imgui.ImVec2(1, 3))
    imgui.Text("Название хранилища:")
    imgui.SetNextItemWidth(-1)
    imgui.InputText("##storage_capture_name", ui.capture_name_buf, ffi.sizeof(ui.capture_name_buf))

    if state.selected_kind == STORAGE_KIND.VEHICLE_TRUNK then
        imgui.TextDisabled("Для машины укажи название автомобиля.")
    elseif state.selected_kind == STORAGE_KIND.WAREHOUSE then
        imgui.TextDisabled("Для склада укажи номер или понятное название.")
    else
        imgui.TextDisabled("Для дома укажи номер дома или понятное обозначение.")
    end

    if state.error then
        imgui.TextColored(imgui.ImVec4(1.0, 0.35, 0.35, 1.0), state.error)
    else
        imgui.Dummy(imgui.ImVec2(1, 19))
    end

    local width = imgui.GetContentRegionAvail().x
    if imgui.Button("Сохранить##storage_capture_save", imgui.ImVec2((width - 8) / 2, 36)) then
        saveManualExternalScan(state.selected_kind, getBuffer(ui.capture_name_buf))
    end
    imgui.SameLine()
    if imgui.Button("Отмена##storage_capture_cancel", imgui.ImVec2((width - 8) / 2, 36)) then
        state.dialog_open = false
        state.snapshot = nil
        state.error = nil
        state.name_initialized = false
    end

    if pushedFont then imgui.PopFont() end
    imgui.End()
    imgui.PopStyleVar(4)
    imgui.PopStyleColor(10)
end

local function renderSpecificStorageFilter()
    local options = getSpecificStorageOptions()
    if #options == 0 then
        if ui.specific_storage_key ~= "" then
            ui.specific_storage_key = ""
            invalidateVisibleRows()
        end
        return
    end

    if not isSpecificStorageStillValid(options) then
        ui.specific_storage_key = ""
        invalidateVisibleRows()
    end

    local comboOptions = {
        { value = "", label = "Все конкретные места" }
    }
    for i = 1, #options do
        comboOptions[#comboOptions + 1] = options[i]
    end

    renderCombo("Конкретное место", comboOptions, ui.specific_storage_key, function(value)
        ui.specific_storage_key = value
        invalidateVisibleRows()
    end)
end

local function renderStorageBrowser()
    local scale = 1
    if type(getMenuUiScale) == "function" then
        local ok, value = pcall(getMenuUiScale)
        if ok and tonumber(value) then
            scale = math.max(0.75, tonumber(value))
        end
    end

    local available = imgui.GetContentRegionAvail()
    local totalWidth = math.max(300, tonumber(available.x) or 300)
    local totalHeight = math.max(120, tonumber(available.y) or 120)

    local contentStart = imgui.GetCursorPos()
    local outerPadX = math.max(6, 8 * scale)
    local topPadY = math.max(6, 8 * scale)
    local listGapY = math.max(4, 6 * scale)

    imgui.SetCursorPosX(contentStart.x + outerPadX)
    imgui.SetCursorPosY(contentStart.y + topPadY)

    local searchWidth = math.min(470 * scale, math.max(260 * scale, totalWidth * 0.43))
    searchWidth = math.min(searchWidth, totalWidth - outerPadX * 2)

    imgui.PushItemWidth(searchWidth)
    if type(imgui.NewInput) == "function" then
        imgui.NewInput(" Поиск предметов", ui.search_buf, ffi.sizeof(ui.search_buf), "storage_search")
    elseif type(imgui.InputTextWithHintD) == "function" then
        imgui.InputTextWithHintD(
            "##storage_search",
            " Поиск предметов",
            ui.search_buf,
            ffi.sizeof(ui.search_buf)
        )
    else
        imgui.InputText("##storage_search", ui.search_buf, ffi.sizeof(ui.search_buf))
    end
    imgui.PopItemWidth()

    local query = normalizeSearchText(getBuffer(ui.search_buf))

    local catalogByName = {}
    local catalog = {}
    local index = getIndexedItems()

    for i = 1, #index do
        local row = index[i]
        local itemName = safeString(row.name, "Неизвестный предмет")
        local itemKey = normalizeSearchText(itemName)

        if itemKey ~= "" and (query == "" or string.find(itemKey, query, 1, true) ~= nil) then
            local itemEntry = catalogByName[itemKey]
            if not itemEntry then
                itemEntry = {
                    key = itemKey,
                    name = itemName,
                    count = 0,
                    locations_by_key = {},
                    locations = {}
                }
                catalogByName[itemKey] = itemEntry
                catalog[#catalog + 1] = itemEntry
            end

            itemEntry.count = itemEntry.count + normalizeCount(row.count)

            local storageKey = safeString(row.storage_key, "unknown:" .. safeString(i))
            local location = itemEntry.locations_by_key[storageKey]
            if not location then
                location = {
                    key = storageKey,
                    kind = row.storage_kind,
                    label = row.storage_label,
                    identity = type(row.storage_identity) == "table" and deepCopy(row.storage_identity) or {}
                }
                itemEntry.locations_by_key[storageKey] = location
                itemEntry.locations[#itemEntry.locations + 1] = location
            end
        end
    end

    table.sort(catalog, function(a, b)
        return normalizeSearchText(a.name) < normalizeSearchText(b.name)
    end)

    for i = 1, #catalog do
        table.sort(catalog[i].locations, function(a, b)
            local ak = safeString(a.kind)
            local bk = safeString(b.kind)
            if ak == bk then
                return safeString(a.label) < safeString(b.label)
            end
            return ak < bk
        end)
    end

    local function formatStorageLocation(location)
        local identity = type(location.identity) == "table" and location.identity or {}

        if location.kind == STORAGE_KIND.VEHICLE_TRUNK then
            local vehicleName = trim(safeString(
                identity.vehicle_name,
                safeString(location.label, "Автомобиль"):gsub("%s*%-%>%s*Багажник%s*$", "")
            ))
            if vehicleName == "" then vehicleName = "Автомобиль" end
            return "Машина №" .. vehicleName
        end

        if location.kind == STORAGE_KIND.HOUSE_CLOSET then
            local houseNumber = trim(safeString(identity.house_number))
            if houseNumber == "" then
                houseNumber = safeString(location.label):match("Дом №(.+)%s+%-%>") or safeString(location.label)
            end
            return "Дом №" .. houseNumber
        end

        if location.kind == STORAGE_KIND.HOUSE_OBJECT then
            local houseNumber = trim(safeString(identity.house_number))
            if houseNumber == "" then
                houseNumber = safeString(location.label):match("Дом №(.+)%s+%-%>") or safeString(location.label)
            end
            return "Дом №" .. houseNumber .. ", объект возле дома"
        end

        if location.kind == STORAGE_KIND.WAREHOUSE then
            local warehouseNumber = trim(safeString(identity.warehouse_number))
            if warehouseNumber == "" then
                warehouseNumber = safeString(location.label):match("Склад №(.+)$") or safeString(location.label)
            end
            return "Склад №" .. warehouseNumber
        end

        if location.kind == STORAGE_KIND.PLAYER_INVENTORY then
            return "Инвентарь"
        end

        return safeString(location.label, "Неизвестное хранилище")
    end

    imgui.SetCursorPosY(imgui.GetCursorPos().y + listGapY)
    imgui.SetCursorPosX(contentStart.x + outerPadX)

    local listHeight = math.max(
        90,
        totalHeight - topPadY - listGapY - math.max(34, imgui.GetFrameHeightWithSpacing())
    )
    local listWidth = math.max(120, totalWidth - outerPadX * 2)

    imgui.CustomInvisibleChild(
        "storageLeftList",
        imgui.ImVec2(listWidth, listHeight),
        true,
        imgui.WindowFlags.NoScrollWithMouse
    )
    imgui.Scroller("storageLeftList", 100, 600, imgui.HoveredFlags.AllowWhenBlockedByActiveItem)

    local clipper = imgui.ImGuiListClipper(#catalog)
    clipper:Begin(#catalog)

    while clipper:Step() do
        for visibleIndex = clipper.DisplayStart, clipper.DisplayEnd - 1 do
            local item = catalog[visibleIndex + 1]
            if item then
                local displayText = safeString(item.name) .. " (" .. safeString(item.count, "0") .. ")"

                -- Search does not move the item into another panel.
                -- It stays in the same list row and receives storage info inline.
                if query ~= "" and #item.locations > 0 then
                    local locationParts = {}
                    for locationIndex = 1, #item.locations do
                        locationParts[#locationParts + 1] = formatStorageLocation(item.locations[locationIndex])
                    end

                    if #locationParts > 0 then
                        displayText = displayText .. " | " .. table.concat(locationParts, "; ")
                    end
                end

                imgui.SetCursorPosX(imgui.GetCursorPos().x + 2)

                -- Match the vertical row step used by the Buy source list:
                -- fonts[18] text height + the ArzMarket 5*scale ItemSpacing.
                local storageRowStartY = imgui.GetCursorPos().y
                imgui.Text("%s", displayText)
                imgui.SetCursorPosY(
                    storageRowStartY
                    + imgui.GetTextLineHeight()
                    + (5 * scale)
                )

            end
        end
    end

    clipper:End()
    imgui.EndCustomInvisibleChild()
end

local function cleanupBindings(predicate)
    local bindings = app.settings.bindings and app.settings.bindings.fingerprints
    if type(bindings) ~= "table" then
        return
    end

    for fingerprint, binding in pairs(bindings) do
        if type(binding) == "table" and predicate(binding) then
            bindings[fingerprint] = nil
        end
    end
end

local function deleteHouse(number, removeHistory)
    number = safeString(number)
    removeHouseNumber(number)

    cleanupBindings(function(binding)
        return type(binding.identity) == "table"
            and safeString(binding.identity.house_number) == number
    end)

    if removeHistory then
        app.database.storages["house:" .. number .. ":closet"] = nil
        app.database.storages["house:" .. number .. ":object"] = nil
        invalidateSearchIndex()
        saveDatabaseAtomic()
    end

    saveSettings()
    if ui.selected_house == number then
        ui.selected_house = ""
        setBuffer(ui.house_buf, "")
    end
end

local function deleteWarehouse(number, removeHistory)
    number = safeString(number)
    removeWarehouseNumber(number)

    cleanupBindings(function(binding)
        return type(binding.identity) == "table"
            and safeString(binding.identity.warehouse_number) == number
    end)

    if removeHistory then
        app.database.storages["warehouse:" .. number] = nil
        invalidateSearchIndex()
        saveDatabaseAtomic()
    end

    saveSettings()
    if ui.selected_warehouse == number then
        ui.selected_warehouse = ""
        setBuffer(ui.warehouse_buf, "")
    end
end

local function forgetVehicle(vehicleKey, removeHistory)
    vehicleKey = safeString(vehicleKey)
    if vehicleKey == "" then
        return
    end

    app.settings.vehicles[vehicleKey] = nil

    cleanupBindings(function(binding)
        return type(binding.identity) == "table"
            and safeString(binding.identity.vehicle_key) == vehicleKey
    end)

    if removeHistory then
        app.database.storages["vehicle:" .. vehicleKey] = nil
        invalidateSearchIndex()
        saveDatabaseAtomic()
    end

    saveSettings()
    if ui.selected_vehicle == vehicleKey then
        ui.selected_vehicle = ""
        setBuffer(ui.vehicle_name_buf, "")
    end
end

local function requestDelete(kind, key)
    ui.pending_delete_kind = safeString(kind)
    ui.pending_delete_key = safeString(key)
end

local function renderDeleteConfirmation()
    if ui.pending_delete_kind == "" or ui.pending_delete_key == "" then
        return
    end

    imgui.Separator()
    imgui.TextWrapped("Удалить запись " .. ui.pending_delete_key .. "? Можно оставить уже просканированную историю либо удалить ее вместе с настройкой.")

    if imgui.Button("Удалить только настройку") then
        if ui.pending_delete_kind == "house" then
            deleteHouse(ui.pending_delete_key, false)
        elseif ui.pending_delete_kind == "warehouse" then
            deleteWarehouse(ui.pending_delete_key, false)
        elseif ui.pending_delete_kind == "vehicle" then
            forgetVehicle(ui.pending_delete_key, false)
        end
        ui.pending_delete_kind = ""
        ui.pending_delete_key = ""
    end

    imgui.SameLine()
    if imgui.Button("Удалить вместе с историей") then
        if ui.pending_delete_kind == "house" then
            deleteHouse(ui.pending_delete_key, true)
        elseif ui.pending_delete_kind == "warehouse" then
            deleteWarehouse(ui.pending_delete_key, true)
        elseif ui.pending_delete_kind == "vehicle" then
            forgetVehicle(ui.pending_delete_key, true)
        end
        ui.pending_delete_kind = ""
        ui.pending_delete_key = ""
    end

    imgui.SameLine()
    if imgui.Button("Отмена") then
        ui.pending_delete_kind = ""
        ui.pending_delete_key = ""
    end
end

local function renderHouseSettings()
    imgui.Text("Дома")
    imgui.TextWrapped("Добавь номера домов. Для первой привязки выбери дом и укажи, что следующим будет открыт шкаф или объект возле дома.")

    imgui.BeginChild("##houses_list", imgui.ImVec2(0, 130), true)
    if #app.settings.houses == 0 then
        imgui.Text("Дома пока не добавлены.")
    end

    for i = 1, #app.settings.houses do
        local number = safeString(app.settings.houses[i])
        if imgui.Selectable("Дом №" .. number .. "##house_" .. safeString(i), ui.selected_house == number) then
            ui.selected_house = number
            setBuffer(ui.house_buf, number)
        end
    end
    imgui.EndChild()

    imgui.SetNextItemWidth(180)
    imgui.InputText("Номер дома##house_input", ui.house_buf, ffi.sizeof(ui.house_buf))

    if imgui.Button("Добавить дом") then
        local value = trim(getBuffer(ui.house_buf))
        if value ~= "" and addHouseNumber(value) then
            ui.selected_house = value
            invalidateVisibleRows()
        end
    end

    imgui.SameLine()
    if imgui.Button("Изменить номер") and ui.selected_house ~= "" then
        local value = trim(getBuffer(ui.house_buf))
        local old = ui.selected_house
        if value ~= "" and editHouseNumber(old, value) then
            ui.selected_house = value
            invalidateVisibleRows()
        end
    end

    imgui.SameLine()
    if imgui.Button("Удалить дом") and ui.selected_house ~= "" then
        requestDelete("house", ui.selected_house)
    end

    if ui.selected_house ~= "" then
        if imgui.Button("Следующее открытие: шкаф дома №" .. ui.selected_house) then
            setPendingBinding(STORAGE_KIND.HOUSE_CLOSET, ui.selected_house)
        end

        if imgui.Button("Следующее открытие: объект дома №" .. ui.selected_house) then
            setPendingBinding(STORAGE_KIND.HOUSE_OBJECT, ui.selected_house)
        end
    end
end

local function renderWarehouseSettings()
    imgui.Text("Складские помещения")
    imgui.TextWrapped("Номер складского помещения задается пользователем. После первой успешной привязки скрипт будет использовать сохраненный fingerprint, если Arizona его передает.")

