            ui.selected_warehouse = number
            setBuffer(ui.warehouse_buf, number)
        end
    end
    imgui.EndChild()

    imgui.SetNextItemWidth(180)
    imgui.InputText("Номер склада##warehouse_input", ui.warehouse_buf, ffi.sizeof(ui.warehouse_buf))

    if imgui.Button("Добавить склад") then
        local value = trim(getBuffer(ui.warehouse_buf))
        if value ~= "" and addWarehouseNumber(value) then
            ui.selected_warehouse = value
            invalidateVisibleRows()
        end
    end

    imgui.SameLine()
    if imgui.Button("Изменить склад") and ui.selected_warehouse ~= "" then
        local value = trim(getBuffer(ui.warehouse_buf))
        local old = ui.selected_warehouse
        if value ~= "" and editWarehouseNumber(old, value) then
