-- Ctrl+Z protection for accidental item deletion in buy/sell lists.
-- Each list has its own undo stack. Only real trash-button deletions are saved;
-- sorting and drag/reorder operations are intentionally ignored.
modificationState.marketUndoVkeys = modificationState.marketUndoVkeys or require("vkeys")
modificationState.itemDeleteUndo = modificationState.itemDeleteUndo or {
	buy = {},
	sell = {},
	maxEntries = 50
}

function resetListSelectionAfterDelete()
	selectedListItem = {
		imguiNew.int(333),
		333,
		false
	}
end

function pushDeletedListItem(listType, list, index)
	local stack = modificationState.itemDeleteUndo[listType]
	index = tonumber(index)

	if type(stack) ~= "table" or type(list) ~= "table" or index == nil or list[index] == nil then
		return false
	end

	stack[#stack + 1] = {
		listRef = list,
		index = index,
		item = list[index]
	}

	while #stack > modificationState.itemDeleteUndo.maxEntries do
		table.remove(stack, 1)
	end

	return true
end

function deleteListItemWithUndo(listType, list, index)
	index = tonumber(index)

	if not pushDeletedListItem(listType, list, index) then
		return false
	end

	local item = list[index]
	local itemName = type(item) == "table" and tostring(item.name or "") or ""

	table.remove(list, index)
	resetListSelectionAfterDelete()

	if itemName ~= "" then
		sendNotify(u8:decode("Удалено: ") .. itemName .. u8:decode(". Ctrl+Z - вернуть."))
	else
		sendNotify(u8:decode("Товар удалён. Ctrl+Z - вернуть."))
	end

	return true
end

function undoLastDeletedListItem(listType)
	local stack = modificationState.itemDeleteUndo[listType]
	local list = listType == "buy" and buyList or sellList

	if type(stack) ~= "table" or type(list) ~= "table" then
		return false
	end

	-- Entries from an old config/list instance must never leak into a newly
	-- loaded config. Drop stale records until the current list instance is found.
	while #stack > 0 and stack[#stack].listRef ~= list do
		table.remove(stack)
	end

	if #stack == 0 then
		return false
	end

	local record = table.remove(stack)
	local item = record.item

	if type(item) ~= "table" then
		return false
	end

	local itemName = tostring(item.name or "")
	if itemName ~= "" and containsItem(list, itemName) then
		sendNotify(u8:decode("Ctrl+Z: товар уже есть в списке."))
		return false
	end

	item.position_tab = nil
	local insertIndex = math.max(1, math.min(tonumber(record.index) or (#list + 1), #list + 1))
	table.insert(list, insertIndex, item)
	resetListSelectionAfterDelete()

	if itemName ~= "" then
		sendNotify(u8:decode("Ctrl+Z: восстановлено: ") .. itemName .. ".")
	else
		sendNotify(u8:decode("Ctrl+Z: товар восстановлен."))
	end

	return true
end

function handleListDeleteUndoHotkey()
	if not menuVisible[0] or (selectedMenuPage ~= 1 and selectedMenuPage ~= 2) then
		return
	end

	if not isKeyDown(modificationState.marketUndoVkeys.VK_CONTROL) or not isKeyJustPressed(modificationState.marketUndoVkeys.VK_Z) then
		return
	end

	-- Do not steal the native Ctrl+Z from active text inputs.
	local io = imgui.GetIO()
	local anyItemActive = false
	if imgui.IsAnyItemActive ~= nil then
		local ok, active = pcall(imgui.IsAnyItemActive)
		anyItemActive = ok and active == true
	end

	if (io and io.WantTextInput) or anyItemActive then
		return
	end

	if selectedMenuPage == 1 then
		undoLastDeletedListItem("sell")
	else
		undoLastDeletedListItem("buy")
	end
end
