-- Global INI write lock. Once account/auth data already exists, ArzMarket starts
-- in read-only mode so the current account can never replace the saved profile.
-- The Authorization button persists this state in a separate marker file because
-- ArzMarket.ini itself must not be rewritten after the lock is enabled.
ARZ_INI_WRITE_LOCK_PATH = "moonloader/config/ArzMarket/ini_write_locked.flag"
ARZ_INI_WRITE_LOCKED = false
ARZ_INI_LOCK_SNAPSHOT = nil


-- Persistent network isolation for this Lua script.
-- When enabled, every HTTP/HTTPS request created by ArzMarket is blocked.
-- SA-MP/RakNet traffic is intentionally not affected because it belongs to the game connection.
ARZ_SCRIPT_OFFLINE_FLAG_PATH = "moonloader/config/ArzMarket/offline_mode.flag"
ARZ_SCRIPT_OFFLINE = doesFileExist(ARZ_SCRIPT_OFFLINE_FLAG_PATH)
ARZ_SCRIPT_OFFLINE_LAST_NOTICE = 0
ARZ_SCRIPT_OFFLINE_NATIVE_DOWNLOAD = downloadUrlToFile

-- ============================================================
-- ArzMarket isolated proxy transport.
-- Only HTTP/HTTPS traffic created by this Lua script is proxied.
-- SA-MP/RakNet remains untouched and therefore keeps the normal game IP.
--
-- External launcher config:
-- moonloader/config/ArzMarket/network_proxy.ini
--
-- [proxy]
-- enabled=0
-- type=http
-- host=
-- port=0
-- username=
-- password=
-- timeout=45
--
-- Supported proxy types are handled by curl.exe: http, https, socks4,
-- socks4a, socks5 and socks5h. If enabled=1, this transport is fail-closed:
-- an invalid/dead proxy NEVER falls back to a direct request.
-- ============================================================
ARZ_PROXY_CONFIG_PATH = "moonloader/config/ArzMarket/network_proxy.ini"
ARZ_PROXY_REQUIRED_FLAG_PATH = "moonloader/config/ArzMarket/proxy_required.flag"
ARZ_PROXY_TEMP_DIR = getWorkingDirectory() .. "\\ArzMarket\\proxy_tmp"
ARZ_PROXY_CONFIG_RELOAD_SECONDS = 0
ARZ_PROXY_REQUEST_SERIAL = 0
ARZ_PROXY_DOWNLOAD_SERIAL = 0
ARZ_PROXY_DOWNLOAD_THREADS = {}
ARZ_PROXY_CONFIG = {
	enabled = false,
	type = "http",
	host = "",
	port = 0,
	username = "",
	password = "",
	timeout = 45,
	valid = true,
	error = "",
	loadedAt = 0
}

function arzProxyTrim(value)
	return tostring(value or ""):match("^%s*(.-)%s*$") or ""
end

function arzProxyParseBool(value)
	local normalized = string.lower(arzProxyTrim(value))
	return normalized == "1" or normalized == "true" or normalized == "yes" or normalized == "on"
end

function arzProxyEnsureConfigDirectory()
	local configRoot = "moonloader/config"
	local configArzMarket = configRoot .. "/ArzMarket"
	if not doesDirectoryExist(configRoot) then
		pcall(createDirectory, configRoot)
	end
	if not doesDirectoryExist(configArzMarket) then
		pcall(createDirectory, configArzMarket)
	end
	return doesDirectoryExist(configArzMarket)
end

function arzProxyEnsureTempDirectory()
	if not doesDirectoryExist(getWorkingDirectory() .. "\\ArzMarket") then
		pcall(createDirectory, getWorkingDirectory() .. "\\ArzMarket")
	end
	if not doesDirectoryExist(ARZ_PROXY_TEMP_DIR) then
		pcall(createDirectory, ARZ_PROXY_TEMP_DIR)
	end
	return doesDirectoryExist(ARZ_PROXY_TEMP_DIR)
end

function arzProxyWriteDefaultConfig()
	if doesFileExist(ARZ_PROXY_CONFIG_PATH) then return true end
	if not arzProxyEnsureConfigDirectory() then return false end
	local file = io.open(ARZ_PROXY_CONFIG_PATH, "wb")
	if not file then return false end
	file:write(table.concat({
		"[proxy]",
		"enabled=0",
		"type=http",
		"host=",
		"port=0",
		"username=",
		"password=",
		"timeout=45",
		""
	}, "\r\n"))
	file:flush()
	file:close()
	return true
end

function arzProxyIsRequiredPersisted()
	return doesFileExist(ARZ_PROXY_REQUIRED_FLAG_PATH)
end

function arzProxyPersistRequired(required)
	required = required == true
	if required then
		if not arzProxyEnsureConfigDirectory() then return false end
		local file = io.open(ARZ_PROXY_REQUIRED_FLAG_PATH, "wb")
		if not file then return false end
		file:write("1")
		file:flush()
		file:close()
		return doesFileExist(ARZ_PROXY_REQUIRED_FLAG_PATH)
	end
	if doesFileExist(ARZ_PROXY_REQUIRED_FLAG_PATH) then
		local ok = pcall(os.remove, ARZ_PROXY_REQUIRED_FLAG_PATH)
		if not ok or doesFileExist(ARZ_PROXY_REQUIRED_FLAG_PATH) then return false end
	end
	return true
end

function arzProxyCleanupTempDirectory()
	if not arzProxyEnsureTempDirectory() then return false end
	local ok, iterator, directoryObject = pcall(lfs.dir, ARZ_PROXY_TEMP_DIR)
	if not ok or type(iterator) ~= "function" then return false end
	for name in iterator, directoryObject do
		if name ~= "." and name ~= ".." then
			local fullPath = ARZ_PROXY_TEMP_DIR .. "\\" .. tostring(name)
			local attrOk, attributes = pcall(lfs.attributes, fullPath)
			if attrOk and type(attributes) == "table" and attributes.mode == "file" then
				pcall(os.remove, fullPath)
			end
		end
	end
	return true
end

function arzProxyValidateConfig(cfg)
	cfg.valid = true
	cfg.error = ""
	if not cfg.enabled then return cfg end

	local allowedTypes = {
		http = true,
		https = true,
		socks4 = true,
		socks4a = true,
		socks5 = true,
		socks5h = true
	}

	if not allowedTypes[cfg.type] then
		cfg.valid = false
		cfg.error = "unsupported_proxy_type"
		return cfg
	end

	if cfg.host == "" or not cfg.host:match("^[%w%.%-%_%:%[%]]+$") then
		cfg.valid = false
		cfg.error = "invalid_proxy_host"
		return cfg
	end

	cfg.port = math.floor(tonumber(cfg.port) or 0)
	if cfg.port < 1 or cfg.port > 65535 then
		cfg.valid = false
		cfg.error = "invalid_proxy_port"
		return cfg
	end

	if cfg.username:find("[\r\n%z]") or cfg.password:find("[\r\n%z]") then
		cfg.valid = false
		cfg.error = "invalid_proxy_credentials"
		return cfg
	end

	if cfg.username == "" and cfg.password ~= "" then
		cfg.valid = false
		cfg.error = "proxy_username_missing"
		return cfg
	end

	cfg.timeout = math.floor(tonumber(cfg.timeout) or 45)
	cfg.timeout = math.max(5, math.min(300, cfg.timeout))
	return cfg
end

function arzProxyLoadConfig(force)
	local now = os.clock()
	if not force and type(ARZ_PROXY_CONFIG) == "table" and now - (tonumber(ARZ_PROXY_CONFIG.loadedAt) or 0) < ARZ_PROXY_CONFIG_RELOAD_SECONDS then
		return ARZ_PROXY_CONFIG
	end

	local persistedRequired = arzProxyIsRequiredPersisted()
	if not doesFileExist(ARZ_PROXY_CONFIG_PATH) then
		-- Once proxy mode has been active, deleting/losing the config must not
		-- silently restore direct networking. An explicit enabled=0 is required.
		if persistedRequired or (type(ARZ_PROXY_CONFIG) == "table" and ARZ_PROXY_CONFIG.enabled == true) then
			ARZ_PROXY_CONFIG.enabled = true
			ARZ_PROXY_CONFIG.valid = false
			ARZ_PROXY_CONFIG.error = "proxy_config_missing_while_enabled"
			ARZ_PROXY_CONFIG.loadedAt = now
			return ARZ_PROXY_CONFIG
		end
		arzProxyWriteDefaultConfig()
	end

	local file = io.open(ARZ_PROXY_CONFIG_PATH, "rb")
	if not file then
		-- If proxy was already active, a temporary read failure must not silently
		-- switch traffic back to the real IP.
		if persistedRequired or (type(ARZ_PROXY_CONFIG) == "table" and ARZ_PROXY_CONFIG.enabled == true) then
			ARZ_PROXY_CONFIG.valid = false
			ARZ_PROXY_CONFIG.error = "proxy_config_unreadable"
			ARZ_PROXY_CONFIG.loadedAt = now
			return ARZ_PROXY_CONFIG
		end
		ARZ_PROXY_CONFIG = {
			enabled = false,
			type = "http",
			host = "",
			port = 0,
			username = "",
			password = "",
			timeout = 45,
			valid = true,
			error = "",
			loadedAt = now
		}
		return ARZ_PROXY_CONFIG
	end

	local rawConfig = file:read("*a") or ""
	file:close()
	local values = {}
	local section = ""
	for line in rawConfig:gmatch("[^\r\n]+") do
		local clean = arzProxyTrim(line)
		local sectionName = clean:match("^%[([^%]]+)%]$")
		if sectionName then
			section = string.lower(arzProxyTrim(sectionName))
		elseif section == "proxy" and clean ~= "" and clean:sub(1, 1) ~= ";" and clean:sub(1, 1) ~= "#" then
			local key, value = clean:match("^([^=]+)=(.*)$")
			if key then
				values[string.lower(arzProxyTrim(key))] = arzProxyTrim(value)
			end
		end
	end

	local enabledRaw = values.enabled
	local enabledNormalized = enabledRaw ~= nil and string.lower(arzProxyTrim(enabledRaw)) or nil
	local enabledRecognized = enabledNormalized == "1" or enabledNormalized == "true" or enabledNormalized == "yes" or enabledNormalized == "on"
		or enabledNormalized == "0" or enabledNormalized == "false" or enabledNormalized == "no" or enabledNormalized == "off"
	local previousWasEnabled = persistedRequired or (type(ARZ_PROXY_CONFIG) == "table" and ARZ_PROXY_CONFIG.enabled == true)
	local cfg = {
		enabled = enabledRecognized and arzProxyParseBool(enabledRaw) or previousWasEnabled,
		type = string.lower(values.type or values.scheme or (previousWasEnabled and ARZ_PROXY_CONFIG.type) or "http"),
		host = values.host or values.ip or (previousWasEnabled and ARZ_PROXY_CONFIG.host) or "",
		port = tonumber(values.port) or (previousWasEnabled and ARZ_PROXY_CONFIG.port) or 0,
		username = values.username or values.user or values.login or (previousWasEnabled and ARZ_PROXY_CONFIG.username) or "",
		password = values.password or values.pass or (previousWasEnabled and ARZ_PROXY_CONFIG.password) or "",
		timeout = tonumber(values.timeout) or (previousWasEnabled and ARZ_PROXY_CONFIG.timeout) or 45,
		valid = true,
		error = "",
		loadedAt = now
	}
	if not enabledRecognized then
		if previousWasEnabled or (enabledRaw ~= nil and arzProxyTrim(enabledRaw) ~= "") then
			cfg.enabled = true
			cfg.valid = false
			cfg.error = "proxy_enabled_state_invalid"
			ARZ_PROXY_CONFIG = cfg
			pcall(arzProxyPersistRequired, true)
			return ARZ_PROXY_CONFIG
		end
	end
	ARZ_PROXY_CONFIG = arzProxyValidateConfig(cfg)
	if enabledRecognized and ARZ_PROXY_CONFIG.enabled == true then
		if not arzProxyPersistRequired(true) then
			ARZ_PROXY_CONFIG.valid = false
			ARZ_PROXY_CONFIG.error = "proxy_required_marker_write_failed"
		end
	elseif enabledRecognized and ARZ_PROXY_CONFIG.enabled == false then
		if not arzProxyPersistRequired(false) then
			ARZ_PROXY_CONFIG.enabled = true
			ARZ_PROXY_CONFIG.valid = false
			ARZ_PROXY_CONFIG.error = "proxy_required_marker_remove_failed"
		end
	elseif ARZ_PROXY_CONFIG.enabled == true then
		pcall(arzProxyPersistRequired, true)
	end
	return ARZ_PROXY_CONFIG
end

function arzProxyGetConfigSnapshot()
	local cfg = arzProxyLoadConfig(false)
	if type(cfg) ~= "table" then
		return nil, false, "proxy_config_missing"
	end
	if not cfg.enabled then
		return nil, false, nil
	end
	if not cfg.valid then
		return nil, true, cfg.error ~= "" and cfg.error or "proxy_config_invalid"
	end
	return {
		enabled = true,
		type = tostring(cfg.type),
		host = tostring(cfg.host),
		port = tonumber(cfg.port),
		username = tostring(cfg.username or ""),
		password = tostring(cfg.password or ""),
		timeout = tonumber(cfg.timeout) or 45
	}, true, nil
end

function arzProxyNextRequestKey(prefix)
	ARZ_PROXY_REQUEST_SERIAL = (tonumber(ARZ_PROXY_REQUEST_SERIAL) or 0) + 1
	return tostring(prefix or "req") .. "_" .. tostring(os.time()) .. "_" .. tostring(ARZ_PROXY_REQUEST_SERIAL)
end

function arzProxyCurlConfigQuote(value)
	value = tostring(value or "")
	if value:find("[\r\n%z]") then return nil end
	value = value:gsub("\\", "\\\\"):gsub('"', '\\"')
	return '"' .. value .. '"'
end

function arzProxyBuildUrl(cfg)
	local host = tostring(cfg.host or "")
	if host:find(":", 1, true) and not host:match("^%[.*%]$") then
		host = "[" .. host .. "]"
	end
	return tostring(cfg.type or "http") .. "://" .. host .. ":" .. tostring(math.floor(tonumber(cfg.port) or 0))
end

function arzProxyResolveCurlPath()
	local windowsRoot = tostring(os.getenv("WINDIR") or os.getenv("SystemRoot") or "")
	if windowsRoot == "" then return nil end
	local candidates = {
		windowsRoot .. "\\SysWOW64\\curl.exe",
		windowsRoot .. "\\Sysnative\\curl.exe",
		windowsRoot .. "\\System32\\curl.exe"
	}
	for _, candidate in ipairs(candidates) do
		local ok, exists = pcall(doesFileExist, candidate)
		if ok and exists then return candidate end
	end
	return nil
end

function arzProxyWriteCurlRequest(method, url, requestOptions, requestKey, outputPath, timeoutSeconds)
	local cfg, enabled, configError = arzProxyGetConfigSnapshot()
	if not enabled then return nil, false, nil end
	if not cfg then return nil, true, configError or "proxy_config_invalid" end
	if not effilLoaded or not effil then return nil, true, "effil_unavailable" end
	if not arzProxyEnsureTempDirectory() then return nil, true, "proxy_temp_directory_failed" end
	local curlPath = arzProxyResolveCurlPath()
	if not curlPath then return nil, true, "windows_curl_not_found" end

	method = string.upper(tostring(method or "GET"))
	url = tostring(url or "")
	if url == "" or not url:match("^https?://") then
		return nil, true, "proxy_target_url_invalid"
	end

	requestOptions = type(requestOptions) == "table" and requestOptions or {}
	local configPath = ARZ_PROXY_TEMP_DIR .. "\\" .. requestKey .. ".curl"
	local errorPath = ARZ_PROXY_TEMP_DIR .. "\\" .. requestKey .. ".err"
	local dataPath = nil
	local requestData = requestOptions.data
	if type(requestData) == "table" then
		local ok, encoded = pcall(cjson.encode, requestData)
		if not ok or type(encoded) ~= "string" then
			return nil, true, "proxy_request_json_encode_failed"
		end
		requestData = encoded
	elseif requestData ~= nil and type(requestData) ~= "string" then
		requestData = tostring(requestData)
	end

	if type(requestData) == "string" and #requestData > 0 then
		dataPath = ARZ_PROXY_TEMP_DIR .. "\\" .. requestKey .. ".data"
		local dataFile = io.open(dataPath, "wb")
		if not dataFile then return nil, true, "proxy_request_body_file_failed" end
		dataFile:write(requestData)
		dataFile:flush()
		dataFile:close()
	end

	local timeout = math.floor(tonumber(timeoutSeconds) or tonumber(cfg.timeout) or 45)
	timeout = math.max(5, math.min(300, timeout))
	local connectTimeout = math.max(3, math.min(20, math.floor(timeout / 3)))
	local quotedMethod = arzProxyCurlConfigQuote(method)
	local quotedUrl = arzProxyCurlConfigQuote(url)
	local quotedProxy = arzProxyCurlConfigQuote(arzProxyBuildUrl(cfg))
	local quotedOutput = arzProxyCurlConfigQuote(outputPath)
	if not quotedMethod or not quotedUrl or not quotedProxy or not quotedOutput then
		if dataPath then pcall(os.remove, dataPath) end
		return nil, true, "proxy_request_value_invalid"
	end
	local lines = {
		"silent",
		"show-error",
		"location",
		"noproxy = \"\"",
		"proto = \"=http,https\"",
		"proto-redir = \"=http,https\"",
		"max-time = " .. tostring(timeout),
		"connect-timeout = " .. tostring(connectTimeout),
		"request = " .. quotedMethod,
		"url = " .. quotedUrl,
		"proxy = " .. quotedProxy,
		"output = " .. quotedOutput,
		"write-out = \"ARZHTTP:%{http_code}:ARZEXIT:%{exitcode}\""
	}

	if cfg.username ~= "" then
		local credentials = cfg.username .. ":" .. cfg.password
		local quotedCredentials = arzProxyCurlConfigQuote(credentials)
		if not quotedCredentials then
			if dataPath then pcall(os.remove, dataPath) end
			return nil, true, "proxy_credentials_invalid"
		end
		lines[#lines + 1] = "proxy-user = " .. quotedCredentials
		if cfg.type == "http" or cfg.type == "https" then
			lines[#lines + 1] = "proxy-anyauth"
		end
	end

	local wantsCompressed = false
	if type(requestOptions.headers) == "table" then
		for headerName, headerValue in pairs(requestOptions.headers) do
			if headerValue ~= nil then
				local name = tostring(headerName)
				local value = tostring(headerValue)
				if name:find("[\r\n:%z]") or value:find("[\r\n%z]") then
					if dataPath then pcall(os.remove, dataPath) end
					return nil, true, "proxy_request_header_invalid"
				end
				if string.lower(name) == "accept-encoding" then
					local lowerValue = string.lower(value)
					wantsCompressed = lowerValue:find("gzip", 1, true) ~= nil
						or lowerValue:find("deflate", 1, true) ~= nil
						or lowerValue:find("br", 1, true) ~= nil
						or lowerValue:find("zstd", 1, true) ~= nil
				end
				local quotedHeader = arzProxyCurlConfigQuote(name .. ": " .. value)
				if not quotedHeader then
					if dataPath then pcall(os.remove, dataPath) end
					return nil, true, "proxy_request_header_invalid"
				end
				lines[#lines + 1] = "header = " .. quotedHeader
			end
		end
	end
	if wantsCompressed then
		lines[#lines + 1] = "compressed"
	end

	if dataPath then
		local quotedDataPath = arzProxyCurlConfigQuote("@" .. dataPath)
		if not quotedDataPath then
			pcall(os.remove, dataPath)
			return nil, true, "proxy_request_body_path_invalid"
		end
		lines[#lines + 1] = "data-binary = " .. quotedDataPath
	end

	local configFile = io.open(configPath, "wb")
	if not configFile then
		if dataPath then pcall(os.remove, dataPath) end
		return nil, true, "proxy_curl_config_write_failed"
	end
	configFile:write(table.concat(lines, "\r\n") .. "\r\n")
	configFile:flush()
	configFile:close()

	return {
		curlPath = curlPath,
		configPath = configPath,
		errorPath = errorPath,
		dataPath = dataPath,
		outputPath = outputPath,
		proxy = arzProxyBuildUrl(cfg)
	}, true, nil
end

function arzProxyStartCurlThread(curlJob, readBody, removeOutput)
	if type(curlJob) ~= "table" then return nil, "proxy_job_invalid" end
	local ok, threadOrError = pcall(function()
		return effil.thread(function(curlPath, configPath, errorPath, dataPath, outputPath, readBody, removeOutput)
			local function readFile(path)
				if type(path) ~= "string" or path == "" then return "" end
				local file = io.open(path, "rb")
				if not file then return "" end
				local content = file:read("*a") or ""
				file:close()
				return content
			end
			local function removeFile(path)
				if type(path) == "string" and path ~= "" then pcall(os.remove, path) end
			end
			local function quoteCmdPath(path)
				return '"' .. tostring(path or ""):gsub('"', '""') .. '"'
			end

			local command = quoteCmdPath(curlPath) .. " --disable --config " .. quoteCmdPath(configPath) .. " 2> " .. quoteCmdPath(errorPath)
			local pipe = io.popen(command, "r")
			if not pipe then
				removeFile(configPath)
				removeFile(dataPath)
				return false, "curl_start_failed"
			end
			local stdout = pipe:read("*a") or ""
			pcall(function() pipe:close() end)
			local errorText = readFile(errorPath)
			local httpCode = tonumber(stdout:match("ARZHTTP:(%d%d%d)"))
			local exitCode = tonumber(stdout:match("ARZEXIT:(%d+)"))
			local body = readBody and readFile(outputPath) or ""

			removeFile(configPath)
			removeFile(errorPath)
			removeFile(dataPath)
			if removeOutput then removeFile(outputPath) end

			if exitCode ~= 0 or not httpCode or httpCode == 0 then
				local message = errorText ~= "" and errorText or stdout
				if message == "" then message = "curl_failed_without_http_status" end
				return false, message
			end

			return true, {
				status_code = httpCode,
				text = body,
				headers = {},
				proxy_transport = true
			}
		end)(curlJob.curlPath, curlJob.configPath, curlJob.errorPath, curlJob.dataPath, curlJob.outputPath, readBody == true, removeOutput == true)
	end)
	if not ok then return nil, tostring(threadOrError) end
	return threadOrError, nil
end

function arzProxyCreateHttpThread(method, url, requestOptions, requestKey, timeoutSeconds)
	local cfg, enabled, configError = arzProxyGetConfigSnapshot()
	if not enabled then return nil, false, nil end
	if not cfg then return nil, true, configError or "proxy_config_invalid" end
	local outputPath = ARZ_PROXY_TEMP_DIR .. "\\" .. requestKey .. ".response"
	local transportTimeout = tonumber(timeoutSeconds) or tonumber(cfg.timeout) or 45
	if transportTimeout > 8 then transportTimeout = transportTimeout - 3 end
	local job, proxyRequired, prepareError = arzProxyWriteCurlRequest(method, url, requestOptions, requestKey, outputPath, transportTimeout)
	if not proxyRequired then return nil, false, nil end
	if not job then return nil, true, prepareError or "proxy_request_prepare_failed" end
	local thread, threadError = arzProxyStartCurlThread(job, true, true)
	if not thread then return nil, true, threadError or "proxy_thread_start_failed" end
	return thread, true, nil
end

function arzProxyStartDownload(url, targetPath, callback)
	local cfg, enabled, configError = arzProxyGetConfigSnapshot()
	if not enabled then return nil, false, nil end
	ARZ_PROXY_DOWNLOAD_SERIAL = (tonumber(ARZ_PROXY_DOWNLOAD_SERIAL) or 0) + 1
	local downloadId = 1000000 + ARZ_PROXY_DOWNLOAD_SERIAL
	if not cfg then
		if type(callback) == "function" then
			lua_thread.create(function()
				wait(0)
				pcall(callback, downloadId, -1)
			end)
		end
		return downloadId, true, configError or "proxy_config_invalid"
	end

	local key = arzProxyNextRequestKey("download")
	local partPath = tostring(targetPath) .. ".arzproxy.part." .. tostring(downloadId)
	local job, proxyRequired, prepareError = arzProxyWriteCurlRequest("GET", url, {}, key, partPath, cfg.timeout)
	if not job then
		if type(callback) == "function" then
			lua_thread.create(function()
				wait(0)
				pcall(callback, downloadId, -1)
			end)
		end
		return downloadId, true, prepareError or "proxy_download_prepare_failed"
	end

	local thread, threadError = arzProxyStartCurlThread(job, false, false)
	if not thread then
		pcall(os.remove, partPath)
		if type(callback) == "function" then
			lua_thread.create(function()
				wait(0)
				pcall(callback, downloadId, -1)
			end)
		end
		return downloadId, true, threadError or "proxy_download_thread_failed"
	end
	ARZ_PROXY_DOWNLOAD_THREADS[downloadId] = thread

	lua_thread.create(function()
		while true do
			local statusOk, threadStatus, threadStateError = pcall(function()
				return thread:status()
			end)
			if not statusOk then
				ARZ_PROXY_DOWNLOAD_THREADS[downloadId] = nil
				pcall(os.remove, partPath)
				if type(callback) == "function" then pcall(callback, downloadId, -1) end
				return
			end
			if threadStateError then
				ARZ_PROXY_DOWNLOAD_THREADS[downloadId] = nil
				pcall(os.remove, partPath)
				if type(callback) == "function" then pcall(callback, downloadId, -1) end
				return
			end
			if threadStatus == "completed" then
				local getOk, requestOk, result = pcall(function() return thread:get(0) end)
				ARZ_PROXY_DOWNLOAD_THREADS[downloadId] = nil
				if getOk and requestOk and type(result) == "table" and tonumber(result.status_code) and tonumber(result.status_code) >= 200 and tonumber(result.status_code) < 400 and doesFileExist(partPath) then
					pcall(os.remove, targetPath)
					local moved = os.rename(partPath, targetPath)
					if moved then
						local dlStatus = require("moonloader").download_status
						if type(callback) == "function" then pcall(callback, downloadId, dlStatus.STATUS_ENDDOWNLOADDATA or 6) end
						return
					end
				end
				pcall(os.remove, partPath)
				if type(callback) == "function" then pcall(callback, downloadId, -1) end
				return
			elseif threadStatus == "canceled" then
				ARZ_PROXY_DOWNLOAD_THREADS[downloadId] = nil
				pcall(os.remove, partPath)
				if type(callback) == "function" then pcall(callback, downloadId, -1) end
				return
			end
			wait(0)
		end
	end)

	return downloadId, true, nil
end

pcall(arzProxyCleanupTempDirectory)
arzProxyWriteDefaultConfig()
arzProxyLoadConfig(true)

function arzScriptOfflineEnsureDirectory()
	local configRoot = "moonloader/config"
	local configArzMarket = configRoot .. "/ArzMarket"
	if not doesDirectoryExist(configRoot) then
		pcall(createDirectory, configRoot)
	end
	if not doesDirectoryExist(configArzMarket) then
		pcall(createDirectory, configArzMarket)
	end
	return doesDirectoryExist(configArzMarket)
end

function arzScriptOfflineCancelInFlight()
	if type(marketState) ~= "table" then return end

	if type(marketState.asyncThreads) == "table" then
		for requestId, requestThread in pairs(marketState.asyncThreads) do
			if requestThread ~= nil then
				pcall(function()
					if requestThread.cancel then requestThread:cancel() end
				end)
			end
			marketState.asyncThreads[requestId] = nil
		end
	end

	if type(marketState.asyncData) == "table" then
		for requestId in pairs(marketState.asyncData) do
			marketState.asyncData[requestId] = nil
		end
	end

	if type(ARZ_PROXY_DOWNLOAD_THREADS) == "table" then
		for downloadId, downloadThread in pairs(ARZ_PROXY_DOWNLOAD_THREADS) do
			if downloadThread ~= nil then
				pcall(function()
					if downloadThread.cancel then downloadThread:cancel() end
				end)
			end
			ARZ_PROXY_DOWNLOAD_THREADS[downloadId] = nil
		end
	end
end

function arzScriptOfflineSet(enabled)
	enabled = enabled == true
	if enabled == ARZ_SCRIPT_OFFLINE then return true end

	if enabled then
		if not arzScriptOfflineEnsureDirectory() then return false end
		local file = io.open(ARZ_SCRIPT_OFFLINE_FLAG_PATH, "wb")
		if not file then return false end
		file:write("1")
		file:flush()
		file:close()
		ARZ_SCRIPT_OFFLINE = true
		arzScriptOfflineCancelInFlight()
	else
		if doesFileExist(ARZ_SCRIPT_OFFLINE_FLAG_PATH) then
			local ok = pcall(os.remove, ARZ_SCRIPT_OFFLINE_FLAG_PATH)
			if not ok or doesFileExist(ARZ_SCRIPT_OFFLINE_FLAG_PATH) then return false end
		end
		ARZ_SCRIPT_OFFLINE = false
	end

	return true
end

function arzScriptOfflineReject(kind, target)
	if not ARZ_SCRIPT_OFFLINE then return false end
	local now = os.clock()
	if now - (tonumber(ARZ_SCRIPT_OFFLINE_LAST_NOTICE) or 0) >= 2 then
		ARZ_SCRIPT_OFFLINE_LAST_NOTICE = now
		print("[ArzMarket][OFFLINE] blocked " .. tostring(kind or "network") .. ": " .. tostring(target or ""))
	end
	return true
end

-- MoonLoader's downloader bypasses asyncHttpRequest. When proxy mode is active
-- it is replaced by the same fail-closed curl transport, otherwise native behavior is preserved.
if type(ARZ_SCRIPT_OFFLINE_NATIVE_DOWNLOAD) == "function" then
	downloadUrlToFile = function(url, path, callback, ...)
		if arzScriptOfflineReject("download", url) then
			if type(callback) == "function" then
				lua_thread.create(function()
					wait(0)
					pcall(callback, -1, -1)
				end)
			end
			return -1
		end

		local proxyDownloadId, proxyEnabled = arzProxyStartDownload(url, path, callback)
		if proxyEnabled then
			return proxyDownloadId or -1
		end

		return ARZ_SCRIPT_OFFLINE_NATIVE_DOWNLOAD(url, path, callback, ...)
	end
end

-- While the Authorization lock is enabled, every INI value is frozen.
-- The Server API session token is protected by the same lock as all other
-- account data and cannot be replaced by another SA-MP window.
function arzIniDeepCopy(value)
	if type(value) ~= "table" then return value end
	local copy = {}
	for key, item in pairs(value) do
		copy[key] = arzIniDeepCopy(item)
	end
	return copy
end

function arzIniCaptureLockSnapshot()
	if type(ini) ~= "table" then return false end
	ARZ_INI_LOCK_SNAPSHOT = arzIniDeepCopy(ini)
	return true
end

function arzIniRestoreTableFromSnapshot(target, source, sectionName)
	if type(target) ~= "table" or type(source) ~= "table" then return end

	for key in pairs(target) do
		if source[key] == nil then
			target[key] = nil
		end
	end

	for key, value in pairs(source) do
		if type(value) == "table" then
			if type(target[key]) ~= "table" then target[key] = {} end
			arzIniRestoreTableFromSnapshot(target[key], value, tostring(key))
		else
			target[key] = value
		end
	end
end

function arzIniRestoreLockedSnapshot()
	if not ARZ_INI_WRITE_LOCKED then return true end
	if type(ARZ_INI_LOCK_SNAPSHOT) ~= "table" then
		return arzIniCaptureLockSnapshot()
	end
	if type(ini) ~= "table" then return false end

	arzIniRestoreTableFromSnapshot(ini, ARZ_INI_LOCK_SNAPSHOT, nil)
	return true
end

function arzIniHasSavedAccountData()
	if type(ini) ~= "table" or type(ini.cfg) ~= "table" then return false end
	local fields = {
		"myServerToken", "myServerId", "authNickname", "authUid",
		"authPremiumTokenAuth", "authUserTempKey", "authRealNameMode1",
		"authRealNameMode2", "authSelfInfoId", "authSelfInfoUsername",
		"authSelfInfoExp", "authSelfInfoOsTime", "marketAuthKey"
	}
	for _, fieldName in ipairs(fields) do
		local value = ini.cfg[fieldName]
		if value ~= nil and tostring(value):gsub("^%s*(.-)%s*$", "%1") ~= "" then
			return true
		end
	end
	return false
end

function arzIniPersistWriteLock(enabled)
	if enabled == false then
		if doesFileExist(ARZ_INI_WRITE_LOCK_PATH) then
			local ok = pcall(os.remove, ARZ_INI_WRITE_LOCK_PATH)
			if not ok or doesFileExist(ARZ_INI_WRITE_LOCK_PATH) then return false end
		end
		return true
	end

	local file = io.open(ARZ_INI_WRITE_LOCK_PATH, "wb")
	if not file then return false end
	file:write("1")
	file:flush()
	file:close()
	return true
end

function arzIniRefreshWriteLock()
	-- The toggle state is controlled only by the marker file. Existing account
	-- data no longer forces the lock on by itself, so the same UI button can
	-- persistently switch receiving/writing both OFF and ON across restarts.
	ARZ_INI_WRITE_LOCKED = doesFileExist(ARZ_INI_WRITE_LOCK_PATH)
	if ARZ_INI_WRITE_LOCKED then
		arzIniCaptureLockSnapshot()
	else
		ARZ_INI_LOCK_SNAPSHOT = nil
	end
	return ARZ_INI_WRITE_LOCKED
end

function arzIniSave(forceWrite)
	if ARZ_INI_WRITE_LOCKED and forceWrite ~= true then
		-- Revert every accidental/config/account mutation before touching disk.
		-- This includes cfg.myServerToken.
		if not arzIniRestoreLockedSnapshot() then return false end
	end
	return inicfg.save(ini, iniPath) == true
end

ARZ_MANUAL_SERVER_TOKEN_BUFFER = imguiNew.char[1024]()
ARZ_ACTUAL_SERVER_TOKEN_BUFFER = imguiNew.char[1024]()
ARZ_USED_SERVER_TOKEN_BUFFER = imguiNew.char[1024]()
ARZ_LAST_SEEN_SERVER_TOKEN = nil
ARZ_LAST_SEEN_SERVER_ID = nil

function arzAuthorizationTokenBufferSet(buffer, value)
	if buffer == nil then return end
	local text = tostring(value or "")
	local bufferSize = ffi.sizeof(buffer)
	if #text >= bufferSize then
		text = text:sub(1, bufferSize - 1)
	end
	ffi.fill(buffer, bufferSize, 0)
	if #text > 0 then
		ffi.copy(buffer, text, #text)
	end
end

function arzAuthorizationGetUsedServerToken()
	local token = nil
	if type(arzSavedCfgString) == "function" then
		local ok, value = pcall(arzSavedCfgString, "myServerToken")
		if ok then token = value end
	end
	if token == nil and type(ini) == "table" and type(ini.cfg) == "table" then
		token = ini.cfg.myServerToken
	end
	return tostring(token or "")
end

function arzRefreshAuthorizationTokenBuffers()
	local actualToken = tostring(ARZ_LAST_SEEN_SERVER_TOKEN or "")
	local usedToken = arzAuthorizationGetUsedServerToken()
	arzAuthorizationTokenBufferSet(ARZ_ACTUAL_SERVER_TOKEN_BUFFER, actualToken)
	arzAuthorizationTokenBufferSet(ARZ_USED_SERVER_TOKEN_BUFFER, usedToken)
end

function arzRememberServerToken(rawToken, rawServerId)
	local token = tostring(rawToken or ""):gsub("%z+$", ""):gsub("^%s*(.-)%s*$", "%1")
	if token == "" then return false end
	ARZ_LAST_SEEN_SERVER_TOKEN = token
	if rawServerId ~= nil and tostring(rawServerId) ~= "" then
		ARZ_LAST_SEEN_SERVER_ID = tostring(rawServerId)
	end
	return true
end

function arzApplyLastSeenServerToken()
	if ARZ_INI_WRITE_LOCKED then return false end
	if type(ini) ~= "table" or type(ini.cfg) ~= "table" then return false end
	local token = tostring(ARZ_LAST_SEEN_SERVER_TOKEN or ""):gsub("^%s*(.-)%s*$", "%1")
	if token == "" then return false end
	local targetServerId = nil
	if ARZ_LAST_SEEN_SERVER_ID ~= nil and tostring(ARZ_LAST_SEEN_SERVER_ID) ~= "" then
		targetServerId = tostring(ARZ_LAST_SEEN_SERVER_ID)
	end
	local currentToken = tostring(ini.cfg.myServerToken or "")
	local currentServerId = tostring(ini.cfg.myServerId or "")
	if currentToken == token and (targetServerId == nil or currentServerId == targetServerId) then
		if type(arzManualServerTokenBufferSet) == "function" then
			arzManualServerTokenBufferSet(token)
		end
		return true
	end
	ini.cfg.myServerToken = token
	if targetServerId ~= nil then
		ini.cfg.myServerId = targetServerId
	end
	if type(ARZ_AUTH_FREEZE) == "table" then
		ARZ_AUTH_FREEZE["cfg:myServerToken"] = token
		if ARZ_LAST_SEEN_SERVER_ID ~= nil then
			ARZ_AUTH_FREEZE["cfg:myServerId"] = tostring(ARZ_LAST_SEEN_SERVER_ID)
		end
	end
	local saved = inicfg.save(ini, iniPath) == true
	if saved and type(arzManualServerTokenBufferSet) == "function" then
		arzManualServerTokenBufferSet(token)
	end
	if saved and type(arzApplySavedAuthRuntime) == "function" then pcall(arzApplySavedAuthRuntime) end
	return saved
end

function arzManualServerTokenBufferSet(value)
	local text = tostring(value or "")
	local bufferSize = ffi.sizeof(ARZ_MANUAL_SERVER_TOKEN_BUFFER)
	if #text >= bufferSize then
		text = text:sub(1, bufferSize - 1)
	end
	ffi.fill(ARZ_MANUAL_SERVER_TOKEN_BUFFER, bufferSize, 0)
	if #text > 0 then
		ffi.copy(ARZ_MANUAL_SERVER_TOKEN_BUFFER, text, #text)
	end
end

function arzSaveManualServerToken(rawToken)
	local token = tostring(rawToken or ""):gsub("%z+$", ""):gsub("^%s*(.-)%s*$", "%1")
	if token == "" then return false, "empty token" end
	if type(ini) ~= "table" or type(ini.cfg) ~= "table" then return false, "INI unavailable" end

	-- A manually saved token must be immutable against incoming account data.
	-- Enable the persistent receiver lock automatically if necessary.
	if not ARZ_INI_WRITE_LOCKED then
		local locked = arzStopReceivingAccountData()
		if not locked then return false, "failed to enable INI lock" end
	end

	-- Restore the frozen profile first so this explicit save cannot accidentally
	-- persist any transient values received from the second SA-MP window.
	if not arzIniRestoreLockedSnapshot() then return false, "failed to restore locked INI" end
	ini.cfg.myServerToken = token
	if type(ARZ_AUTH_FREEZE) == "table" then
		ARZ_AUTH_FREEZE["cfg:myServerToken"] = token
	end

	if inicfg.save(ini, iniPath) ~= true then return false, "failed to save INI" end
	arzIniCaptureLockSnapshot()
	arzManualServerTokenBufferSet(token)
	if type(arzApplySavedAuthRuntime) == "function" then pcall(arzApplySavedAuthRuntime) end
	return true
end

function arzStopReceivingAccountData()
	-- Freeze the exact current INI state, including cfg.myServerToken.
	if type(ini) == "table" then pcall(inicfg.save, ini, iniPath) end
	ARZ_INI_WRITE_LOCKED = true
	arzIniCaptureLockSnapshot()
	ARZ_AUTH_FREEZE = {}
	if type(marketState) == "table" and type(marketState.myUidCheck) == "table" then
		marketState.myUidCheck[1] = false
	end
	pcall(arzAuthFreezeProtectIni)
	pcall(arzApplySavedAuthRuntime)
	return arzIniPersistWriteLock(true)
end

function arzStartReceivingAccountData()
	-- Removing the marker is the only persistent unlock action. When unlocked,
	-- incoming account/auth values may update the INI again. HTTP requests still
	-- read those values from the INI, never directly from transient packet data.
	if not arzIniPersistWriteLock(false) then return false end
	ARZ_INI_WRITE_LOCKED = false
	ARZ_INI_LOCK_SNAPSHOT = nil
	ARZ_AUTH_FREEZE = {}
	if type(marketState) == "table" and type(marketState.myUidCheck) == "table" then
		marketState.myUidCheck[1] = true
		marketState.myUidCheck[3] = os.time() - 3
	end
	-- A real setToken event can arrive before the launcher has removed a previous INI lock.
	-- Keep that event in RAM and commit it now, immediately after receiving is enabled.
	local appliedSeenToken = false
	if type(arzApplyLastSeenServerToken) == "function" then
		local ok, applied = pcall(arzApplyLastSeenServerToken)
		appliedSeenToken = ok and applied == true
	end
	if not appliedSeenToken and type(arzManualServerTokenBufferSet) == "function" then
		arzManualServerTokenBufferSet(type(ini) == "table" and type(ini.cfg) == "table" and ini.cfg.myServerToken or "")
	end
	return true
end

function arzToggleReceivingAccountData()
	if ARZ_INI_WRITE_LOCKED then
		return arzStartReceivingAccountData(), false
	end
	return arzStopReceivingAccountData(), true
end

arzIniRefreshWriteLock()
arzManualServerTokenBufferSet(type(ini) == "table" and type(ini.cfg) == "table" and ini.cfg.myServerToken or "")

-- ============================================================
-- Lua <-> BAT account watchdog bridge.
-- Lua writes state.ini every 2 seconds.
-- BAT reads state.ini and restarts only this GTA process by PID.
-- BAT writes bat_heartbeat.ini, so the Authorization page can show whether
-- the external controller is alive. Both sides read watchdog_config.ini.
-- ============================================================
ARZ_WATCHDOG_DIR = "moonloader/ArzMarket/watchdog"
ARZ_WATCHDOG_CONFIG_PATH = ARZ_WATCHDOG_DIR .. "/watchdog_config.ini"
ARZ_WATCHDOG_STATE_PATH = ARZ_WATCHDOG_DIR .. "/state.ini"
ARZ_WATCHDOG_BAT_HEARTBEAT_PATH = ARZ_WATCHDOG_DIR .. "/bat_heartbeat.ini"
ARZ_WATCHDOG_WRITE_INTERVAL_MS = 2000
ARZ_WATCHDOG_BAT_STALE_SECONDS = 10

function arzWatchdogEnsureDirectory()
    if not doesDirectoryExist(ARZ_WATCHDOG_DIR) then
        pcall(createDirectory, ARZ_WATCHDOG_DIR)
    end
    return doesDirectoryExist(ARZ_WATCHDOG_DIR)
end

function arzWatchdogSanitize(value)
    return tostring(value or ""):gsub("[\r\n]", " ")
end

function arzWatchdogAtomicWrite(path, content)
    if not arzWatchdogEnsureDirectory() then return false end
    local tempPath = path .. ".tmp"
    local file = io.open(tempPath, "wb")
    if not file then return false end
    local ok = pcall(function()
        file:write(content)
        file:flush()
    end)
    pcall(file.close, file)
    if not ok then
        pcall(os.remove, tempPath)
        return false
    end
    if doesFileExist(path) then pcall(os.remove, path) end
    local renamed = os.rename(tempPath, path)
    if not renamed then
        pcall(os.remove, tempPath)
        return false
    end
    return true
end

function arzWatchdogReadKeyValueFile(path)
    local result = {}
    local file = io.open(path, "rb")
    if not file then return result end
    for line in file:lines() do
        line = tostring(line or ""):gsub("\r$", "")
        local key, value = line:match("^([%w_]+)=(.*)$")
        if key then result[key] = value end
    end
    file:close()
    return result
end

ARZ_WATCHDOG_CONFIG = {
    enabled = true,
    nick = "Nikita_Quart",
    server = "80.66.82.22",
    port = 7777,
    disconnect_timeout = 15,
    startup_grace = 90,
    unspawned_timeout = 30
}

function arzWatchdogLoadConfig()
    arzWatchdogEnsureDirectory()
    local loaded = arzWatchdogReadKeyValueFile(ARZ_WATCHDOG_CONFIG_PATH)
    if next(loaded) ~= nil then
        if loaded.enabled ~= nil then ARZ_WATCHDOG_CONFIG.enabled = tostring(loaded.enabled) == "1" end
        if loaded.nick and loaded.nick ~= "" then ARZ_WATCHDOG_CONFIG.nick = loaded.nick end
        if loaded.server and loaded.server ~= "" then ARZ_WATCHDOG_CONFIG.server = loaded.server end
        ARZ_WATCHDOG_CONFIG.port = math.max(1, math.min(65535, tonumber(loaded.port) or ARZ_WATCHDOG_CONFIG.port))
        ARZ_WATCHDOG_CONFIG.disconnect_timeout = math.max(5, math.min(300, tonumber(loaded.disconnect_timeout) or ARZ_WATCHDOG_CONFIG.disconnect_timeout))
        ARZ_WATCHDOG_CONFIG.startup_grace = math.max(30, math.min(600, tonumber(loaded.startup_grace) or ARZ_WATCHDOG_CONFIG.startup_grace))
        ARZ_WATCHDOG_CONFIG.unspawned_timeout = math.max(10, math.min(300, tonumber(loaded.unspawned_timeout) or ARZ_WATCHDOG_CONFIG.unspawned_timeout))
    end
    return ARZ_WATCHDOG_CONFIG
end

function arzWatchdogSaveConfig()
    local cfg = ARZ_WATCHDOG_CONFIG
    local content = table.concat({
        "enabled=" .. (cfg.enabled and "1" or "0"),
        "nick=" .. arzWatchdogSanitize(cfg.nick),
        "server=" .. arzWatchdogSanitize(cfg.server),
        "port=" .. tostring(math.floor(tonumber(cfg.port) or 7777)),
        "disconnect_timeout=" .. tostring(math.floor(tonumber(cfg.disconnect_timeout) or 15)),
        "startup_grace=" .. tostring(math.floor(tonumber(cfg.startup_grace) or 90)),
        "unspawned_timeout=" .. tostring(math.floor(tonumber(cfg.unspawned_timeout) or 30)),
        ""
    }, "\r\n")
    return arzWatchdogAtomicWrite(ARZ_WATCHDOG_CONFIG_PATH, content)
end

function arzWatchdogBufferSet(buffer, value)
    local text = tostring(value or "")
    local size = ffi.sizeof(buffer)
    if #text >= size then text = text:sub(1, size - 1) end
    ffi.fill(buffer, size, 0)
    if #text > 0 then ffi.copy(buffer, text, #text) end
end

arzWatchdogLoadConfig()
if not doesFileExist(ARZ_WATCHDOG_CONFIG_PATH) then arzWatchdogSaveConfig() end
ARZ_WATCHDOG_ENABLED_UI = imguiNew.bool(ARZ_WATCHDOG_CONFIG.enabled == true)
ARZ_WATCHDOG_NICK_BUFFER = imguiNew.char[64]()
ARZ_WATCHDOG_SERVER_BUFFER = imguiNew.char[128]()
arzWatchdogBufferSet(ARZ_WATCHDOG_NICK_BUFFER, ARZ_WATCHDOG_CONFIG.nick)
arzWatchdogBufferSet(ARZ_WATCHDOG_SERVER_BUFFER, ARZ_WATCHDOG_CONFIG.server)

ARZ_WATCHDOG_RUNTIME = {
    startedAt = os.time(),
    everOnline = false,
    lastOnlineAt = 0,
    disconnectSince = nil,
    unspawnedSince = nil,
    mismatchSince = nil,
    state = "STARTING",
    reason = "script_start",
    gamestate = -1,
    spawned = false,
    nick = "",
    server = "",
    port = 0,
    pid = 0,
    batConnected = false,
    threadStarted = false,
    lastWriteAt = 0
}

function arzWatchdogGetPid()
    if ARZ_WATCHDOG_KERNEL32_OK and ARZ_WATCHDOG_KERNEL32 then
        local ok, value = pcall(ARZ_WATCHDOG_KERNEL32.GetCurrentProcessId)
        if ok and tonumber(value) then return tonumber(value) end
    end
    return 0
end

function arzWatchdogBatIsConnected()
    local ok, modified = pcall(lfs.attributes, ARZ_WATCHDOG_BAT_HEARTBEAT_PATH, "modification")
    if not ok or tonumber(modified) == nil then return false end
    local age = os.time() - tonumber(modified)
    return age >= 0 and age <= ARZ_WATCHDOG_BAT_STALE_SECONDS
end

function arzWatchdogSafeGamestate()
    if type(sampGetGamestate) ~= "function" then return -1 end
    local ok, value = pcall(sampGetGamestate)
    return ok and tonumber(value) or -1
end

function arzWatchdogSafeSpawned()
    if type(sampIsLocalPlayerSpawned) == "function" then
        local ok, value = pcall(sampIsLocalPlayerSpawned)
        if ok then return value == true end
    end
    return doesCharExist(PLAYER_PED)
end

function arzWatchdogCurrentIdentity()
    local nick = ""
    local okId, playerId = pcall(function()
        local ok, id = sampGetPlayerIdByCharHandle(PLAYER_PED)
        if ok then return id end
        return nil
    end)
    if okId and playerId ~= nil then
        local okNick, value = pcall(sampGetPlayerNickname, playerId)
        if okNick and value then nick = tostring(value) end
    end

    local server, port = "", 0
    local okServer, address, serverPort = pcall(sampGetCurrentServerAddress)
    if okServer then
        server = tostring(address or "")
        port = tonumber(serverPort) or 0
    end
    return nick, server, port
end

function arzWatchdogEvaluate()
    local now = os.time()
    local rt = ARZ_WATCHDOG_RUNTIME
    local cfg = ARZ_WATCHDOG_CONFIG
    local gamestate = arzWatchdogSafeGamestate()
    local spawned = arzWatchdogSafeSpawned()
    local nick, server, port = arzWatchdogCurrentIdentity()

    rt.gamestate = gamestate
    rt.spawned = spawned
    rt.nick = nick
    rt.server = server
    rt.port = port
    rt.pid = arzWatchdogGetPid()
    rt.batConnected = arzWatchdogBatIsConnected()

    if not cfg.enabled then
        rt.state = "DISABLED"
        rt.reason = "watchdog_disabled"
        rt.disconnectSince = nil
        rt.unspawnedSince = nil
        rt.mismatchSince = nil
        return rt
    end

    if gamestate == 3 then
        rt.disconnectSince = nil

        local nickReady = cfg.nick == "" or nick == cfg.nick
        local serverReady = cfg.server == "" or server == cfg.server
        local portReady = not tonumber(cfg.port) or tonumber(cfg.port) <= 0 or port == tonumber(cfg.port)
        local nickMismatch = cfg.nick ~= "" and nick ~= "" and not nickReady
        local serverMismatch = cfg.server ~= "" and server ~= "" and not serverReady
        local portMismatch = tonumber(cfg.port) and tonumber(cfg.port) > 0 and port > 0 and not portReady

        if nickMismatch or serverMismatch or portMismatch then
            if rt.mismatchSince == nil then rt.mismatchSince = now end
            if now - rt.mismatchSince >= 5 then
                if nickMismatch then
                    rt.state = "WRONG_ACCOUNT"
                    rt.reason = "nick_mismatch"
                else
                    rt.state = "WRONG_SERVER"
                    rt.reason = serverMismatch and "server_mismatch" or "port_mismatch"
                end
                return rt
            end
        else
            rt.mismatchSince = nil
        end

        if spawned and nickReady and serverReady and portReady then
            rt.state = "ONLINE"
            rt.reason = "connected_and_spawned"
            rt.everOnline = true
            rt.lastOnlineAt = now
            rt.unspawnedSince = nil
            return rt
        end

        if not spawned or not nickReady or not serverReady or not portReady then
            if rt.unspawnedSince == nil then rt.unspawnedSince = now end
            local timeout = rt.everOnline and cfg.unspawned_timeout or cfg.startup_grace
            if now - rt.unspawnedSince >= timeout then
                rt.state = "NOT_LOGGED_IN"
                if not spawned then
                    rt.reason = rt.everOnline and "local_player_not_spawned" or "startup_spawn_timeout"
                else
                    rt.reason = "identity_timeout"
                end
            else
                rt.state = rt.everOnline and "WAIT_SPAWN" or "STARTING"
                rt.reason = not spawned and "waiting_for_spawn" or "identity_pending"
            end
            return rt
        end

        rt.state = "STARTING"
        rt.reason = "identity_pending"
        return rt
    end

    rt.unspawnedSince = nil
    rt.mismatchSince = nil
    if rt.disconnectSince == nil then rt.disconnectSince = now end

    local timeout = rt.everOnline and cfg.disconnect_timeout or cfg.startup_grace
    if now - rt.disconnectSince >= timeout then
        rt.state = "DISCONNECTED"
        rt.reason = "gamestate_" .. tostring(gamestate)
    else
        rt.state = rt.everOnline and "RECONNECTING" or "STARTING"
        rt.reason = "gamestate_" .. tostring(gamestate)
    end
    return rt
end

function arzWatchdogWriteState(forceState, forceReason)
    local rt = arzWatchdogEvaluate()
    local state = forceState or rt.state
    local reason = forceReason or rt.reason
    local content = table.concat({
        "state=" .. arzWatchdogSanitize(state),
        "reason=" .. arzWatchdogSanitize(reason),
        "pid=" .. tostring(math.floor(tonumber(rt.pid) or 0)),
        "heartbeat=" .. tostring(os.time()),
        "nick=" .. arzWatchdogSanitize(rt.nick),
        "expected_nick=" .. arzWatchdogSanitize(ARZ_WATCHDOG_CONFIG.nick),
        "server=" .. arzWatchdogSanitize(rt.server),
        "expected_server=" .. arzWatchdogSanitize(ARZ_WATCHDOG_CONFIG.server),
        "port=" .. tostring(math.floor(tonumber(rt.port) or 0)),
        "expected_port=" .. tostring(math.floor(tonumber(ARZ_WATCHDOG_CONFIG.port) or 0)),
        "gamestate=" .. tostring(math.floor(tonumber(rt.gamestate) or -1)),
        "spawned=" .. (rt.spawned and "1" or "0"),
        "bat_connected=" .. (rt.batConnected and "1" or "0"),
        "enabled=" .. (ARZ_WATCHDOG_CONFIG.enabled and "1" or "0"),
        "last_online=" .. tostring(math.floor(tonumber(rt.lastOnlineAt) or 0)),
        ""
    }, "\r\n")
    local ok = arzWatchdogAtomicWrite(ARZ_WATCHDOG_STATE_PATH, content)
    if ok then rt.lastWriteAt = os.time() end
    return ok
end

function arzWatchdogStart()
    if ARZ_WATCHDOG_RUNTIME.threadStarted then return end
    ARZ_WATCHDOG_RUNTIME.threadStarted = true
    ARZ_WATCHDOG_RUNTIME.startedAt = os.time()
    lua_thread.create(function()
        while true do
            arzWatchdogLoadConfig()
            ARZ_WATCHDOG_ENABLED_UI[0] = ARZ_WATCHDOG_CONFIG.enabled == true
            arzWatchdogWriteState()
            wait(ARZ_WATCHDOG_WRITE_INTERVAL_MS)
        end
    end)
end

function onExitScript(quitGame)
    if storageFinder and storageFinder.shutdown then
        pcall(storageFinder.shutdown)
    end
    if type(ARZ_WATCHDOG_RUNTIME) == "table" then
        pcall(arzWatchdogWriteState, "SCRIPT_STOPPED", quitGame and "game_exit" or "script_exit")
    end
    if type(arzAccountBridgeTick) == "function" then
        pcall(arzAccountBridgeTick)
    end
end


-- External account-role bridge used by Arizona Account Launcher.
-- A role is effective only while launcher_heartbeat.ini is fresh.
-- If the launcher is closed, killed, or crashes, Lua releases the role automatically.
ARZ_ACCOUNT_BRIDGE_FAILSAFE_VERSION = 3
ARZ_ACCOUNT_BRIDGE_PROTOCOL = 3
ARZ_ACCOUNT_BRIDGE_CONFIG_PATH = "moonloader/config/ArzMarket/account_bridge.ini"
ARZ_ACCOUNT_BRIDGE_SYNC_PATH = "moonloader/config/ArzMarket/donor_auth_sync.json"
ARZ_ACCOUNT_BRIDGE_HEARTBEAT_PATH = "moonloader/config/ArzMarket/launcher_heartbeat.ini"
ARZ_ACCOUNT_BRIDGE_RESTORE_STATE_PATH = "moonloader/config/ArzMarket/bridge_restore_state.ini"
ARZ_ACCOUNT_BRIDGE_MAIN_AUTH_BACKUP_PATH = "moonloader/config/ArzMarket/main_auth_restore.json"
ARZ_ACCOUNT_BRIDGE_ROLE_FLAG_PATH = "moonloader/config/ArzMarket/account_role.flag"
ARZ_ACCOUNT_BRIDGE_HEARTBEAT_STALE_SECONDS = 8
ARZ_ACCOUNT_BRIDGE_RUNTIME = {
    threadStarted = false,
    role = "NONE",
    effectiveRole = "NONE",
    lastVersion = "",
    session = "",
    active = false,
    launcherPid = 0,
    heartbeatAge = math.huge,
    lastReleaseReason = "startup"
}
ARZ_ACCOUNT_BRIDGE_CFG_NUMERIC = {
    premiumTokenAuth = true,
    lastUpdatePremiumToken = true,
    realMoneyNow = true,
    myBalanceArz = true
}
ARZ_ACCOUNT_BRIDGE_ANY_SECTION_AUTH_FIELDS = {
    "marketAuthKey", "marketAuthToken", "premiumToken", "premiumAuthToken",
    "userToken", "userAuthToken", "serverToken", "authKey"
}

function arzAccountBridgeReadText(path)
    local file = io.open(path, "rb")
    if not file then return nil end
    local raw = file:read("*a")
    file:close()
    return raw
end

function arzAccountBridgeReadKeyValue(path)
    local result = {}
    local file = io.open(path, "rb")
    if not file then return result end
    for line in file:lines() do
        line = tostring(line or ""):gsub("\r$", "")
        local key, value = line:match("^([%w_]+)=(.*)$")
        if key then result[key] = value end
    end
    file:close()
    return result
end

function arzAccountBridgeAtomicWrite(path, content)
    if type(arzScriptOfflineEnsureDirectory) == "function" then
        pcall(arzScriptOfflineEnsureDirectory)
    end
    local tempPath = path .. ".tmp"
    local file = io.open(tempPath, "wb")
    if not file then return false end
    local ok = pcall(function()
        file:write(tostring(content or ""))
        file:flush()
    end)
    pcall(file.close, file)
    if not ok then
        pcall(os.remove, tempPath)
        return false
    end
    if doesFileExist(path) then pcall(os.remove, path) end
    local renamed = os.rename(tempPath, path)
    if not renamed then
        pcall(os.remove, tempPath)
        return false
    end
    return true
end

function arzAccountBridgeLauncherState()
    local hb = arzAccountBridgeReadKeyValue(ARZ_ACCOUNT_BRIDGE_HEARTBEAT_PATH)
    local protocol = tonumber(hb.protocol) or 0
    local activeFlag = tostring(hb.active or "0") == "1"
    local timestamp = tonumber(hb.timestamp)
    local age = math.huge
    if timestamp ~= nil then age = os.time() - timestamp end
    local fresh = protocol == ARZ_ACCOUNT_BRIDGE_PROTOCOL
        and activeFlag and timestamp ~= nil
        and age >= -5
        and age <= ARZ_ACCOUNT_BRIDGE_HEARTBEAT_STALE_SECONDS
    local reason = "heartbeat_missing"
    if next(hb) ~= nil then
        if protocol ~= ARZ_ACCOUNT_BRIDGE_PROTOCOL then
            reason = "heartbeat_protocol_mismatch"
        elseif not activeFlag then
            reason = "launcher_inactive"
        elseif timestamp == nil then
            reason = "heartbeat_timestamp_missing"
        elseif age < -5 then
            reason = "heartbeat_clock_mismatch"
        elseif age > ARZ_ACCOUNT_BRIDGE_HEARTBEAT_STALE_SECONDS then
            reason = "heartbeat_stale"
        else
            reason = "launcher_alive"
        end
    end
    return {
        active = fresh,
        protocol = protocol,
        flag = activeFlag,
        timestamp = timestamp,
        age = age,
        pid = tonumber(hb.pid) or 0,
        session = tostring(hb.session or ""),
        reason = reason
    }
end

function arzAccountBridgeLoadRestoreState()
    return arzAccountBridgeReadKeyValue(ARZ_ACCOUNT_BRIDGE_RESTORE_STATE_PATH)
end

function arzAccountBridgeSessionKey(cfgSession, launcherState)
    cfgSession = tostring(cfgSession or "")
    if cfgSession ~= "" then return cfgSession end
    local hbSession = launcherState and tostring(launcherState.session or "") or ""
    if hbSession ~= "" then return hbSession end
    local pid = launcherState and tonumber(launcherState.pid) or 0
    if pid and pid > 0 then return "legacy_pid_" .. tostring(math.floor(pid)) end
    return "legacy"
end

function arzAccountBridgeCaptureRestoreState(session, role)
    local existing = arzAccountBridgeLoadRestoreState()
    local existingSession = tostring(existing.session or "")
    local existingRole = tostring(existing.role or ""):upper()
    -- Preserve the first standalone baseline until a bridge is fully released.
    -- This also survives a launcher restart that happens before Lua gets one cleanup tick.
    if tostring(existing.captured or "") == "1" then
        return existing
    end

    local content = table.concat({
        "captured=1",
        "session=" .. tostring(session or ""),
        "role=" .. tostring(role or "NONE"):upper(),
        "offline_before=" .. (ARZ_SCRIPT_OFFLINE and "1" or "0"),
        "lock_before=" .. (ARZ_INI_WRITE_LOCKED and "1" or "0"),
        "captured_at=" .. tostring(os.time()),
        ""
    }, "\r\n")
    if not arzAccountBridgeAtomicWrite(ARZ_ACCOUNT_BRIDGE_RESTORE_STATE_PATH, content) then
        return nil
    end
    return arzAccountBridgeReadKeyValue(ARZ_ACCOUNT_BRIDGE_RESTORE_STATE_PATH)
end

function arzAccountBridgeDeactivateRoleFile(expectedSession)
    local current = arzAccountBridgeReadKeyValue(ARZ_ACCOUNT_BRIDGE_CONFIG_PATH)
    local currentSession = tostring(current.session or "")
    expectedSession = tostring(expectedSession or "")
    if expectedSession ~= "" and currentSession ~= "" and currentSession ~= expectedSession then
        return false
    end
    local content = "protocol=" .. tostring(ARZ_ACCOUNT_BRIDGE_PROTOCOL) .. "\r\nrole=NONE\r\npaired=0\r\n"
    if expectedSession ~= "" then content = content .. "session=" .. expectedSession .. "\r\n" end
    local ok = arzAccountBridgeAtomicWrite(ARZ_ACCOUNT_BRIDGE_CONFIG_PATH, content)
    pcall(arzAccountBridgeAtomicWrite, ARZ_ACCOUNT_BRIDGE_ROLE_FLAG_PATH, "NONE\r\n")
    return ok
end

function arzAccountBridgeForceMainLock()
    if type(ini) ~= "table" or type(ini.cfg) ~= "table" then return false end
    ARZ_INI_WRITE_LOCKED = true
    ARZ_AUTH_FREEZE = {}
    arzIniCaptureLockSnapshot()
    arzIniPersistWriteLock(true)
    pcall(arzAuthFreezeProtectIni)
    pcall(arzApplySavedAuthRuntime)
    return true
end

function arzAccountBridgeApplySnapshot(snapshot)
    if type(snapshot) ~= "table" or type(snapshot.sections) ~= "table" then return false end
    if type(ini) ~= "table" then return false end

    for sectionName, values in pairs(snapshot.sections) do
        if type(values) == "table" then
            if type(ini[sectionName]) ~= "table" then ini[sectionName] = {} end
            for fieldName, rawValue in pairs(values) do
                local value = rawValue
                if sectionName == "cfg" and ARZ_ACCOUNT_BRIDGE_CFG_NUMERIC[fieldName] then
                    local numericValue = tonumber(rawValue)
                    if numericValue ~= nil then value = numericValue end
                else
                    value = tostring(rawValue or "")
                end
                ini[sectionName][fieldName] = value

                if type(ARZ_AUTH_FREEZE) == "table" then
                    if sectionName == "cfg" then
                        ARZ_AUTH_FREEZE["cfg:" .. tostring(fieldName)] = value
                    else
                        ARZ_AUTH_FREEZE["ini:" .. tostring(sectionName) .. ":" .. tostring(fieldName)] = value
                    end
                end
            end
        end
    end

    if inicfg.save(ini, iniPath) ~= true then return false end
    if ARZ_INI_WRITE_LOCKED then arzIniCaptureLockSnapshot() end

    if type(ini.cfg) == "table" and type(arzManualServerTokenBufferSet) == "function" then
        arzManualServerTokenBufferSet(ini.cfg.myServerToken or "")
    end
    pcall(arzApplySavedAuthRuntime)
    return true
end

function arzAccountBridgeLoadSnapshot()
    local raw = arzAccountBridgeReadText(ARZ_ACCOUNT_BRIDGE_SYNC_PATH)
    if not raw or raw == "" then return nil end
    local ok, decoded = pcall(decodeJson, raw)
    if not ok or type(decoded) ~= "table" then return nil end
    return decoded
end

function arzAccountBridgeRestoreMainAuthBackup()
    local raw = arzAccountBridgeReadText(ARZ_ACCOUNT_BRIDGE_MAIN_AUTH_BACKUP_PATH)
    if not raw or raw == "" then return false end
    local ok, backup = pcall(decodeJson, raw)
    if not ok or type(backup) ~= "table" then return false end
    if type(ini) ~= "table" then return false end

    if type(backup.sections) == "table" then
        for sectionName, values in pairs(backup.sections) do
            if type(values) == "table" then
                if type(ini[sectionName]) ~= "table" then ini[sectionName] = {} end
                for fieldName, rawValue in pairs(values) do
                    local value = rawValue
                    if sectionName == "cfg" and ARZ_ACCOUNT_BRIDGE_CFG_NUMERIC[fieldName] then
                        local numericValue = tonumber(rawValue)
                        if numericValue ~= nil then value = numericValue end
                    else
                        value = tostring(rawValue or "")
                    end
                    ini[sectionName][fieldName] = value
                end
            end
        end
    end

    local representedSections = {}
    if type(backup.sections) == "table" then
        for sectionName in pairs(backup.sections) do representedSections[tostring(sectionName)] = true end
    end
    if type(backup.missing) == "table" then
        for sectionName, values in pairs(backup.missing) do
            representedSections[tostring(sectionName)] = true
            if type(values) == "table" and type(ini[sectionName]) == "table" then
                for fieldName, isMissing in pairs(values) do
                    if isMissing == true or tostring(isMissing) == "1" or tostring(isMissing) == "true" then
                        ini[sectionName][fieldName] = nil
                    end
                end
            end
        end
    end

    -- A donor snapshot can introduce an auth-only section that did not exist in MAIN.
    -- Remove only known auth fields from such sections, leaving unrelated settings intact.
    for sectionName, section in pairs(ini) do
        if type(section) == "table" and not representedSections[tostring(sectionName)] then
            for _, fieldName in ipairs(ARZ_ACCOUNT_BRIDGE_ANY_SECTION_AUTH_FIELDS) do
                if section[fieldName] ~= nil then section[fieldName] = nil end
            end
        end
    end

    if inicfg.save(ini, iniPath) ~= true then return false end
    if ARZ_INI_WRITE_LOCKED then arzIniCaptureLockSnapshot() end
    pcall(os.remove, ARZ_ACCOUNT_BRIDGE_MAIN_AUTH_BACKUP_PATH)
    pcall(arzApplySavedAuthRuntime)
    return true
end

function arzAccountBridgeRelease(previousRole, expectedSession, reason)
    previousRole = tostring(previousRole or "NONE"):upper()
    expectedSession = tostring(expectedSession or "")

    -- Keep the current live session intact, but allow cleanup of an older session.
    local launcherState = arzAccountBridgeLauncherState()
    local launcherSession = tostring(launcherState.session or "")
    if launcherState.active
        and (expectedSession == "" or launcherSession == "" or launcherSession == expectedSession) then
        return false
    end

    local restore = arzAccountBridgeLoadRestoreState()
    local restoreRole = tostring(restore.role or ""):upper()
    local restoreSession = tostring(restore.session or "")
    if previousRole == "NONE" and (restoreRole == "MAIN" or restoreRole == "DONOR") then
        previousRole = restoreRole
    end
    if expectedSession == "" then expectedSession = restoreSession end

    local stateMatches = tostring(restore.captured or "") == "1"
    local offlineBefore = false
    local lockBefore = false
    if stateMatches then
        offlineBefore = tostring(restore.offline_before or "0") == "1"
        lockBefore = tostring(restore.lock_before or "0") == "1"
    end

    if previousRole == "MAIN" or restoreRole == "MAIN" then
        pcall(arzAccountBridgeRestoreMainAuthBackup)
    end

    -- Old builds had no restore-state file. In that migration case, recover to
    -- normal standalone ArzMarket behavior: online and receiving account data.
    if not stateMatches then
        offlineBefore = false
        lockBefore = false
    end

    if ARZ_SCRIPT_OFFLINE ~= offlineBefore then
        pcall(arzScriptOfflineSet, offlineBefore)
    end

    if lockBefore then
        if not ARZ_INI_WRITE_LOCKED then
            pcall(arzStopReceivingAccountData)
        else
            pcall(arzIniCaptureLockSnapshot)
        end
    else
        if ARZ_INI_WRITE_LOCKED then
            pcall(arzStartReceivingAccountData)
        elseif type(arzApplyLastSeenServerToken) == "function" then
            pcall(arzApplyLastSeenServerToken)
        end
    end

    if (previousRole == "MAIN" or restoreRole == "MAIN") and doesFileExist(ARZ_ACCOUNT_BRIDGE_SYNC_PATH) then
        pcall(os.remove, ARZ_ACCOUNT_BRIDGE_SYNC_PATH)
    end
    if doesFileExist(ARZ_ACCOUNT_BRIDGE_RESTORE_STATE_PATH) then
        pcall(os.remove, ARZ_ACCOUNT_BRIDGE_RESTORE_STATE_PATH)
    end
    pcall(arzAccountBridgeDeactivateRoleFile, expectedSession)

    ARZ_ACCOUNT_BRIDGE_RUNTIME.role = "NONE"
    ARZ_ACCOUNT_BRIDGE_RUNTIME.effectiveRole = "NONE"
    ARZ_ACCOUNT_BRIDGE_RUNTIME.lastVersion = ""
    ARZ_ACCOUNT_BRIDGE_RUNTIME.session = ""
    ARZ_ACCOUNT_BRIDGE_RUNTIME.active = false
    ARZ_ACCOUNT_BRIDGE_RUNTIME.launcherPid = 0
    ARZ_ACCOUNT_BRIDGE_RUNTIME.heartbeatAge = math.huge
    ARZ_ACCOUNT_BRIDGE_RUNTIME.lastReleaseReason = tostring(reason or launcherState.reason or "launcher_stopped")
    return true
end

function arzAccountBridgeTick()
    local cfg = arzAccountBridgeReadKeyValue(ARZ_ACCOUNT_BRIDGE_CONFIG_PATH)
    local requestedRole = tostring(cfg.role or "NONE"):upper()
    local cfgProtocol = tonumber(cfg.protocol) or 0
    local cfgSession = tostring(cfg.session or "")
    local launcherState = arzAccountBridgeLauncherState()
    local heartbeatSession = tostring(launcherState.session or "")
    local sessionsCompatible = cfgSession ~= "" and heartbeatSession ~= "" and cfgSession == heartbeatSession
    local protocolCompatible = cfgProtocol == ARZ_ACCOUNT_BRIDGE_PROTOCOL
        and launcherState.protocol == ARZ_ACCOUNT_BRIDGE_PROTOCOL
    local roleValid = requestedRole == "MAIN" or requestedRole == "DONOR"
    local bridgeActive = launcherState.active and protocolCompatible and sessionsCompatible and roleValid

    ARZ_ACCOUNT_BRIDGE_RUNTIME.role = requestedRole
    ARZ_ACCOUNT_BRIDGE_RUNTIME.launcherPid = tonumber(launcherState.pid) or 0
    ARZ_ACCOUNT_BRIDGE_RUNTIME.heartbeatAge = launcherState.age

    if not bridgeActive then
        local previousRole = tostring(ARZ_ACCOUNT_BRIDGE_RUNTIME.effectiveRole or "NONE"):upper()
        local restore = arzAccountBridgeLoadRestoreState()
        local restoreRole = tostring(restore.role or "NONE"):upper()
        if previousRole == "NONE" and roleValid then previousRole = requestedRole end
        if previousRole == "NONE" and (restoreRole == "MAIN" or restoreRole == "DONOR") then previousRole = restoreRole end

        if previousRole == "MAIN" or previousRole == "DONOR" then
            local reason = launcherState.reason
            if launcherState.active and not protocolCompatible then reason = "bridge_protocol_mismatch" end
            if launcherState.active and protocolCompatible and not sessionsCompatible then reason = "launcher_session_mismatch" end
            if launcherState.active and protocolCompatible and sessionsCompatible and not roleValid then reason = "bridge_role_missing" end
            arzAccountBridgeRelease(previousRole, cfgSession, reason)
        else
            ARZ_ACCOUNT_BRIDGE_RUNTIME.effectiveRole = "NONE"
            ARZ_ACCOUNT_BRIDGE_RUNTIME.active = false
            if not ARZ_INI_WRITE_LOCKED and type(arzApplyLastSeenServerToken) == "function" then
                pcall(arzApplyLastSeenServerToken)
            end
        end
        return
    end

    local sessionKey = arzAccountBridgeSessionKey(cfgSession, launcherState)
    if ARZ_ACCOUNT_BRIDGE_RUNTIME.session ~= sessionKey then
        ARZ_ACCOUNT_BRIDGE_RUNTIME.lastVersion = ""
        ARZ_ACCOUNT_BRIDGE_RUNTIME.session = sessionKey
    end
    ARZ_ACCOUNT_BRIDGE_RUNTIME.active = true
    ARZ_ACCOUNT_BRIDGE_RUNTIME.effectiveRole = requestedRole

    -- Capture the standalone state before the bridge changes Offline/INI lock.
    arzAccountBridgeCaptureRestoreState(sessionKey, requestedRole)

    if requestedRole == "MAIN" then
        if ARZ_SCRIPT_OFFLINE then pcall(arzScriptOfflineSet, false) end

        local snapshot = arzAccountBridgeLoadSnapshot()
        if type(snapshot) == "table" then
            local snapshotSession = tostring(snapshot.session or "")
            local snapshotAllowed = snapshotSession == "" or cfgSession == "" or snapshotSession == cfgSession
            if snapshotAllowed then
                local version = tostring(snapshot.version or "")
                if version ~= "" and version ~= ARZ_ACCOUNT_BRIDGE_RUNTIME.lastVersion then
                    if arzAccountBridgeApplySnapshot(snapshot) then
                        ARZ_ACCOUNT_BRIDGE_RUNTIME.lastVersion = version
                    end
                end
            end
        end

        if not ARZ_INI_WRITE_LOCKED then
            arzAccountBridgeForceMainLock()
        end
    elseif requestedRole == "DONOR" then
        if not ARZ_SCRIPT_OFFLINE then pcall(arzScriptOfflineSet, true) end
        if ARZ_INI_WRITE_LOCKED then
            pcall(arzStartReceivingAccountData)
        elseif type(arzApplyLastSeenServerToken) == "function" then
            pcall(arzApplyLastSeenServerToken)
        end
    end
end

function arzAccountBridgeStart()
    if ARZ_ACCOUNT_BRIDGE_RUNTIME.threadStarted then return end
    ARZ_ACCOUNT_BRIDGE_RUNTIME.threadStarted = true
    -- Run one tick synchronously so stale DONOR offline/lock state is released
    -- before normal startup code can issue Marketplace/Premium HTTP requests.
    pcall(arzAccountBridgeTick)
    lua_thread.create(function()
        while true do
            wait(1000)
            pcall(arzAccountBridgeTick)
        end
    end)
end

