local AUTO_PIAR_COMMANDS = {
	"/vr", "/ad", "/j", "/jb", "/r", "/rb", "/f", "/fb", "/al", "/g", "/d", "/s", "/fam"
}
local LEGACY_AUTO_PIAR_COMMANDS = { [0] = "/vr", [1] = "/ad", [2] = "/s", [3] = "/al", [4] = "/fam" }
local AUTO_PIAR_COMMAND_INDEX = {}

for commandIndex, commandName in ipairs(AUTO_PIAR_COMMANDS) do
	AUTO_PIAR_COMMAND_INDEX[commandName] = commandIndex - 1
end

local function createAutoAdCommandSettings(command)
	local settings = { isCounter = { count = 99, status = false } }

	if command == "/vr" then
		settings.isADVIP = true
	elseif command == "/ad" then
		settings.isRadioStation = 0
		settings.isVipAd = false
		settings.isRetry = { osTime = -1, retryTime = 35, status = true }
	end

	return settings
end

local function normalizeAutoAdProfile(profile)
	local changed = false

	if type(profile.uid) ~= "string" or not profile.uid:match("^ad_[%w_%-]+$") then
		profile.uid = "ad_" .. tostring(os.time()) .. "_" .. tostring(math.floor(os.clock() * 1000000)) .. "_" .. tostring(math.random(1000, 9999))
		changed = true
	end
	local legacyType = tonumber(profile.isType) or 0
	local command = profile.command

	if AUTO_PIAR_COMMAND_INDEX[command] == nil then
		command = LEGACY_AUTO_PIAR_COMMANDS[legacyType] or "/vr"
		profile.command = command
		changed = true
	end

	profile.settingsAd = type(profile.settingsAd) == "table" and profile.settingsAd or {}
	profile.settingsAdByCommand = type(profile.settingsAdByCommand) == "table" and profile.settingsAdByCommand or {}

	for oldType, oldCommand in pairs(LEGACY_AUTO_PIAR_COMMANDS) do
		if profile.settingsAdByCommand[oldCommand] == nil and type(profile.settingsAd[tostring(oldType)]) == "table" then
			profile.settingsAdByCommand[oldCommand] = profile.settingsAd[tostring(oldType)]
			changed = true
		end
	end

	for _, supportedCommand in ipairs(AUTO_PIAR_COMMANDS) do
		local settings = profile.settingsAdByCommand[supportedCommand]

		if type(settings) ~= "table" then
			settings = createAutoAdCommandSettings(supportedCommand)
			profile.settingsAdByCommand[supportedCommand] = settings
			changed = true
		end

		if type(settings.isCounter) ~= "table" then
			settings.isCounter = { count = 99, status = false }
			changed = true
		end

		settings.isCounter.count = tonumber(settings.isCounter.count) or 99
		settings.isCounter.status = settings.isCounter.status == true
	end

	local vrSettings = profile.settingsAdByCommand["/vr"]
	local adSettings = profile.settingsAdByCommand["/ad"]
	vrSettings.isADVIP = vrSettings.isADVIP ~= false
	adSettings.isRadioStation = tonumber(adSettings.isRadioStation) or 0
	adSettings.isVipAd = adSettings.isVipAd == true
	adSettings.isRetry = type(adSettings.isRetry) == "table" and adSettings.isRetry or { osTime = -1, retryTime = 35, status = true }
	adSettings.isRetry.osTime = tonumber(adSettings.isRetry.osTime) or -1
	adSettings.isRetry.retryTime = tonumber(adSettings.isRetry.retryTime) or 35
	adSettings.isRetry.status = adSettings.isRetry.status == true

	profile.command = command

	if profile.isType ~= AUTO_PIAR_COMMAND_INDEX[command] then
		profile.isType = AUTO_PIAR_COMMAND_INDEX[command]
		changed = true
	end

	for commandIndex, supportedCommand in ipairs(AUTO_PIAR_COMMANDS) do
		profile.settingsAd[tostring(commandIndex - 1)] = profile.settingsAdByCommand[supportedCommand]
	end

	return command, profile.settingsAdByCommand[command], changed
end

local function createAutoAdProfile()
	local profile = { command = "/vr", isType = 0, isTimer = 0, isPiarText = "", osTime = -1, isEnabled = false, settingsAd = {}, settingsAdByCommand = {} }
	normalizeAutoAdProfile(profile)
	return profile
end

