function arzPaletteClamp(value)
	value = tonumber(value) or 0
	if value < 0 then return 0 end
	if value > 1 then return 1 end
	return value
end

function arzPaletteHex(hex, alpha)
	local value = tostring(hex or "#000000"):gsub("#", "")
	local r = (tonumber(value:sub(1, 2), 16) or 0) / 255
	local g = (tonumber(value:sub(3, 4), 16) or 0) / 255
	local b = (tonumber(value:sub(5, 6), 16) or 0) / 255
	return { r, g, b, alpha ~= nil and alpha or 1 }
end

function arzPaletteMix(first, second, amount, alpha)
	local t = arzPaletteClamp(amount or 0)
	local k = 1 - t
	return {
		arzPaletteClamp((first[1] or 0) * k + (second[1] or 0) * t),
		arzPaletteClamp((first[2] or 0) * k + (second[2] or 0) * t),
		arzPaletteClamp((first[3] or 0) * k + (second[3] or 0) * t),
		alpha ~= nil and alpha or 1
	}
end

