AVG_PRICE_SOURCE_STATE_PATH = getWorkingDirectory() .. "\\ArzMarket\\average_price_sources.json"

function avgPriceBoolValue(value, defaultValue)
	if value == true or value == 1 or value == "1" then return true end
	if value == false or value == 0 or value == "0" then return false end
	local text = tostring(value or ""):lower()
	if text == "true" then return true end
	if text == "false" then return false end
	return defaultValue == true
end

function avgPriceLoadPersistedSourceState()
	local defaults = {
		buy_ = avgPriceBoolValue(ini.cfg.avg_price_buy_sa, false),
		buy_vc = avgPriceBoolValue(ini.cfg.avg_price_buy_vc, false),
		sell_ = avgPriceBoolValue(ini.cfg.avg_price_sell_sa, false),
		sell_vc = avgPriceBoolValue(ini.cfg.avg_price_sell_vc, false)
	}
	if not doesFileExist(AVG_PRICE_SOURCE_STATE_PATH) then
		return defaults
	end
	local ok, data = pcall(readJsonFile, AVG_PRICE_SOURCE_STATE_PATH, {})
	if not ok or type(data) ~= "table" then
		return defaults
	end
	for key, defaultValue in pairs(defaults) do
		data[key] = avgPriceBoolValue(data[key], defaultValue)
	end
	return data
end

AVG_PRICE_SOURCE_PERSISTED = avgPriceLoadPersistedSourceState()

function avgPricePersistSourceState()
	local payload = {}
	if type(avgPriceSourceEnabled) == "table" then
		for _, key in ipairs({ "buy_", "buy_vc", "sell_", "sell_vc" }) do
			local state = avgPriceSourceEnabled[key]
			payload[key] = state ~= nil and state[0] == true or false
		end
	else
		payload = AVG_PRICE_SOURCE_PERSISTED or {}
	end
	local ok = writeJsonFile(payload, AVG_PRICE_SOURCE_STATE_PATH)
	if ok then
		AVG_PRICE_SOURCE_PERSISTED = payload
	end
	return ok == true
end

-- Independent average-price sources. Disabled sources are removed from priceData
-- and are not decoded during manual price downloads. This keeps large history
-- tables out of the LuaJIT heap until the user explicitly enables them.
avgPriceSourceEnabled = {
	buy_ = imguiNew.bool(AVG_PRICE_SOURCE_PERSISTED.buy_ == true),
	buy_vc = imguiNew.bool(AVG_PRICE_SOURCE_PERSISTED.buy_vc == true),
	sell_ = imguiNew.bool(AVG_PRICE_SOURCE_PERSISTED.sell_ == true),
	sell_vc = imguiNew.bool(AVG_PRICE_SOURCE_PERSISTED.sell_vc == true)
}

avgPriceSourceIniKey = {
	buy_ = "avg_price_buy_sa",
	buy_vc = "avg_price_buy_vc",
	sell_ = "avg_price_sell_sa",
	sell_vc = "avg_price_sell_vc"
}

avgPriceSourceLoading = {
	buy_ = false,
	buy_vc = false,
	sell_ = false,
	sell_vc = false
}

function avgPriceSourceIsEnabled(sourceKey)
	local state = avgPriceSourceEnabled[sourceKey]
	return state ~= nil and state[0] == true
end

function avgPriceDetectServerSlug()
	local serverName = sampGetCurrentServerName()
	if type(serverName) ~= "string" or not serverName:find("Arizona") then
		return nil
	end

	local nickname = ""
	local playerIdOk, playerId = sampGetPlayerIdByCharHandle(PLAYER_PED)
	if playerIdOk then
		local okNick, value = pcall(sampGetPlayerNickname, playerId)
		if okNick and value then
			nickname = tostring(value)
		end
	end

	local viceCityServerId = nickname:match("%[(%-?%d+)%]")
	local detectedServerSlug = viceCityServerId ~= nil and serverSlugById[viceCityServerId]
		or serverName:match("|%s*(.+)% |")
		or serverName:match("|%s*(.+)")

	if detectedServerSlug == nil or detectedServerSlug == "" then
		return nil
	end

	return string.lower(detectedServerSlug):gsub(" ", "-")
end

function avgPriceGetSourcePath(sourceKey)
	local baseDir = getWorkingDirectory() .. "/ArzMarket/UsersInfo/"

	if sourceKey == "buy_vc" then
		return baseDir .. "info_users_buy_vc.json"
	elseif sourceKey == "sell_vc" then
		return baseDir .. "info_users_sell_vc.json"
	end

	local serverSlug = avgPriceDetectServerSlug()
	if not serverSlug then
		return nil
	end

	if sourceKey == "buy_" then
		return baseDir .. "info_users_buy_" .. serverSlug .. ".json"
	elseif sourceKey == "sell_" then
		return baseDir .. "info_users_sell_" .. serverSlug .. ".json"
	end

	return nil
end

function avgPriceLoadSourceFromDisk(sourceKey)
	if not avgPriceSourceIsEnabled(sourceKey) then
		return false, "disabled"
	end

	local current = priceData[sourceKey]
	if type(current) == "table" and next(current) ~= nil then
		return true
	end

	local path = avgPriceGetSourcePath(sourceKey)
	if not path or not doesFileExist(path) then
		priceData[sourceKey] = nil
		return false, "cache_missing"
	end

	local okLoad, loaded = pcall(readJsonFile, path, {})
	if not avgPriceSourceIsEnabled(sourceKey) then
		loaded = nil
		priceData[sourceKey] = nil
		return false, "disabled"
	end

	if okLoad and type(loaded) == "table" and next(loaded) ~= nil then
		priceData[sourceKey] = loaded
		return true
	end

	priceData[sourceKey] = nil
	return false, "cache_invalid"
end

function avgPriceSetSourceEnabled(sourceKey, enabled)
	local state = avgPriceSourceEnabled[sourceKey]
	local iniKey = avgPriceSourceIniKey[sourceKey]
	if state == nil or iniKey == nil then
		return
	end

	enabled = enabled == true
	state[0] = enabled
	ini.cfg[iniKey] = enabled
	avgPricePersistSourceState()

	if not enabled then
		avgPriceSourceLoading[sourceKey] = false
		priceData[sourceKey] = nil

		-- Release the detached history incrementally to avoid one long GC pause.
		lua_thread.create(function()
			if type(averagePriceGcStep) == "function" then
				averagePriceGcStep(12)
			else
				for _ = 1, 12 do
					pcall(collectgarbage, "step", 128)
					wait(0)
				end
			end
		end)
	else
		if not avgPriceSourceLoading[sourceKey] then
			avgPriceSourceLoading[sourceKey] = true
			lua_thread.create(function()
				local okCall, loaded = pcall(avgPriceLoadSourceFromDisk, sourceKey)
				avgPriceSourceLoading[sourceKey] = false

				if not okCall or loaded ~= true then
					pcall(sendNotify, u8:decode("Нет кэша средних цен. Нажмите загрузку цен."))
				end
			end)
		end
	end

	if type(save_all) == "function" then
		pcall(save_all)
	end
end

