-- The old scale wrapper enlarged fixed button widths while the legacy pages
-- still positioned neighbours with their original X coordinates. That caused
-- toolbar buttons, filters and borders to overlap at 125-150% UI scale.
-- Keep page-calculated widths intact and scale only the vertical button size.
do
	local baseButton = imgui.__ArzMarketBaseButton or imgui.Button
	imgui.__ArzMarketBaseButton = baseButton
	imgui.Button = function(label, size)
		if size ~= nil then
			local scale = getMenuUiScale()
			local width = tonumber(size.x) or 0
			local height = tonumber(size.y) or 0

			if width > 0 then
				local available = tonumber(imgui.GetContentRegionAvail().x) or width
				if available > 0 then
					width = math.min(width, available)
				end
			end

			if height > 0 then
				height = height * scale
			end

			return baseButton(label, imgui.ImVec2(width, height))
		end
		return baseButton(label)
	end
end


-- Storage CEF packets usually contain an item ID, not a display name.
-- Resolve the ID through the same ArzMarket items_data table used by Marketplace.
ARZ_STORAGE_ITEM_NAME_RESOLVER = function(itemId, rawItem)
    local key = tostring(itemId or "")
    if key == "" then return nil end

    if type(marketState) == "table" then
        marketState.itemsMarketData = type(marketState.itemsMarketData) == "table" and marketState.itemsMarketData or {}
        if next(marketState.itemsMarketData) == nil then
            local itemsPath = getWorkingDirectory() .. "/ArzMarket/items_data" .. tostring(ini.cfg.lastItemsUpdate or 0) .. ".json"
            if doesFileExist(itemsPath) then
                local loaded = readJsonFile(itemsPath)
                if type(loaded) == "table" then
                    marketState.itemsMarketData = loaded
                end
            end
        end

        local mappedName = marketState.itemsMarketData[key]
        if type(mappedName) == "string" and mappedName ~= "" and mappedName ~= "DELETED" then
            return mappedName
        end
    end

    return nil
end

