function modificationState.persistMainWindowSize(forceSave)
	local width = tonumber(modificationState.uiLastWindowWidth)
	local height = tonumber(modificationState.uiLastWindowHeight)

	if width == nil or height == nil then
		return false
	end

	width = math.max(830, math.min(10000, math.floor(width + 0.5)))
	height = math.max(550, math.min(10000, math.floor(height + 0.5)))

	if type(windowThemeConfig.mainWindowSize) ~= "table" then
		windowThemeConfig.mainWindowSize = {
			x = 830,
			y = 550
		}
	end

	local oldWidth = tonumber(windowThemeConfig.mainWindowSize.x) or 830
	local oldHeight = tonumber(windowThemeConfig.mainWindowSize.y) or 550

	if not forceSave and oldWidth == width and oldHeight == height then
		modificationState.uiWindowSizeDirty = false
		return true
	end

	windowThemeConfig.mainWindowSize.x = width
	windowThemeConfig.mainWindowSize.y = height

	local saved = writeJsonFile(windowThemeConfig, windowThemePath) == true

	if saved then
		modificationState.uiWindowSizeDirty = false
	end

	return saved
end
