lrendScanState = {
	active = false,
	nextId = 0,
	found = {}
}
LREND_SCAN_CHUNK = 128
LREND_SCAN_INTERVAL = 0.75

local function updateLrendPoints()
	if not modificationState.lrendEnabled[0] then
		lrendScanState.active = false
		lrendScanState.nextId = 0
		lrendScanState.found = {}
		return
	end

	local now = os.clock()
	if not lrendScanState.active then
		if now < modificationState.lrendNextScan then
			return
		end
		lrendScanState.active = true
		lrendScanState.nextId = 0
		lrendScanState.found = {}
	end

	local firstId = lrendScanState.nextId
	local lastId = math.min(2304, firstId + LREND_SCAN_CHUNK - 1)
	for textId = firstId, lastId do
		if sampIs3dTextDefined(textId) then
			local ok, text, textColor, pointX, pointY, pointZ = pcall(sampGet3dTextInfoById, textId)
			if ok and text == "" and pointZ and math.floor(pointZ) == 17 then
				lrendScanState.found[#lrendScanState.found + 1] = { x = pointX, y = pointY, z = pointZ }
			end
		end
	end

	lrendScanState.nextId = lastId + 1
	if lrendScanState.nextId > 2304 then
		modificationState.lrendPoints = lrendScanState.found
		lrendScanState.active = false
		lrendScanState.nextId = 0
		lrendScanState.found = {}
		modificationState.lrendNextScan = now + LREND_SCAN_INTERVAL
	end
end

local function renderLrendPoints()
	if not modificationState.lrendEnabled[0] or not modificationState.lrendFont then
		return
	end

	local playerX, playerY, playerZ = getCharCoordinates(PLAYER_PED)
	local playerScreenX, playerScreenY = convert3DCoordsToScreen(playerX, playerY, playerZ)
	local green = 4278255360

	for _, point in ipairs(modificationState.lrendPoints) do
		if isPointOnScreen(point.x, point.y, point.z, 1) then
			local screenX, screenY = convert3DCoordsToScreen(point.x, point.y, point.z)

			renderFontDrawText(modificationState.lrendFont, u8:decode("Свободна"), screenX + 6, screenY - 14, green, true)
			renderDrawLine(playerScreenX, playerScreenY, screenX, screenY, 2, green)
			renderDrawBox(screenX - 3, screenY - 3, 6, 6, green)
			renderDrawBox(playerScreenX - 2, playerScreenY - 2, 4, 4, green)
		end
	end
end

