		local currentClock = os.clock()
		local notificationIndexesToRemove = {}
		local visibleNotificationCount = 0
		local disappearingNotifications = {}

		for notificationIndex, notification in ipairs(marketState.notifications) do
			if notification.state == "disappearing" then
				table.insert(disappearingNotifications, {
					index = notificationIndex,
					start_time = notification.start_time,
					y_pos = notification.y_pos,
					alpha = notification.alpha
				})
			elseif notification.state ~= "disappearing" then
				visibleNotificationCount = visibleNotificationCount + 1
			end
		end

		for notificationIndex = #marketState.notifications, 1, -1 do
			local notification = marketState.notifications[notificationIndex]
			local notificationElapsedTime = currentClock - notification.start_time

			notification.target_y = marketState.BASE_Y_POS

			local precedingVisibleCount = 0

			for precedingIndex = 1, notificationIndex - 1 do
				local precedingNotification = marketState.notifications[precedingIndex]

				if precedingNotification.state ~= "disappearing" or precedingNotification.alpha > 0 then
					precedingVisibleCount = precedingVisibleCount + 1
					notification.target_y = marketState.BASE_Y_POS + precedingVisibleCount * marketState.SPACING
				end
			end

			local springAcceleration = (notification.target_y - notification.y_pos) * marketState.SPRING_TENSION

			notification.velocity = notification.velocity * marketState.SPRING_DAMPING + springAcceleration
			notification.y_pos = notification.y_pos + notification.velocity

			if notification.state == "appearing" then
				notification.alpha = math.min(notification.alpha + 0.02 * (2 / marketState.FADE_TIME), 1)
				notification.spring_velocity = notification.spring_velocity - notification.spring_offset * 0.1
				notification.spring_offset = notification.spring_offset + notification.spring_velocity
				notification.spring_velocity = notification.spring_velocity * 0.9

				if math.abs(notification.y_pos - notification.target_y) < marketState.MIN_DISTANCE and notification.alpha == 1 then
					notification.state = "showing"
					notification.start_time = currentClock
				end
			elseif notification.state == "showing" then
				if notificationElapsedTime >= marketState.SHOW_DURATION then
					notification.state = "disappearing"
					notification.start_time = currentClock
				end
			elseif notification.state == "disappearing" then
				notification.alpha = math.max(notification.alpha - 0.02 * (2 / marketState.FADE_TIME), 0)

				if notification.alpha <= 0 then
					table.insert(notificationIndexesToRemove, notificationIndex)
				end
			end

			if notification.alpha > 0 then
				local notificationX = (marketState.ScreenResolution.x - notification.text_width) / 2
				local notificationY = notification.y_pos + notification.spring_offset
				local notificationColor = 16777215 + math.floor(notification.alpha * 255) * 16777216

