					else
						SendToServer(command .. " " .. adProfile.isPiarText)
					end

					break
				end

				if adProfile.isEnabled and command == "/ad" and commandSettings.isRetry.status and (commandSettings.isRetry.osTime == -1 or os.time() - commandSettings.isRetry.osTime > commandSettings.isRetry.retryTime) then
					adProfile.osTime = os.time()
					commandSettings.isRetry.osTime = os.time()
					marketState.send_adControl = { active = true, uid = profileName, timer = os.time() }
					SendToServer(command .. " " .. adProfile.isPiarText)
					break
				end
			end
		end
	end
end

function arzCompareVersions(leftVersion, rightVersion)
	local leftParts = {}
	local rightParts = {}
	for part in tostring(leftVersion or ""):gmatch("%d+") do
		leftParts[#leftParts + 1] = tonumber(part) or 0
	end
	for part in tostring(rightVersion or ""):gmatch("%d+") do
		rightParts[#rightParts + 1] = tonumber(part) or 0
	end
	if #leftParts == 0 or #rightParts == 0 then
		return nil
	end
	local count = math.max(#leftParts, #rightParts)
	for i = 1, count do
		local left = leftParts[i] or 0
		local right = rightParts[i] or 0
		if left > right then return 1 end
		if left < right then return -1 end
	end
	return 0
end

function autoUpdateCheckUrl()
	print("isUpdate?")
	asyncHttpRequest("GET", "https://raw.githubusercontent.com/FREYM1337/forumnick/main/ArzMarketV3/updateArzMarket.js", {}, function(updateCheckResponse)
		if updateCheckResponse.status_code == 200 or updateCheckResponse.status_code == 304 then
			local updateInfo, decodeError = decodeJsonSafe(updateCheckResponse.text)

			if type(updateInfo) == "table" then
				print("success updated. " .. tostring(ini.cfg.lastItemsUpdate))

				marketState.scriptVersion[3] = updateInfo
				local currentVersion = tostring(marketState.scriptVersion[1] or "")
				local latestVersion = tostring(updateInfo.latest or "")
				local compareResult = arzCompareVersions(latestVersion, currentVersion)
				local hasUpdateUrl = type(updateInfo.updateurl) == "string" and updateInfo.updateurl ~= ""

				if compareResult == 1 and hasUpdateUrl then
					deAFKMessage("[+] new version > " .. currentVersion .. " | " .. latestVersion)
					marketState.scriptVersion[2] = true
				else
					marketState.scriptVersion[2] = false
					deAFKMessage("[-] no newer version > " .. currentVersion .. " | " .. latestVersion)
				end

				local remoteItemsUpdate = tonumber(updateInfo.itemsUpdate)
				local localItemsUpdate = tonumber(ini.cfg.lastItemsUpdate) or 0
				if remoteItemsUpdate and remoteItemsUpdate > localItemsUpdate and doesFileExist(getWorkingDirectory() .. "/ArzMarket/items_data" .. tostring(ini.cfg.lastItemsUpdate) .. ".json") then
					print("removed items")
					os.remove(getWorkingDirectory() .. "/ArzMarket/items_data" .. tostring(ini.cfg.lastItemsUpdate) .. ".json")
				end
			else
				marketState.scriptVersion[2] = false
				deAFKMessage("update json decode error: " .. tostring(decodeError))
			end
		else
			marketState.scriptVersion[2] = false
			deAFKMessage(debug.getinfo(1, "l"), "error1 autoUpdateCheckUrl " .. tostring(updateCheckResponse.status_code))
		end
	end, function(updateCheckError)
		marketState.scriptVersion[2] = false
		deAFKMessage(debug.getinfo(1, "l"), "error2 autoUpdateCheckUrl " .. tostring(updateCheckError))
	end)
end

function arzSavedCfgValue(fieldName, fallbackValue)
	if type(ini) ~= "table" or type(ini.cfg) ~= "table" then
		return fallbackValue
	end

	local value = ini.cfg[fieldName]
	if value == nil then
		return fallbackValue
	end

	return value
end

function arzSavedCfgString(fieldName)
	local value = arzSavedCfgValue(fieldName, "")
	if value == nil then return "" end
	return tostring(value)
end

function arzApplySavedAuthRuntime()
	if type(marketState) ~= "table" then return end
	marketState.premiumKeys = marketState.premiumKeys or {}
	marketState.premiumKeys[1] = arzSavedCfgString("authPremiumTokenAuth")
	marketState.premiumKeys[2] = arzSavedCfgString("authUserTempKey")
	marketState.premiumKeys[3] = arzSavedCfgString("marketAuthKey")
	if type(marketState.myUidCheck) == "table" then
		marketState.myUidCheck[2] = arzSavedCfgString("authUid") ~= "" and arzSavedCfgString("authUid") or nil
	end
end

function loadPremiumFunction(premiumLoadMode)
	arzApplySavedAuthRuntime()

	deAFKMessage("loadPremiumFunction(func)")

	if not marketState.premiumKeys[1] or not marketState.premiumKeys[2] then
		local premiumRegistryValueNames = {
			"premiumTokenAuth",
			"UserTempKey"
		}
		local premiumKeyIndex = 1

		for registryNameIndex, registryValueName in ipairs(premiumRegistryValueNames) do
			deAFKMessage(debug.getinfo(1, "l"), "scaning > " .. registryValueName)

			local registryValue, registryError = getKey(tostring(registryValueName))

			if registryValue then
				deAFKMessage("Get key: " .. registryValue)

				marketState.premiumKeys[premiumKeyIndex] = tostring(u8(registryValue))

				if registryValueName == "premiumTokenAuth" then
					deAFKMessage(debug.getinfo(1, "l"), "seccess loaded > premiumTokenAuth")

					marketState.premiumTokenAuth = imguiNew.char[256]("" .. registryValue)
				end
			else
				deAFKMessage(u8:decode("Ошибка: ") .. registryError)
			end

			premiumKeyIndex = premiumKeyIndex + 1
		end

		if not marketState.premiumKeys[1] then
			marketState.premiumKeys[1] = ""
		end
	end

	if premiumLoadMode == 1 then
		asyncHttpRequest("POST", (ini.cfg.priumUrlChange == true and marketState.premiumUrl[2] or marketState.premiumUrl[1]) .. "/api/checkKey/" .. arzSavedCfgString("authPremiumTokenAuth"), {
			headers = {
				["content-Type"] = "application/json; charset=utf-8",
				["user-agent"] = arzSavedCfgString("authUserTempKey")
			}
		}, function(premiumAuthResponse)
			if premiumAuthResponse.status_code == 201 then
				deAFKMessage(debug.getinfo(1, "l"), "sub: " .. premiumAuthResponse.text)

				marketState.premiumUserInfo = decodeJson(premiumAuthResponse.text)

				if marketState.premiumUserInfo.endTime then
					marketState.premiumUserInfo.userName = u8:decode(marketState.premiumUserInfo.userName)
					ini.cfg.premiumTokenAuth = arzAuthFreezeNumber("ini_premiumTokenAuth", marketState.premiumUserInfo.userStatus ~= 0 and 1 or 2, -1) or ini.cfg.premiumTokenAuth

					if marketState.premiumUserInfo.UserTempKey then
						local writeSuccess, writeError = writeKey(tostring(marketState.premiumUserInfo.UserTempKey), "UserTempKey")

						deAFKMessage(debug.getinfo(1, "l"), "saved to regdit? > " .. tostring(writeSuccess) .. " | " .. tostring(writeError))
					end

					if marketState.premiumUserInfo.isMenuActive then
						marketState.isMenuActive = marketState.premiumUserInfo.isMenuActive
					end

					save_all()

					if marketState.premiumUserInfo.userStatus ~= 0 then
						marketState.isPremiumAuthedStatus = true
						marketState.lastUpdatePremiumToken = os.time()

						sendNotify(u8:decode("Авторизация успешна! Спасибо, ") .. tostring(marketState.premiumUserInfo.userName) .. u8:decode(", что вы пользуетесь Arizona Market Premium!"))
						save_all()

						timers[27] = os.time()
						timers[26] = os.clock() - 3.5
						isStartLoadPremium = 2
					else
						sendNotify(u8:decode("Авторизация прошла успешно, ") .. tostring(marketState.premiumUserInfo.userName) .. ".")
					end
				elseif marketState.premiumUserInfo.error then
					ini.cfg.premiumTokenAuth = -1

					save_all()
					sendNotify(u8:decode("К сожалению данный ключ продукта недопустим."))
				end
			else
				deAFKMessage(debug.getinfo(1, "l"), "error[2] " .. tostring(premiumAuthResponse.status_code) .. " | " .. tostring(premiumAuthResponse.text))
				sendNotify(u8:decode("Ошибка ") .. tostring(premiumAuthResponse.status_code) .. ".")
			end
		end, function(premiumAuthError)
			deAFKMessage(debug.getinfo(1, "l"), "sub error")
		end)
	end

	if premiumLoadMode == 2 then
		asyncHttpRequest("GET", (ini.cfg.priumUrlChange == true and marketState.premiumUrl[2] or marketState.premiumUrl[1]) .. "/api/getAllPremiumItems/" .. arzSavedCfgString("authPremiumTokenAuth"), {}, function(premiumItemsResponse)
			if premiumItemsResponse.status_code == 200 or premiumItemsResponse.status_code == 304 then
				deAFKMessage(u8:decode(premiumItemsResponse.text))

				local premiumItemsData = decodeJson(u8:decode(premiumItemsResponse.text))

				if not premiumItemsData.error then
					marketState.premItems = premiumItemsData

					sendNotify(u8:decode("Таблица с предметами успешно загружена! Открыть таблицу: /crrxl"))
				else
					marketState.premItems = {}

					sendNotify(u8:decode("Ошибка загрузка таблицы. Обратитесь в поддержку."))
				end
			else
				deAFKMessage(debug.getinfo(1, "l"), "error1 premItems " .. tostring(premiumItemsResponse.status_code))
			end
		end, function(premiumItemsError)
			sendNotify(u8:decode("Ошибка клиента/сервера. Обратитесь в поддержку."))
			sendNotify(u8:decode("Для решения вашей проблемы возможно поможет команда /premhost, напишите ее в чат игры"))
			deAFKMessage(debug.getinfo(1, "l"), "error2 premItems")
		end)
	end

	if premiumLoadMode == 3 then
		local premiumUserPayload = {
			username = arzSavedCfgString("authRealNameMode2"),
			serverId = tonumber(arzSavedCfgString("myServerId")) or arzSavedCfgString("myServerId")
		}
		local premiumUserRequestBody = " [\n        " .. encodeJson(premiumUserPayload) .. "        ] "

		deAFKMessage(debug.getinfo(1, "l"), "[sendPremiumNick]SEND DATA=[" .. premiumUserRequestBody .. "]")
		deAFKMessage(debug.getinfo(1, "l"), "[sendPremiumNick]NICK=[saved]")
		asyncHttpRequest("POST", (ini.cfg.priumUrlChange == true and marketState.premiumUrl[2] or marketState.premiumUrl[1]) .. "/api/insertPremiumUser/" .. arzSavedCfgString("authPremiumTokenAuth"), {
			headers = {
				["content-type"] = "application/json"
			},
			data = u8(premiumUserRequestBody)
		}, function(premiumUserResponse)
			if premiumUserResponse.status_code == 201 or premiumUserResponse.status_code == 304 then
				deAFKMessage(premiumUserResponse.text)

				local premiumUserData = decodeJson(premiumUserResponse.text)

				if premiumUserData and not premiumUserData.error then
					marketState.premUsers = premiumUserData

					writeJsonFile(marketState.premUsers, "moonloader/ArzMarket/UsersInfo/PremiumUsers.json")
				end
			else
				deAFKMessage(debug.getinfo(1, "l"), "error1 insertPremiumUser " .. tostring(premiumUserResponse.status_code))
			end
		end, function(premiumUserError)
			deAFKMessage(debug.getinfo(1, "l"), "error2 insertPremiumUser")
		end)
	end
end

function replacePickup(pickupId, pickupType, pickupPosition, objectPosition)
	local destroyPickupBitStream = raknetNewBitStream()

	raknetBitStreamWriteInt32(destroyPickupBitStream, pickupId)
	raknetEmulRpcReceiveBitStream(63, destroyPickupBitStream)
	raknetDeleteBitStream(destroyPickupBitStream)

	local createPickupBitStream = raknetNewBitStream()

	raknetBitStreamWriteInt32(createPickupBitStream, pickupId)
	raknetBitStreamWriteInt32(createPickupBitStream, 1274)
	raknetBitStreamWriteInt32(createPickupBitStream, 1)
	raknetBitStreamWriteFloat(createPickupBitStream, pickupPosition.x)
	raknetBitStreamWriteFloat(createPickupBitStream, pickupPosition.y)
	raknetBitStreamWriteFloat(createPickupBitStream, pickupPosition.z)
	raknetEmulRpcReceiveBitStream(95, createPickupBitStream)
	raknetDeleteBitStream(createPickupBitStream)

	local objectHandle = createObject(18728, objectPosition.x, objectPosition.y, objectPosition.z - 6)

	marketState.activeObjects[tostring(pickupId)] = {
		modelHandle = objectHandle,
		pickupId = pickupId
	}

	deAFKMessage(debug.getinfo(1, "l"), "create VIP object > " .. pickupId .. " | " .. #marketState.activeObjects)
end

function getKey(valueName)
	local fieldName = valueName == "premiumTokenAuth" and "authPremiumTokenAuth" or valueName == "UserTempKey" and "authUserTempKey" or nil
	if not fieldName then return nil, "unsupported auth key" end

	local saved = arzAuthFreezeText(ini.cfg[fieldName])
	if saved then return saved end

	-- A stopped receiver never imports even legacy registry values.
	if ARZ_INI_WRITE_LOCKED then return nil, "auth data receiving is stopped" end

	local legacy = arzAuthReadLegacyRegistry(valueName)
	if legacy then
		local frozen = arzAuthFreezeCfgString(fieldName, legacy, valueName == "premiumTokenAuth" and "reg_premiumTokenAuth" or "reg_UserTempKey")
		arzAuthDeleteLegacyRegistry()
		if frozen then return frozen end
	end
	return nil, "auth key is empty in ArzMarket.ini"
end

function sampev.onDestroyPickup(pickupId)
	timers[37][6] = {
		pickupId,
		os.time()
	}
	marketState.lavkaPickUp[tostring(pickupId)] = nil

	if marketState.activeObjects[tostring(pickupId)] then
		for objectKey, objectData in pairs(marketState.activeObjects) do
			if objectData.pickupId == pickupId then
				deAFKMessage(debug.getinfo(1, "l"), "destroy VIP object > " .. objectData.modelHandle)
				deleteObject(objectData.modelHandle)
			end
		end

		marketState.activeObjects[tostring(pickupId)] = nil
	end
end

function custom_packet(packetBytes)
	if getGameGlobal(707) == 22 then
		if packetBytes == nil then
			deAFKMessage(debug.getinfo(1, "l"), "error")

			return
		end

		local bitStream = raknetNewBitStream()

		for byteIndex = 1, #packetBytes do
			raknetBitStreamWriteInt8(bitStream, packetBytes[byteIndex])
		end

		raknetEmulPacketReceiveBitStream(220, bitStream)
		raknetDeleteBitStream(bitStream)
	end
end

