	elseif nameMode == 2 then
		local saved = arzSavedCfgString("authRealNameMode2")
		return saved ~= "" and saved or nil
	end
	return nil
end

function premiumObjectManager(textX, textY, textZ, text)
	(function(pickups, textX, textY, textZ, text)
		local pickupMatched = false

		for pickupKey, pickupData in pairs(pickups) do
			if pickupMatched then
				break
			end

			local pickupDistance = getDistanceBetweenCoords3d(pickupData.position.x, pickupData.position.y, pickupData.position.z, textX, textY, textZ)

			if pickupDistance <= 3.5 then
				for textId = 0, 2048 do
					if sampIs3dTextDefined(textId) then
						local text3d, text3dColor, text3dX, text3dY, text3dZ, text3dDistance, text3dTestLos, attachedPlayerId, attachedVehicleId = sampGet3dTextInfoById(textId)
						local textDistanceFromPickup = getDistanceBetweenCoords3d(pickupData.position.x, pickupData.position.y, pickupData.position.z, text3dX, text3dY, text3dZ)

						if text3d:find(u8:decode("Лавка")) and textDistanceFromPickup < 1 then
							for objectKey, objectData in pairs(marketState.activeObjects) do
								if objectData.pickupId == pickupData.id then
									deAFKMessage(debug.getinfo(1, "l"), "[respawn] destroy VIP object > " .. objectData.modelHandle)

									pickupMatched = true
								end
							end

							if not pickupMatched then
								deAFKMessage(pickupData.id .. " | " .. getDistanceBetweenCoords3d(pickupData.position.x, pickupData.position.y, pickupData.position.z, text3dX, text3dY, text3dZ) .. " (" .. getDistanceBetweenCoords3d(pickupData.position.x, pickupData.position.y, pickupData.position.z, textX, textY, textZ) .. ")| " .. text)
								deAFKMessage(textX .. ", " .. textY .. "," .. textZ)

								local midpointPosition = {
									x = (pickupData.position.x + textX) / 2,
									y = (pickupData.position.y + textY) / 2,
									z = (pickupData.position.z + textZ) / 2
								}

								replacePickup(pickupData.id, pickupData.iSpawnType, pickupData.position, pickupDistance > 3 and midpointPosition or {
									x = textX,
									y = textY,
									z = textZ
								})
								table.remove(pickups, pickupKey)

								pickupMatched = true

								break
							end

							deAFKMessage("block recreate new objects > " .. text3d)

							break
						end
					end
				end
			end
		end

		return pickupMatched
	end)(marketState.lavkaPickUp, textX, textY, textZ, text)
end

