function drawCircleIn3d(centerX, centerY, centerZ, radius, segmentCount, lineWidth, color)
	local angleStep = math.floor(360 / (segmentCount or 36))
	local previousScreenX
	local previousScreenY

	for angle = 0, 360, angleStep do
		local pointX = radius * math.cos(math.rad(angle)) + centerX
		local pointY = radius * math.sin(math.rad(angle)) + centerY
		local pointZ = centerZ
		local pointVisible, screenX, screenY, pointDepth, pointScaleX, pointScaleY = convert3DCoordsToScreenEx(pointX, pointY, pointZ)

		if pointDepth > 1 then
			if previousScreenX and previousScreenY then
				renderDrawLine(screenX, screenY, previousScreenX, previousScreenY, lineWidth, color)
			end

			previousScreenX, previousScreenY = screenX, screenY
		end
	end
end

function clear_items()
	while true do
		wait(0)

		if clearInventoryEntries[clearTextdrawState[3] + 1] == nil and clear_busy == false then
			timers[8] = os.time()
			lets_gooooo_clear = false

			wait(100)
		end

		if clearTextdrawState[1] ~= nil and clear_busy == false and clearInventoryEntries[clearTextdrawState[3] + 1] ~= nil then
			wait(0)

			if clearTextdrawState[3] ~= nil and clearTextdrawState[3] ~= 0 and clearWorkerState[3] == true then
				clearWorkerState[3] = false
				clearInventoryEntries[clearTextdrawState[3]][2] = 1337
			end

			for entryIndex, inventoryEntry in pairs(clearInventoryEntries) do
				if tonumber(clearTextdrawState[3]) == inventoryEntry[2] then
					clear_busy = true
					dialogWorkerState[2], dialogWorkerState[3] = inventoryEntry[1], entryIndex
					lets_goo = true

					wait(0)
				end
			end

			clearTextdrawState[3] = clearTextdrawState[3] + 1
		end
	end
end

function scan_items()
	while true do
		wait(0)

		if scannedInventoryEntries[scanTextdrawState[3] + 1] == nil and scan_busy == false then
			lets_gooooo = false

			wait(100)
		end

		if scanTextdrawState[1] ~= nil and scan_busy == false and scannedInventoryEntries[scanTextdrawState[3] + 1] ~= nil then
			wait(0)

			for entryIndex, inventoryEntry in pairs(scannedInventoryEntries) do
				if tonumber(scanTextdrawState[3]) == inventoryEntry[2] then
					if inventoryEntry[3] == 0 then
						wait(0)

						break
					end

					scan_busy = true
					dialogWorkerState[2] = inventoryEntry[1]
					lets_goo = true
				end
			end

			scanTextdrawState[3] = scanTextdrawState[3] + 1
		end
	end
end

function sell_alitems()
	::label_57_0::

	while true do
		wait(0)

		if marketState.custom_is_invent_open[1] ~= nil and marketState.custom_is_invent_open[4] ~= -1 and marketState.custom_is_invent_open[3] == true and marketState.custom_is_invent_open[2] + 2.8 <= os.clock() then
			send_cef("clickOnBlock|{\"slot\": " .. marketState.custom_is_invent_open[4] .. ", \"type\": 1}")

			marketState.custom_is_invent_open = {
				marketState.custom_is_invent_open[1],
				os.clock(),
				marketState.custom_is_invent_open[3],
				marketState.custom_is_invent_open[4],
				marketState.custom_is_invent_open[5] + 1
			}

			if marketState.custom_is_invent_open[5] > 4 then
				AFKMessage(u8:decode("Произошла ошибка нового инвентаря! К сожалению единственным решением будет удалить все товары с продажи и начать выставку товара заново!"))
				off_sell_buy()
			end
		end

		if (is_invent_open ~= nil or marketState.custom_is_invent_open[1] ~= nil) and tradeAutomation.sell and tradeAutomation.score <= tradeAutomation.score_from and sell_busy == false then
			deAFKMessage("+")

			::label_57_1::

			if tradeAutomation.score ~= 0 then
				if need_to_sell > 0 then
					next_stage = false
				else
					next_stage = true
				end
			else
				next_stage = true
			end

			if next_stage == true then
				tradeAutomation.score = tradeAutomation.score + 1

				if tradeAutomation.score > tradeAutomation.score_from and tradeAutomation.sell then
					inventoryPage = 1
					tradeAutomationVisible[0] = false

					AFKMessage(u8:decode("Выставление товаров завершено."))
					table.insert(sellStatusMessages, u8:decode("{35cf0a}Выставление товаров завершено. Проверить все товары вы можете ниже! "))
					saveLog(os.date("[%H:%M:%S]") .. u8:decode(" Выставление товаров завершено. Проверить все товары вы можете ниже!"))

					tradeAutomation = {
						score = 1,
						sell = false,
						score_from = 1
					}
					marketplacePayload.enabled = true
					lets_gooo = false

					if buttons_id ~= nil then
						sampSendClickTextdraw(buttons_id + 2)
					end

					goto label_57_0
				end

				if not sellList[tradeAutomation.score] then
					print("FATAL ERROR SELL!")
				end

				local availableItemCount = sellList[tradeAutomation.score].all_count > 1 and sellList[tradeAutomation.score].all_count - 1 or sellList[tradeAutomation.score].all_count

				need_to_sell = sellList[tradeAutomation.score].maximum and (marketState.filter_seven[0] == false and 999999 or availableItemCount) or tonumber(sellList[tradeAutomation.score].count)
				need_slot = 1
			end

			deAFKMessage("sell_list[display.score].enabled")

			if sellList[tradeAutomation.score].enabled == false then
				saveLog("{ff6666}" .. os.date("[%H:%M:%S]") .. u8:decode("{ffffff} Предмет [{ff6666}") .. sellList[tradeAutomation.score].name .. u8:decode("{ffffff}] не выставлен так как отключен."))
				table.insert(sellStatusMessages, "{ff6666}" .. os.date("[%H:%M:%S]") .. u8:decode("{ffffff} Предмет [{ff6666}") .. sellList[tradeAutomation.score].name .. u8:decode("{ffffff}] не выставлен так как отключен. "))

				need_to_sell = 0
				sell_busy = false

				goto label_57_1
			end

			local serverAddress, serverPort = sampGetCurrentServerAddress()

			if serverIdByAddress[serverAddress] == 0 and tonumber(sellList[tradeAutomation.score].price_vc) < 10 or serverIdByAddress[serverAddress] ~= 0 and tonumber(sellList[tradeAutomation.score].price) < 10 then
				saveLog("{ff6666}" .. os.date("[%H:%M:%S]") .. u8:decode("{ffffff} Предмет [{ff6666}") .. sellList[tradeAutomation.score].name .. u8:decode("{ffffff}] не выставлен так как цена 9, мы не выставляем такую цену."))
				table.insert(sellStatusMessages, "{ff6666}" .. os.date("[%H:%M:%S]") .. u8:decode("{ffffff} Предмет [{ff6666}") .. sellList[tradeAutomation.score].name .. u8:decode("{ffffff}] не выставлен так как цена 9, мы не выставляем такую цену. "))

				need_to_sell = 0
				sell_busy = false

				goto label_57_1
			end

			sellList[tradeAutomation.score].slot_count[need_slot] = GetItemCountByName(sellList[tradeAutomation.score].name, need_slot)

			local inventorySlotId = GetSlot_IdByName(sellList[tradeAutomation.score].name, need_slot)

			if inventorySlotId == nil then
				need_to_sell = 0
				sell_busy = false

				goto label_57_1
			end

			sell_busy = true

			saveLog("[try to sell] [" .. sellList[tradeAutomation.score].name .. "] [" .. sellList[tradeAutomation.score].price .. "|" .. sellList[tradeAutomation.score].price_vc .. "]")
			wait(sellActionDelay)

			if marketState.custom_is_invent_open[1] == nil then
				if tonumber(inventorySlotId) > 35 and tonumber(inventorySlotId) < 72 and inventoryPage ~= 2 then
					tblid = 36
					scannedInventoryEntries = {}
					inventoryPage = 2

					sampSendClickTextdraw(buttons_id + 3)
					wait(mainLoopDelay)
				elseif tonumber(inventorySlotId) > 71 and tonumber(inventorySlotId) < 108 and inventoryPage ~= 3 then
					tblid = 72
					scannedInventoryEntries = {}
					inventoryPage = 3

					sampSendClickTextdraw(buttons_id + 4)
					wait(mainLoopDelay)
				elseif tonumber(inventorySlotId) > 107 and tonumber(inventorySlotId) < 144 and inventoryPage ~= 4 then
					tblid = 108
					scannedInventoryEntries = {}
					inventoryPage = 4

					sampSendClickTextdraw(buttons_id + 5)
					wait(mainLoopDelay)
				elseif tonumber(inventorySlotId) > 143 and tonumber(inventorySlotId) < 180 and inventoryPage ~= 5 then
					tblid = 144
					scannedInventoryEntries = {}
					inventoryPage = 5

					sampSendClickTextdraw(buttons_id + 6)
					wait(mainLoopDelay)
				elseif tonumber(inventorySlotId) < 36 and inventoryPage ~= 1 then
					tblid = 0
					scannedInventoryEntries = {}
					inventoryPage = 1

					sampSendClickTextdraw(buttons_id + 2)
					wait(mainLoopDelay)
				end
			else
				local itemAvailable = true

				for inventoryGroupKey, inventoryGroup in pairs(marketState.available_items_custom) do
					for inventoryItemKey, inventoryItem in pairs(inventoryGroup) do
						if inventoryItem.slot == tonumber(inventorySlotId) and inventoryItem.available == 0 then
							need_to_sell = 0
							sell_busy = false
							itemAvailable = false

							saveLog("[error! item blocked by server, skip. CEF] {ff6666}" .. os.date("[%H:%M:%S]") .. u8:decode("{ffffff} Предмет [{ff6666}") .. sellList[tradeAutomation.score].name .. u8:decode("{ffffff}] не выставлен так как он выставлен или заблокирован. "))
							table.insert(sellStatusMessages, "{ff6666}" .. os.date("[%H:%M:%S]") .. u8:decode("{ffffff} Предмет [{ff6666}") .. sellList[tradeAutomation.score].name .. u8:decode("{ffffff}] не выставлен так как он выставлен или заблокирован. "))

							break
						end
					end
				end

				if itemAvailable then
					send_cef("clickOnBlock|{\"slot\": " .. tostring(inventorySlotId) .. ", \"type\": 1}")

					marketState.custom_is_invent_open = {
						marketState.custom_is_invent_open[1],
						os.clock(),
						true,
						tostring(inventorySlotId),
						marketState.custom_is_invent_open[5]
					}
				end
			end

			if marketState.custom_is_invent_open[1] == nil then
				sellWorkerState[2] = inventorySlotId

				while true do
					for entryIndex, inventoryEntry in pairs(scannedInventoryEntries) do
						if tonumber(sellWorkerState[2]) == inventoryEntry[2] then
							if inventoryEntry[3] == 0 then
								saveLog("[error! item blocked by server, skip.] {ff6666}" .. os.date("[%H:%M:%S]") .. u8:decode("{ffffff} Предмет [{ff6666}") .. sellList[tradeAutomation.score].name .. u8:decode("{ffffff}] не выставлен так как он выставлен или заблокирован. "))
								table.insert(sellStatusMessages, "{ff6666}" .. os.date("[%H:%M:%S]") .. u8:decode("{ffffff} Предмет [{ff6666}") .. sellList[tradeAutomation.score].name .. u8:decode("{ffffff}] не выставлен так как он выставлен или заблокирован. "))

								sell_busy = false
								need_slot = need_slot + 1

								return false
							end

							dialogWorkerState[2] = inventoryEntry[1]
							lets_goo = true

							return false
						end
					end

					wait(0)
				end
			end
		end
	end
end

function kapibara()
	while true do
		for entryIndex, inventoryEntry in pairs(scannedInventoryEntries) do
			if tonumber(sellWorkerState[2]) == inventoryEntry[2] then
				if inventoryEntry[3] == 0 then
					saveLog("[error! item blocked by server, skip.] {ff6666}" .. os.date("[%H:%M:%S]") .. u8:decode("{ffffff} Предмет [{ff6666}") .. sellList[tradeAutomation.score].name .. u8:decode("{ffffff}] не выставлен так как он выставлен или заблокирован. "))
					table.insert(sellStatusMessages, "{ff6666}" .. os.date("[%H:%M:%S]") .. u8:decode("{ffffff} Предмет [{ff6666}") .. sellList[tradeAutomation.score].name .. u8:decode("{ffffff}] не выставлен так как он выставлен или заблокирован. "))

					sell_busy = false
					need_slot = need_slot + 1
					lets_goooo = false

					break
				end

				lets_goooo = false
				dialogWorkerState[2] = inventoryEntry[1]
				lets_goo = true
			end
		end

		wait(txdParseDelay)
	end
end

imgui.OnInitialize(function()
	-- Percentage scale changes UI content, not the outer window. Build the
	-- embedded TTF fonts at the target pixel size after reload instead of
	-- stretching an already rasterized atlas (which made text look blurry).
	local uiScale = getMenuUiScale()
	fonts = loadFonts({
		13,
		17,
		22,
		24,
		27,
		20,
		18
	}, uiScale)

	local io = imgui.GetIO()
	if io ~= nil then
		io.FontGlobalScale = 1.0
	end
	arizona = imgui.CreateTextureFromFileInMemory(imgui.new("const char*", exit_data), #exit_data)
	imgui.GetIO().IniFilename = nil

	imgui.FrameTheme()
end)

function Get_AllCountByName(itemName)
	if json_vlads == nil then
		deAFKMessage(debug.getinfo(1, "l"), "Get_AllCountByName[nil]")

		json_vlads = readJsonFile(sellJsonPath)
	end

	for itemIndex, itemData in pairs(json_vlads) do
		if itemData.item == itemName then
			return tonumber(itemData.all_count)
		end
	end

	return 0
end

function GetSlot_IdByName(itemName, slotIndex)
	if json_vlads == nil then
		deAFKMessage(debug.getinfo(1, "l"), "GetSlot_IdByName[nil]")

		json_vlads = readJsonFile(sellJsonPath)
	end

	if json_vlads ~= nil then
		for itemIndex, itemData in pairs(json_vlads) do
			if itemData.item == itemName then
				return itemData.slot_id[slotIndex]
			end
		end
	else
		deAFKMessage(debug.getinfo(1, "l"), " EROR IN FUNCTION GetSlot_IdByName()")
	end
end

function GetItemCountByName(itemName, slotIndex)
	if json_vlads == nil then
		deAFKMessage(debug.getinfo(1, "l"), "GetItemCountByName[nil]")

		json_vlads = readJsonFile(sellJsonPath)
	end

	if json_vlads ~= nil then
		for itemIndex, itemData in pairs(json_vlads) do
			if itemData.item == itemName then
				return itemData.count[slotIndex]
			end
		end
	else
		deAFKMessage(debug.getinfo(1, "l"), " EROR IN FUNCTION GetItemCountByName()")
	end

	return "0"
end

function rainbow(speed, alpha)
	local currentClock = os.clock()
	local red = math.floor(math.sin(currentClock * speed) * 127 + 128)
	local green = math.floor(math.sin(currentClock * speed + 2) * 127 + 128)
	local blue = math.floor(math.sin(currentClock * speed + 4) * 127 + 128)

	return {
		red / 255,
		green / 255,
		blue / 255,
		alpha
	}
end

function url_decode(encodedUrl)
	local function decodeHexByte(hexByte)
		return string.char(tonumber(hexByte, 16))
	end

	return encodedUrl:gsub("%%(%x%x)", decodeHexByte)
end

