	local windowHeight = 343 + math.floor(82 * getMenuUiScale())

	imgui.SetNextWindowPos(imgui.ImVec2(screenWidth, screenHeight / 2), imgui.Cond.FirstUseEver, imgui.ImVec2(1, 0.5))
	imgui.SetNextWindowSize(imgui.ImVec2(windowWidth, windowHeight), imgui.Cond.Always)
