	windowDrawList:AddRectFilled(imgui.ImVec2(cursorScreenPos.x, cursorScreenPos.y), imgui.ImVec2(cursorScreenPos.x + windowWidth, cursorScreenPos.y + windowHeight + 2.6), imgui.GetColorU32Vec4(imgui.ImVec4(windowColor[0], windowColor[1], windowColor[2], windowColor[3])), 5, 0)

