	imgui.GetWindowDrawList():AddRect(cursorScreenPos, imgui.ImVec2(cursorScreenPos.x + windowWidth, cursorScreenPos.y + windowHeight), imgui.GetColorU32Vec4(imgui.ImVec4(menuThemeConfig.Border[1], menuThemeConfig.Border[2], menuThemeConfig.Border[3], menuThemeConfig.Border[4])), 5, 0, 3)
