function wrapTextSputnik(text, maxWidth)
	local wrappedLines = {}
	local currentLine = ""
	local currentLineWidth = 0

	for word, whitespace in text:gmatch("([^%s]*)(%s*)") do
		local wordWidth = #word * 6
		local whitespaceWidth = #whitespace * 3

		if currentLine ~= "" then
			wordWidth = wordWidth + whitespaceWidth
		end

		if maxWidth >= currentLineWidth + wordWidth then
			if currentLine == "" then
				currentLine = word
			else
				currentLine = currentLine .. whitespace .. word
			end

			currentLineWidth = currentLineWidth + wordWidth
		else
			if currentLine ~= "" then
				table.insert(wrappedLines, currentLine)
			end

			currentLine = word
			currentLineWidth = #word * 6
		end
	end

	if currentLine ~= "" then
		table.insert(wrappedLines, currentLine)
	end

	return wrappedLines
end

function sendSputnikText(text, replaceCurrentText, hideDelay)
	if ini.cfg.isEnabledSputnikWords then
		local textWithTrailingSpace = text .. " "

		if replaceCurrentText then
			sputnikDraw.currentText = textWithTrailingSpace
			sputnikDraw.textAnimation.fullText = ""
			sputnikDraw.textAnimation.lines = wrapTextSputnik(textWithTrailingSpace, 350)
			sputnikDraw.textAnimation.charIndex = #textWithTrailingSpace
			sputnikDraw.textAnimation.hideDelay = hideDelay or 3
			sputnikDraw.textAnimation.hideTime = os.clock() + (hideDelay or 3)

			return
		end

		if sputnikDraw.textAnimation.fullText ~= "" then
			sputnikDraw.currentText = sputnikDraw.textAnimation.fullText
			sputnikDraw.textAnimation.fullText = ""
			sputnikDraw.textAnimation.lines = wrapTextSputnik(sputnikDraw.currentText, 350)
			sputnikDraw.textAnimation.charIndex = #sputnikDraw.currentText
			sputnikDraw.textAnimation.hideDelay = hideDelay or 3
			sputnikDraw.textAnimation.hideTime = os.clock() + (hideDelay or 3)

			return
		end

		sputnikDraw.textAnimation = {
			speed = 0.03,
			charIndex = 0,
			currentText = "",
			hideTime = 0,
			fullText = textWithTrailingSpace,
			lastUpdate = os.clock(),
			lines = {},
			hideDelay = hideDelay or 3
		}
		sputnikDraw.currentText = ""
	end
end

sputnikDraw = imgui.OnFrame(function()
	return marketState.isEnabledSputnik[0]
end, function(frame)
	frame.HideCursor = true

	local backgroundDrawList = imgui.GetBackgroundDrawList()
	local screenWidth, screenHeight = getScreenResolution()

	if not marketState.sputnikPng and menuThemeConfig.selectedSputnik ~= "" and doesFileExist(getWorkingDirectory() .. "/ArzMarket/resource/sputnik/" .. menuThemeConfig.selectedSputnik .. ".png") then
		if not menuWP then
			menuWP = {
				x = 0,
				y = 0
			}
		end

		marketState.sputnikPng = imgui.CreateTextureFromFile(getWorkingDirectory() .. "/ArzMarket/resource/sputnik/" .. menuThemeConfig.selectedSputnik .. ".png")
	end

	if not sputnikDraw.textAnimation then
		sputnikDraw.textAnimation = {
			speed = 0.05,
			fullText = "",
			lastUpdate = 0,
			charIndex = 0,
			hideTime = 0,
			currentText = "",
			hideDelay = 3,
			lines = {}
		}
	end

	if marketState.sputnikPng and menuThemeConfig.selectedSputnik ~= "" and doesFileExist(getWorkingDirectory() .. "/ArzMarket/resource/sputnik/sputnik.json") then
		marketState.sputnikJson = marketState.sputnikJson or ini.cfg.isCustomSputnikEnabled and menuThemeConfig.customSputniks or readJsonFile("moonloader/ArzMarket/resource/sputnik/sputnik.json")

		if marketState.sputnikJson and marketState.sputnikJson[menuThemeConfig.selectedSputnik:match("%a+")] then
			for sputnikEntryKey, sputnikEntry in pairs(marketState.sputnikJson[menuThemeConfig.selectedSputnik:match("%a+")]) do
				if sputnikEntryKey == "dialogText" and sputnikEntry.timer and timers[28][1] + sputnikEntry.timer <= os.time() then
					if sputnikEntry[tostring(timers[28][2])] then
						sendSputnikText(u8(sputnikEntry[tostring(timers[28][2])]), false, 5)

						timers[28][1] = os.time()
						timers[28][2] = timers[28][2] + 1
					else
						deAFKMessage("error message > timer set to 1")

						timers[28][2] = 1
					end
				end
			end
		end
	end

	if sputnikDraw.textAnimation.fullText ~= "" then
		local currentClock = os.clock()

		if currentClock - sputnikDraw.textAnimation.lastUpdate > sputnikDraw.textAnimation.speed then
			sputnikDraw.textAnimation.charIndex = sputnikDraw.textAnimation.charIndex + 1
			sputnikDraw.textAnimation.currentText = string.sub(sputnikDraw.textAnimation.fullText, 1, sputnikDraw.textAnimation.charIndex)
			sputnikDraw.textAnimation.lastUpdate = currentClock
			sputnikDraw.currentText = sputnikDraw.textAnimation.currentText
			sputnikDraw.textAnimation.lines = wrapTextSputnik(sputnikDraw.currentText, 350)

			if sputnikDraw.textAnimation.charIndex >= #sputnikDraw.textAnimation.fullText then
				sputnikDraw.textAnimation.fullText = ""
				sputnikDraw.textAnimation.hideTime = os.clock() + sputnikDraw.textAnimation.hideDelay
			end
		end
	end

	if sputnikDraw.textAnimation.fullText == "" and sputnikDraw.textAnimation.hideTime > 0 and os.clock() > sputnikDraw.textAnimation.hideTime then
		sputnikDraw.currentText = ""
		sputnikDraw.textAnimation.hideTime = 0
		sputnikDraw.textAnimation.lines = {}
	end

	if menuWP and marketState.sputnikPng then
		sputnikDraw.currentPos = sputnikDraw.currentPos or imgui.ImVec2(menuWP.x - 300, menuWP.y)

		local targetX = menuOpen and marketState.edit_sputnik == false and menuWP.x - 300 or menuThemeConfig.sputnikPosition.x
		local targetY = menuOpen and marketState.edit_sputnik == false and menuWP.y - 200 or menuThemeConfig.sputnikPosition.y
		local positionLerpFactor = 0.06

		sputnikDraw.currentPos.x = sputnikDraw.currentPos.x + (targetX - sputnikDraw.currentPos.x) * positionLerpFactor
		sputnikDraw.currentPos.y = sputnikDraw.currentPos.y + (targetY - sputnikDraw.currentPos.y) * positionLerpFactor

		if not sputnikDraw.turnOffset then
			sputnikDraw.turnOffset = 0
			sputnikDraw.turnVelocity = 0
		end

		local maxTurnOffset = 75
		local turnAcceleration = 0.05
		local centeringForce = 0.01

		if isKeyDown(68) and isCharInAnyCar(PLAYER_PED) then
			sputnikDraw.turnVelocity = sputnikDraw.turnVelocity - turnAcceleration
		elseif isKeyDown(65) and isCharInAnyCar(PLAYER_PED) then
			sputnikDraw.turnVelocity = sputnikDraw.turnVelocity + turnAcceleration
		elseif math.abs(sputnikDraw.turnOffset) > 0.1 then
			sputnikDraw.turnVelocity = sputnikDraw.turnVelocity - sputnikDraw.turnOffset * centeringForce
		else
			sputnikDraw.turnVelocity = 0
			sputnikDraw.turnOffset = 0
		end

		sputnikDraw.turnVelocity = sputnikDraw.turnVelocity * 0.95
		sputnikDraw.turnOffset = sputnikDraw.turnOffset + sputnikDraw.turnVelocity

		if maxTurnOffset < sputnikDraw.turnOffset then
			sputnikDraw.turnOffset = maxTurnOffset
			sputnikDraw.turnVelocity = 0
		elseif sputnikDraw.turnOffset < -maxTurnOffset then
			sputnikDraw.turnOffset = -maxTurnOffset
			sputnikDraw.turnVelocity = 0
		end

		if not sputnikDraw.waveTime then
			sputnikDraw.waveTime = 0
		else
			sputnikDraw.waveTime = sputnikDraw.waveTime + 0.05
		end

		local waveOffsetX = math.sin(sputnikDraw.waveTime * 1.5) * 0.91
		local waveOffsetY = math.cos(sputnikDraw.waveTime * 1) * 0.35
		local sputnikPosition = imgui.ImVec2(sputnikDraw.currentPos.x + waveOffsetX + sputnikDraw.turnOffset, sputnikDraw.currentPos.y + waveOffsetY)

		backgroundDrawList:AddImageRounded(marketState.sputnikPng, sputnikPosition, imgui.ImVec2(sputnikPosition.x + menuThemeConfig.sputnikSize.x, sputnikPosition.y + menuThemeConfig.sputnikSize.y), imgui.ImVec2(0, 0), imgui.ImVec2(1, 1), 4294967295, 60)

		if sputnikDraw.currentText and sputnikDraw.currentText ~= "" and #sputnikDraw.textAnimation.lines > 0 then
			local textPadding = 15
			local lineHeight = 20
			local bubbleOffsetY = -50
			local bubbleWidth = (220) + textPadding * 2
			local bubbleHeight = #sputnikDraw.textAnimation.lines * lineHeight + textPadding * 2
			local bubblePosition = imgui.ImVec2(sputnikPosition.x + menuThemeConfig.sputnikSize.x / 2 - bubbleWidth / 2, sputnikPosition.y + bubbleOffsetY - bubbleHeight)

			if not sampIsChatInputActive() then
				backgroundDrawList:AddRectFilled(bubblePosition, imgui.ImVec2(bubblePosition.x + bubbleWidth, bubblePosition.y + bubbleHeight), 3707764736, 15, 15)
			end

			local bubbleTipPosition = imgui.ImVec2(bubblePosition.x + bubbleWidth / 2, bubblePosition.y + bubbleHeight)

			if not sampIsChatInputActive() then
				backgroundDrawList:AddTriangleFilled(bubbleTipPosition, imgui.ImVec2(bubbleTipPosition.x - 10, bubbleTipPosition.y + 10), imgui.ImVec2(bubbleTipPosition.x + 10, bubbleTipPosition.y + 10), 3707764736)
			end

			local showCursor = sputnikDraw.textAnimation.fullText ~= "" and math.floor(os.clock() * 2) % 2 == 0

			imgui.PushFont(uiFonts[1])

			if not sampIsChatInputActive() then
				for lineIndex, lineText in ipairs(sputnikDraw.textAnimation.lines) do
					local lineY = bubblePosition.y + textPadding + (lineIndex - 1) * lineHeight

					backgroundDrawList:AddText(imgui.ImVec2(bubblePosition.x + textPadding, lineY), 4294967295, lineText .. (showCursor and lineIndex == #sputnikDraw.textAnimation.lines and "|" or ""))
				end
			end

			imgui.PopFont()
		end
	end
end)

function priceGraphRender(drawList, origin, width, height, pricePoints, priceMode)
	local priceField = priceMode == 2 and "3" or "2"

	if #pricePoints == 0 then
		drawList:AddText(imgui.ImVec2(origin.x + width / 2 - 50, origin.y + height / 2 - 10), 2432696319, u8:decode("Нет данных для отображения"))

		return
	end

	marketState.priceGraph.min, marketState.priceGraph.max = math.huge, -math.huge

	for pointIndex, pricePoint in ipairs(pricePoints) do
		local priceValue = pricePoint[priceField]

		marketState.priceGraph.min = math.min(marketState.priceGraph.min, priceValue)
		marketState.priceGraph.max = math.max(marketState.priceGraph.max, priceValue)
	end

	local priceRange = marketState.priceGraph.max - marketState.priceGraph.min

	if priceRange == 0 then
		priceRange = 1
	end

	local graphPadding = marketState.priceGraph.padding
	local plotWidth = width - graphPadding.left - graphPadding.right
	local plotHeight = height - graphPadding.top - graphPadding.bottom
	local mousePos = imgui.GetMousePos()
	local hoveredPointIndex = -1

	for gridLineIndex = 0, 4 do
		local gridLineY = origin.y + graphPadding.top + plotHeight * gridLineIndex / 4

		drawList:AddLine(imgui.ImVec2(origin.x + graphPadding.left, gridLineY), imgui.ImVec2(origin.x + width - graphPadding.right, gridLineY), marketState.priceGraph.colors.grid, 1)

		local gridPrice = marketState.priceGraph.max - priceRange * gridLineIndex / 4

		drawList:AddText(imgui.ImVec2(origin.x + 5, gridLineY - 8), marketState.priceGraph.colors.text, tostring(formatPrice(math.floor(gridPrice))))
	end

	drawList:AddLine(imgui.ImVec2(origin.x + graphPadding.left, origin.y + graphPadding.top), imgui.ImVec2(origin.x + graphPadding.left, origin.y + height - graphPadding.bottom), marketState.priceGraph.colors.grid, 2)
	drawList:AddLine(imgui.ImVec2(origin.x + width - graphPadding.right, origin.y + graphPadding.top), imgui.ImVec2(origin.x + width - graphPadding.right, origin.y + height - graphPadding.bottom), marketState.priceGraph.colors.grid, 2)

	local plotPoints = {}

	for pointIndex = 1, #pricePoints do
		local pointRatio = #pricePoints > 1 and (pointIndex - 1) / (#pricePoints - 1) or 0.5
		local pointX = origin.x + graphPadding.left + pointRatio * plotWidth
		local pointY = origin.y + height - graphPadding.bottom - (pricePoints[pointIndex][priceField] - marketState.priceGraph.min) / priceRange * plotHeight

		table.insert(plotPoints, {
			x = pointX,
			y = pointY
		})

		local pointHovered = mousePos.x >= pointX - 5 and mousePos.x <= pointX + 5 and mousePos.y >= pointY - 5 and mousePos.y <= pointY + 5

		drawList:AddCircleFilled(imgui.ImVec2(pointX, pointY), 3, pointHovered and 4283215696 or 4281519410)

		if pointHovered then
			hoveredPointIndex = pointIndex
		end
	end

	for pointIndex = 2, #plotPoints do
		drawList:AddLine(imgui.ImVec2(plotPoints[pointIndex - 1].x, plotPoints[pointIndex - 1].y), imgui.ImVec2(plotPoints[pointIndex].x, plotPoints[pointIndex].y), marketState.priceGraph.colors.line, 2)
	end

	for segmentIndex = 1, #plotPoints - 1 do
		local segmentStart = imgui.ImVec2(plotPoints[segmentIndex].x, plotPoints[segmentIndex].y)
		local segmentEnd = imgui.ImVec2(plotPoints[segmentIndex + 1].x, plotPoints[segmentIndex + 1].y)
		local fillBottomEnd = imgui.ImVec2(plotPoints[segmentIndex + 1].x, origin.y + height - graphPadding.bottom)
		local fillBottomStart = imgui.ImVec2(plotPoints[segmentIndex].x, origin.y + height - graphPadding.bottom)

		drawList:AddQuadFilled(segmentStart, segmentEnd, fillBottomEnd, fillBottomStart, 1077071154)
	end

	if #plotPoints > 0 then
		local lastPoint = plotPoints[#plotPoints]

		drawList:AddCircleFilled(imgui.ImVec2(lastPoint.x, lastPoint.y), 5, 4294956800)
		drawList:AddCircle(imgui.ImVec2(lastPoint.x, lastPoint.y), 7, 4294956800, 0, 2)
	end

	for pointIndex = 1, #pricePoints do
		if pointIndex == 1 or pointIndex == #pricePoints or pointIndex % math.max(1, math.floor(#pricePoints / 4)) == 0 then
			local labelRatio = #pricePoints > 1 and (pointIndex - 1) / (#pricePoints - 1) or 0.5
			local labelX = origin.x + graphPadding.left + labelRatio * plotWidth
			local dateParts = {}

			for datePart in string.gmatch(pricePoints[pointIndex]["1"], "[^-]+") do
				table.insert(dateParts, datePart)
			end

			local formattedDate = table.concat(dateParts, "-", 2, 3)

			drawList:AddText(imgui.ImVec2(labelX - 10, origin.y + height - graphPadding.bottom + 5), marketState.priceGraph.colors.text, formattedDate)
		end
	end

	if hoveredPointIndex ~= -1 then
		imgui.PushStyleVarVec2(imgui.StyleVar.WindowPadding, imgui.ImVec2(8, 8))
		imgui.BeginTooltip()
		imgui.Text("Дата: " .. pricePoints[hoveredPointIndex]["1"])
		imgui.Text("Цена: " .. formatPrice(pricePoints[hoveredPointIndex][priceField]))

		if hoveredPointIndex > 1 then
			local previousPrice = tonumber(pricePoints[hoveredPointIndex - 1][priceField]) or 0
			local priceDifference = pricePoints[hoveredPointIndex][priceField] - previousPrice
			if previousPrice ~= 0 then
				local percentChange = priceDifference / previousPrice * 100
				imgui.Text(string.format("Изменение: %s%.2f%%", priceDifference >= 0 and "+" or "-", math.abs(percentChange)) .. "  %")
			end
		end

		imgui.EndTooltip()
		imgui.PopStyleVar()
	end
end

function formatPrice(price)
	if not price then
		return "N/A"
	end

	return tostring(math.floor(price)):reverse():gsub("(%d%d%d)", "%1 "):reverse():gsub("^ ", ""):gsub(" ", ",")
end

