function isMarketFrameActive()
	local cursorX, cursorY = getCursorPos()
	local screenWidth, screenHeight = getScreenResolution()
	local marketWindowPosition = marketWindowPos.x ~= -1 and marketWindowPos or imgui.ImVec2((screenWidth - marketWindowSize.x[0]) / 2, screenHeight - marketWindowSize.y[0] - screenHeight * 0.01)

	if (sampIsCursorActive() or marketState.isEnableCursor or menuVisible[0]) and marketWindowPositionEditMode == false then
		if cursorX < marketWindowPosition.x or cursorX > marketWindowPosition.x + marketWindowSize.x[0] or cursorY < marketWindowPosition.y or cursorY > marketWindowPosition.y + marketWindowSize.y[0] then
			return true
		else
			return false
		end
	end

	return true
end

