function GetMoneyLimit()
	local unlimitedItemCount = 0
	local budget = tonumber(ffi.string(buyBudgetInput.buy))

	for itemIndex, itemData in pairs(buyList) do
		if not itemData.maximum and itemData.enabled then
			unlimitedItemCount = unlimitedItemCount + 1
		end
	end

	if not budget or budget < 0 or unlimitedItemCount == 0 then
		return getPlayerMoney()
	end

	local budgetPerItem = math.floor(budget) / unlimitedItemCount
	local totalPurchaseCost = 0

	for itemIndex, itemData in pairs(buyList) do
		if not itemData.maximum and itemData.enabled then
			local itemPrice = tonumber(viceCityMode and itemData.price or itemData.price_vc) or 0
			if itemPrice > 0 then
				local itemPurchaseCost = math.floor(budgetPerItem / itemPrice) * itemPrice
				totalPurchaseCost = totalPurchaseCost + itemPurchaseCost
			end
		end
	end

	return getPlayerMoney() - totalPurchaseCost
end

function getPlayerMoney()
	return ini.cfg.realMoneyNow
end

