						ini.cfg.premiumTokenAuth = arzAuthFreezeNumber("ini_premiumTokenAuth", marketState.premiumUserInfo.userStatus ~= 0 and 1 or 2, -1) or ini.cfg.premiumTokenAuth

						local writeSuccess, writeError = writeKey(tostring(ffi.string(marketState.premiumTokenAuth)), "premiumTokenAuth")

						deAFKMessage(debug.getinfo(1, "l"), "saved to regdit[1]? > " .. tostring(writeSuccess) .. " | " .. tostring(writeError))

						if marketState.premiumUserInfo.UserTempKey then
							local tempKeyWriteSuccess, tempKeyWriteError = writeKey(tostring(marketState.premiumUserInfo.UserTempKey), "UserTempKey")

							deAFKMessage(debug.getinfo(1, "l"), "saved to regdit? > " .. tostring(tempKeyWriteSuccess) .. " | " .. tostring(tempKeyWriteError))
						end

						if marketState.premiumUserInfo.isMenuActive then
							marketState.isMenuActive = marketState.premiumUserInfo.isMenuActive
						end

						timers[27] = os.time()

						if marketState.premiumUserInfo.userStatus ~= 0 then
							sendNotify(u8:decode("Авторизация успешна! Спасибо, ") .. tostring(marketState.premiumUserInfo.userName) .. u8:decode(", что вы пользуетесь Arizona Market Premium!"))
							save_all()

							timers[26] = os.clock() - 3.5
							isStartLoadPremium = 2
							marketState.isPremiumAuthedStatus = true
						else
							sendNotify(u8:decode("Авторизация прошла успешно, ") .. tostring(marketState.premiumUserInfo.userName) .. ".")
						end

						isUpdateNick = 3
					elseif marketState.premiumUserInfo.error then
						marketState.lastUpdatePremiumToken = -1

						sendNotify(u8:decode("К сожалению данный ключ продукта недопустим."))
						save_all()
					end
				else
					deAFKMessage(debug.getinfo(1, "l"), "error1 " .. tostring(tokenCheckResponse.status_code))
					sendNotify(u8:decode("Ошибка ") .. tostring(tokenCheckResponse.status_code) .. ".")
				end
			end, function(tokenCheckError)
				deAFKMessage(debug.getinfo(1, "l"), "sub error")
				sendNotify(u8:decode("Ошибка клиента/сервера. Обратитесь в поддержку."))
				sendNotify(u8:decode("Для решения вашей проблемы возможно поможет команда /premhost, напишите ее в чат игры"))
			end)
		end

		if marketState.isMenuActive == 1 and imgui.Button("Привязать аккаунт", imgui.ImVec2(imgui.GetWindowWidth(), 30)) then
			local savedRealPlayerName = arzSavedCfgString("authRealNameMode1")
			local savedUid = arzSavedCfgString("authUid")

			if savedUid ~= "" and savedRealPlayerName ~= "" then
				local bindingRequestBody = encodeJson({
					keyAccept = arzSavedCfgString("authPremiumTokenAuth"),
					gameNickname = savedRealPlayerName .. "[" .. savedUid .. "]"
				})

				asyncHttpRequest("POST", marketState.host .. "/api/confirm-binding", {
					headers = {
						["content-type"] = "application/json"
					},
					data = u8(bindingRequestBody)
				}, function(bindingResponse)
					if bindingResponse.status_code == 201 or bindingResponse.status_code == 304 then
						deAFKMessage(debug.getinfo(1, "l"), "sub: " .. bindingResponse.text)

						local bindingData = decodeJson(bindingResponse.text)

						if bindingData.isMenuActive then
							marketState.isMenuActive = bindingData.isMenuActive

							if bindingData.status then
								sendNotify(u8:decode("Аккаунт успешно привязан! Зайдите в телеграм и прочитайте сообщение!"))
							else
								sendNotify(u8:decode("К сожалению произошла ошибка при привязке! Пройдите в бота для просмотра причины!"))
							end
						end
					else
						deAFKMessage(debug.getinfo(1, "l"), "error1 confirm-binding " .. tostring(bindingResponse.status_code))
					end
				end, function(bindingError)
					deAFKMessage(debug.getinfo(1, "l"), "error2 confirm-binding")
				end)
			else
				sendNotify(u8:decode("Произошла ошибка! Перезайдите полностью на сервер. Если проблема повторяется - напишите в тех поддержку."))
			end
		end

		if imgui.Button("Закрыть", imgui.ImVec2(imgui.GetWindowWidth(), 30)) then
			marketState.isPopupActive = false

			imgui.CloseCurrentPopup()
		end

		imgui.GetStyle().FrameBorderSize = 0

		imgui.EndPopup()
	end

	imgui.PopStyleVar()
	imgui.PopStyleColor()
	imgui.PopFont()
end

