		end

		if imgui.InputTextWithHintD(" Название спутника", " Название спутника", marketState.sputnikName, ffi.sizeof(marketState.sputnikName)) then
		end

		if imgui.InputTextWithHintD(" Задержка на отправку фраз над головой.", " Задержка на отправку фраз над головой.", marketState.sputnikDelay, ffi.sizeof(marketState.sputnikDelay)) then
		end

		imgui.PopItemWidth()
		imgui.Text("Фразы которые будут воспроизводится.")
		imgui.PushItemWidth(500)

		imgui.GetStyle().FrameBorderSize = borderSideEnabled[0] and 1 or 0

		if imgui.InputTextMultiline(u8("##words1"), marketState.sputnikWords, ffi.sizeof(marketState.sputnikWords)) then
		end

		imgui.GetStyle().FrameBorderSize = 0

		imgui.PopItemWidth()
		imgui.EndChild()

		imgui.GetStyle().FrameBorderSize = borderSideEnabled[0] and 1 or 0

		if imgui.Button("Сохранить", imgui.ImVec2(imgui.GetWindowWidth() / 2.01, 30)) then
			local sputnikNameText = ffi.string(marketState.sputnikName)
			local sputnikDelaySeconds = tonumber(ffi.string(marketState.sputnikDelay))

			if #ffi.string(marketState.sputnikName) > 1 and #ffi.string(marketState.sputnikImage) > 1 and not u8:decode(sputnikNameText):match("%d") and not u8:decode(sputnikNameText):match(u8:decode("[а-яА-ЯёЁ]")) and sputnikDelaySeconds ~= nil and not u8:decode(sputnikNameText):match("%s") then
				if marketState.isEditSputnik[2] ~= "" and marketState.isEditSputnik[1] then
					deAFKMessage("clean > current_theme.customSputniks")

					menuThemeConfig.customSputniks[marketState.isEditSputnik[2]] = nil
					textureCache[marketState.isEditSputnik[2]] = nil

					os.remove(getWorkingDirectory() .. "/ArzMarket/resource/sputnik/" .. marketState.isEditSputnik[2] .. ".png")
				end

				menuThemeConfig.customSputniks[sputnikNameText] = {}
				menuThemeConfig.customSputniks[sputnikNameText].png = ffi.string(marketState.sputnikImage)
				menuThemeConfig.customSputniks[sputnikNameText].dialogText = {}
				menuThemeConfig.customSputniks[sputnikNameText].dialogText.timer = sputnikDelaySeconds

				local dialogLineIndex = 0

				for line in magiclines(ffi.string(marketState.sputnikWords)) do
					dialogLineIndex = dialogLineIndex + 1
					menuThemeConfig.customSputniks[sputnikNameText].dialogText[tostring(dialogLineIndex)] = u8:decode(line)
				end

				imgui.CloseCurrentPopup()

				marketState.download_sputnik = nil
				marketState.isPopupActive = false

				writeJsonFile(menuThemeConfig, menuThemePath)
			else
				AFKMessage(u8:decode("Вы заполнили не все параметры! Так же проверьте:"))
				AFKMessage(u8:decode("        Что бы название было на английском языке и без цифр!"))
				AFKMessage(u8:decode("        Что бы в таймере не было букв!"))
				AFKMessage(u8:decode("        Что бы в названии спутника не было пробелов!"))
			end
		end

		imgui.SameLine()

		if imgui.Button("Закрыть", imgui.ImVec2(imgui.GetWindowWidth() / 2.04, 30)) then
			marketState.isPopupActive = false

			imgui.CloseCurrentPopup()
		end

		if marketState.isEditSputnik[1] and marketState.isEditSputnik[2] ~= "" and imgui.Button("[!] Удалить [!]", imgui.ImVec2(imgui.GetWindowWidth(), 30)) then
			marketState.isPopupActive = false

			imgui.CloseCurrentPopup()
			deAFKMessage("clean > current_theme.customSputniks")

			menuThemeConfig.customSputniks[marketState.isEditSputnik[2]] = nil
			textureCache[marketState.isEditSputnik[2]] = nil

			os.remove(getWorkingDirectory() .. "/ArzMarket/resource/sputnik/" .. marketState.isEditSputnik[2] .. ".png")
			writeJsonFile(menuThemeConfig, menuThemePath)
		end

		imgui.GetStyle().FrameBorderSize = 0

		imgui.EndPopup()
	end

	imgui.PopStyleVar()
	imgui.PopStyleColor()
	imgui.PopFont()
end

