function hexToRGBA(hexColor)
	hexColor = hexColor:gsub("{", ""):gsub("}", "")

	if #hexColor ~= 6 and #hexColor ~= 8 then
		error(u8:decode("Неверный формат HEX. Ожидается 6 или 8 символов."))
	end

	local red = tonumber(hexColor:sub(1, 2), 16) / 255
	local green = tonumber(hexColor:sub(3, 4), 16) / 255
	local blue = tonumber(hexColor:sub(5, 6), 16) / 255
	local alpha = #hexColor == 8 and tonumber(hexColor:sub(7, 8), 16) / 255 or 1

	return red, green, blue, alpha
end

