function isNodeInstalled()
	if timers[12] + 10 <= os.time() then
		timers[12] = os.time()

		local nodeVersionProcess = io.popen("node -v 2>&1")
		local nodeVersionOutput = nodeVersionProcess:read("*a")

		nodeVersionProcess:close()
		print(nodeVersionOutput)

		if nodeVersionOutput:match("v%d+%.%d+%.%d+") then
			isNodeInstalledV = true
		else
			isNodeInstalledV = false
		end
	end
end

