function changeDate()
	if imgui.BeginPopupModal("Выбор даты", _, imgui.WindowFlags.NoCollapse + imgui.WindowFlags.NoResize + imgui.WindowFlags.NoMove) then
		imgui.SetWindowSizeVec2(imgui.ImVec2(300, 305))
		imgui.BeginChild("changeDate", imgui.ImVec2(-1, imgui.GetWindowWidth() - 70), true)

		local sortedDates = {}

		for date, dayLog in pairs(jsonLog) do
			local day, month, year = date:match("(%d+)%.(%d+)%.(%d+)")

			table.insert(sortedDates, {
				key = date,
				date = tonumber(year .. month .. day)
			})
		end

		table.sort(sortedDates, function(leftItem, rightItem)
			return leftItem.date > rightItem.date
		end)

		if imgui.Button("За весь период", imgui.ImVec2(-1)) then
			marketState.searchStorage.logPage_1[2] = ""
			date_select = -1

			imgui.CloseCurrentPopup()
		end

		for dateIndex, dateEntry in ipairs(sortedDates) do
			if imgui.Button(dateEntry.key, imgui.ImVec2(-1)) then
				marketState.searchStorage.logPage_1[2] = ""
				date_select = dateEntry.key

				imgui.CloseCurrentPopup()
			end
		end

		imgui.EndChild()

		if imgui.Button("Закрыть", imgui.ImVec2(-1, 30)) then
			imgui.CloseCurrentPopup()
		end

		imgui.EndPopup()
	end
end

function imgui.Hint(hintId, hintText, alignLeft, offset, forceVisible)
	if hintsEnabled[0] == false then
		return false
	end

	if offset == nil then
		offset = {
			x = 0,
			y = 0
		}
	end

	color = imgui.ImVec4(menuThemeConfig.Border[1], menuThemeConfig.Border[2], menuThemeConfig.Border[3], 0.75)

	local cursorPos = imgui.GetCursorPos()
	local hintVisible = forceVisible or imgui.IsItemHovered()

	imgui.SameLine(nil, 0)

	local animationDuration = 0.09
	local canAnimate = true

	if not POOL_HINTS then
		POOL_HINTS = {}
	end

	if not POOL_HINTS[hintId] then
		POOL_HINTS[hintId] = {
			timer = 0,
			status = false
		}
	end

	if hintVisible then
		for otherHintId, otherHintState in pairs(POOL_HINTS) do
			if otherHintId ~= hintId and animationDuration >= os.clock() - otherHintState.timer then
				canAnimate = false
			end
		end
	end

	if canAnimate and POOL_HINTS[hintId].status ~= hintVisible then
		POOL_HINTS[hintId].status = hintVisible
		POOL_HINTS[hintId].timer = os.clock()
	end

	local function getContrastingTextColor(backgroundColor)
		return 1 - (0.299 * backgroundColor.x + 0.587 * backgroundColor.y + 0.114 * backgroundColor.z) < 0.5 and imgui.ImVec4(0, 0, 0, 1) or imgui.ImVec4(1, 1, 1, 1)
	end

	local function drawHint(alpha)
		local itemSize = imgui.GetItemRectSize()
		local cursorScreenPos = imgui.GetCursorScreenPos()
		local windowDrawList = imgui.GetWindowDrawList()
		local tooltipPosition = imgui.ImVec2(cursorScreenPos.x + offset.x - itemSize.x / 2, cursorScreenPos.y + offset.y + itemSize.y / 2 - alpha * 4 + 10)
		local arrowLeft = imgui.ImVec2(tooltipPosition.x - 7, tooltipPosition.y - itemSize.y - 3)
		local arrowRight = imgui.ImVec2(tooltipPosition.x + 7, tooltipPosition.y - itemSize.y - 3)
		local arrowTip = imgui.ImVec2(tooltipPosition.x, tooltipPosition.y - itemSize.y + 3)
		local tooltipColor = imgui.ColorConvertFloat4ToU32(imgui.ImVec4(color.x, color.y, color.z, alpha))

		imgui.SetNextWindowPos(imgui.ImVec2(tooltipPosition.x, tooltipPosition.y - itemSize.y - 3), imgui.Cond.Always, imgui.ImVec2(0.5, 1))
		imgui.PushStyleColor(imgui.Col.PopupBg, color)
		imgui.PushStyleColor(imgui.Col.Border, color)
		imgui.PushStyleColor(imgui.Col.Text, imgui.ImVec4(menuThemeConfig.input[1], menuThemeConfig.input[2], menuThemeConfig.input[3], 0.9))
		imgui.PushStyleVarVec2(imgui.StyleVar.WindowPadding, imgui.ImVec2(8, 8))
		imgui.PushStyleVarFloat(imgui.StyleVar.WindowRounding, 6)
		imgui.PushStyleVarFloat(imgui.StyleVar.Alpha, alpha)

		local tooltipWidth = ((function(text)
			local maxLineWidth = 0

			for line in text:gmatch("[^\n]+") do
				local textSize = imgui.CalcTextSize(line).x

				if maxLineWidth < textSize then
					maxLineWidth = textSize
				end
			end

			return maxLineWidth
		end)(hintText) + imgui.GetStyle().WindowPadding.x * 2) * 1.3

		imgui.SetNextWindowSize(imgui.ImVec2(tooltipWidth, -1), imgui.Cond.Always)
		imgui.Begin("##" .. hintId, _, imgui.WindowFlags.Tooltip + imgui.WindowFlags.NoResize + imgui.WindowFlags.NoScrollbar + imgui.WindowFlags.NoTitleBar)
		imgui.PushFont(fonts[18])

		for line in hintText:gmatch("[^\n]+") do
			if alignLeft then
				imgui.Text(line)
			else
				imgui.SetCursorPosX((tooltipWidth - imgui.CalcTextSize(line).x) / 2)
				imgui.Text(line)
			end
		end

		imgui.PopFont()
		imgui.End()
		imgui.PopStyleVar(3)
		imgui.PopStyleColor(3)
	end

	if canAnimate then
		local elapsedTime = os.clock() - POOL_HINTS[hintId].timer

		if elapsedTime <= animationDuration then
			local function clamp01(value)
				return value < 0 and 0 or value > 1 and 1 or value
			end

			local alpha = hintVisible and clamp01(elapsedTime / animationDuration) or clamp01(1 - elapsedTime / animationDuration)

			drawHint(alpha)
		elseif hintVisible then
			drawHint(1)
		end
	end

	imgui.SetCursorPos(cursorPos)
end

function imgui.Spinner(label, radius, thickness, color)
	local style = imgui.GetStyle()
	local cursorScreenPos = imgui.GetCursorScreenPos()
	local spinnerSize = imgui.ImVec2(radius * 2, (radius + style.FramePadding.y) * 2)

	imgui.Dummy(imgui.ImVec2(spinnerSize.x + style.ItemSpacing.x, spinnerSize.y))

	local windowDrawList = imgui.GetWindowDrawList()

	windowDrawList:PathClear()

	local segmentCount = 30
	local startAngle = 6.28 * math.abs(math.sin(imgui.GetTime() * 1.8) * (segmentCount - 5)) / segmentCount
	local endAngle = 6.28 * (segmentCount - 3) / segmentCount
	local center = imgui.ImVec2(cursorScreenPos.x + radius, cursorScreenPos.y + radius + style.FramePadding.y)

	for segmentIndex = 0, segmentCount do
		local angle = startAngle + segmentIndex / segmentCount * (endAngle - startAngle)

		windowDrawList:PathLineTo(imgui.ImVec2(center.x + math.cos(angle + imgui.GetTime() * 8) * radius, center.y + math.sin(angle + imgui.GetTime() * 8) * radius))
	end

	windowDrawList:PathStroke(color, false, thickness)

	return true
end

function imgui.BufferingBar(label, progress, size, backgroundColor, foregroundColor)
	local var_144_0 = imgui.GetStyle()
	local var_144_1 = size
	local windowDrawList = imgui.GetWindowDrawList()

	var_144_1.x = var_144_1.x - var_144_0.FramePadding.x * 2

	local cursorScreenPos = imgui.GetCursorScreenPos()

	imgui.Dummy(imgui.ImVec2(var_144_1.x, var_144_1.y))

	local var_144_4 = var_144_1.x * 0.85
	local var_144_5 = var_144_1.x - var_144_4

	windowDrawList:AddRectFilled(cursorScreenPos, imgui.ImVec2(cursorScreenPos.x + var_144_4, cursorScreenPos.y + var_144_1.y), backgroundColor)
	windowDrawList:AddRectFilled(cursorScreenPos, imgui.ImVec2(cursorScreenPos.x + var_144_4 * progress, cursorScreenPos.y + var_144_1.y), foregroundColor)

	return true
end

