	imgui.GetWindowDrawList():AddRectFilled(cursorScreenPos, imgui.ImVec2(cursorScreenPos.x + 2, cursorScreenPos.y + separatorHeight), imgui.GetColorU32Vec4(imgui.ImVec4(separatorColor[0], separatorColor[1], separatorColor[2], separatorColor[3] - 0.1)), 5)
