function imgui.ToggleButton(label, value, size)
	local duration = 1.0
	local cursorScreenPos = imgui.GetCursorScreenPos()
	local windowDrawList = imgui.GetWindowDrawList()
	local uiScale = getMenuUiScale()
	local buttonSize = imgui.ImVec2((size and size.x or 40) * uiScale, (size and size.y or 20) * uiScale)
	local visibleLabel = label:gsub("##.*$", "")
	local textSize = imgui.CalcTextSize(visibleLabel)
	local toggleAlpha = tonumber(kifir) or 1.0
	if toggleAlpha < 0 then toggleAlpha = 0 elseif toggleAlpha > 1 then toggleAlpha = 1 end
	local toggleColors = {
		enable = imgui.ImVec4(activeToggleColor[0], activeToggleColor[1], activeToggleColor[2], toggleAlpha),
		disable = imgui.ImVec4(inactiveToggleColor[0], inactiveToggleColor[1], inactiveToggleColor[2], toggleAlpha)
	}
	local padding = 5 * uiScale
	local labelOffset = {
		x = 4 * uiScale,
		y = cursorScreenPos.y + buttonSize.y / 2
	}
	local labelStart = imgui.ImVec2(cursorScreenPos.x + padding + labelOffset.x, labelOffset.y)
	local labelEnd = imgui.ImVec2(cursorScreenPos.x + buttonSize.x - padding - labelOffset.x, labelOffset.y)

	if AI_TOGGLE == nil then
		AI_TOGGLE = {}
	end

	if AI_TOGGLE[label] == nil then
		AI_TOGGLE[label] = {
			color = value[0] and toggleColors.enable or toggleColors.disable,
			pos = value[0] and labelEnd or labelStart
		}
	end

	local toggleState = AI_TOGGLE[label]

	imgui.BeginGroup()

	local cursorPos = imgui.GetCursorPos()
	local itemSpacing = imgui.GetStyle().ItemSpacing
	local clickableWidth = buttonSize.x
	local clickableHeight = math.max(buttonSize.y, textSize.y)

	-- Make the whole toggle row interactive, not only the switch itself.
	-- The same InvisibleButton now covers the switch, spacing and visible label.
	if #visibleLabel > 0 then
		clickableWidth = clickableWidth + itemSpacing.x + textSize.x
	end

	local clicked = imgui.InvisibleButton(label, imgui.ImVec2(clickableWidth, clickableHeight))

	if clicked then
		value[0] = not value[0]
		toggleState.clock = os.clock()
	end

	if #visibleLabel > 0 then
		-- Draw the label over the extended hit area without creating a second
		-- interactive widget. This prevents double toggles on a single click.
		imgui.SetCursorPos(imgui.ImVec2(cursorPos.x + buttonSize.x + itemSpacing.x, cursorPos.y + (buttonSize.y - textSize.y) / 2))
		imgui.Text(visibleLabel)
	end

	imgui.EndGroup()

	if toggleState.clock and duration >= os.clock() - toggleState.clock then
		toggleState.color = bringVec4To(imgui.ImVec4(toggleState.color), value[0] and toggleColors.enable or toggleColors.disable, toggleState.clock, duration)
		toggleState.pos = bringVec2To(imgui.ImVec2(toggleState.pos), value[0] and labelEnd or labelStart, toggleState.clock, duration)
	else
		toggleState.color = value[0] and toggleColors.enable or toggleColors.disable
		toggleState.pos = value[0] and labelEnd or labelStart
	end

	windowDrawList:AddRect(cursorScreenPos, imgui.ImVec2(cursorScreenPos.x + buttonSize.x, cursorScreenPos.y + buttonSize.y), imgui.ColorConvertFloat4ToU32(toggleState.color), 10, buttonStyleEnabled[0] and 15 or 0, 1.5)

	if buttonStyleEnabled[0] == true then
		windowDrawList:AddCircleFilled(toggleState.pos, padding, imgui.ColorConvertFloat4ToU32(toggleState.color))
	else
		windowDrawList:AddRectFilled(imgui.ImVec2(cursorScreenPos.x + 5 + (toggleState.pos.x - labelStart.x), cursorScreenPos.y + 5), imgui.ImVec2(cursorScreenPos.x + buttonSize.x - buttonSize.x / 1.5 + (toggleState.pos.x - labelStart.x), cursorScreenPos.y + buttonSize.y - 5), imgui.ColorConvertFloat4ToU32(toggleState.color), 1)
	end

	return clicked
end

function onWindowMessage(message, wparam, lparam)
	-- VK_HOME (0x24): the 3.56 hotkey mirrors /crr and is ignored while
	-- the player is typing or another SA:MP dialog owns the keyboard.
	if message == 257 and wparam == 36 and not isPauseMenuActive() and not sampIsChatInputActive() and not sampIsDialogActive() then
		consumeWindowMessage(true, false)
		onOpenMenu = true
		menuOpen = not menuOpen
		menuVisible[0] = menuOpen

		if replaceWindowEnabled[0] then
			var_0_71[0] = not var_0_71[0]
		end

		if menuOpen then
			zzztime = os.clock()
		else
			resetIO()
		end

		return
	end

	if (message == 256 or message == 257) and wparam == 27 and (menuOpen or sellWindowVisible[0] or marketState.emule_ExelPremium[0]) and not isPauseMenuActive() then
		consumeWindowMessage(true, false)

		if message == 257 and menuOpen then
			menuOpen = false


			menuVisible[0] = menuOpen

			resetIO()
		end

		if message == 257 and sellWindowVisible[0] and selectedItemInfo[1] ~= nil then
			closeCustomDialog(0)
		end

		if message == 257 and marketState.emule_ExelPremium[0] then
			marketState.emule_ExelPremium[0] = false
		end
	end

	if message == 257 and selectedItemInfo[1] ~= nil and sellWindowVisible[0] and wparam == 13 and not sampIsChatInputActive() then
		closeCustomDialog(1)
	end
end

function onScriptTerminate(script, quitGame)
	if script == thisScript() then
		-- Cancel every in-flight network worker before AutoReboot or MoonLoader unloads this Lua state.
		if type(telegramOriginalCleanup) == "function" then pcall(telegramOriginalCleanup) end
		if type(arzScriptOfflineCancelInFlight) == "function" then pcall(arzScriptOfflineCancelInFlight) end
		if type(arzAccountBridgeTick) == "function" then pcall(arzAccountBridgeTick) end
		if marketBuyRouteCleanup then
			pcall(marketBuyRouteCleanup)
		end

		if modificationState and modificationState.prepareEntityRemovalForTerminate then
			pcall(modificationState.prepareEntityRemovalForTerminate, quitGame == true)
		end


		-- Startup/reload chat is intentionally quiet. One info line is shown after successful load.

		local currentTime = os.time()

		print("script terminate info:")
		print(timers[37][1][1] .. "|" .. timers[37][1][2] - currentTime)
		print(timers[37][2][1] .. "|" .. timers[37][2][2] - currentTime)
		print(timers[37][3][1] .. "|" .. timers[37][3][2] - currentTime)
		print(timers[37][4][1] .. "|" .. timers[37][4][2] - currentTime)
		print(timers[37][5][1] .. "|" .. timers[37][5][2] - currentTime)
		print(timers[37][6][1] .. "|" .. timers[37][6][2] - currentTime)
		print(timers[37][7][1] .. "|" .. timers[37][7][2] - currentTime)
		print(timers[37][8][1] .. "|" .. timers[37][8][2] - currentTime)
		print(timers[37][9][1] .. "|" .. timers[37][9][2] - currentTime)
		print(timers[37][10][1] .. "|" .. timers[37][10][2] - currentTime)
		print("Server: " .. tostring(select(1, sampGetCurrentServerAddress())))

		if modificationState and modificationState.persistMainWindowSize then
			pcall(modificationState.persistMainWindowSize, true)
		end

		save_all()

		if next(marketState.activeObjects) then
			deAFKMessage(debug.getinfo(1, "l"), ">>> " .. #marketState.activeObjects)

			for objectKey, objectData in pairs(marketState.activeObjects) do
				deleteObject(objectData.modelHandle)
				deAFKMessage(debug.getinfo(1, "l"), "destroy VIP object > " .. objectData.modelHandle)
			end
		end

		if last_dialog_id ~= nil then
			sampSendDialogResponsed(last_dialog_id, 0, 0, false)
		end

		if dialogWorkerState[1] ~= nil then
			print("destroy wait_dialog_d[1]")
			dialogWorkerState[1]:terminate()
		end

		if sell_alitems_d ~= nil then
			print("destroy sell_alitems_d")
			sell_alitems_d:terminate()
		end

		if sellWorkerState[1] ~= nil then
			print("destroy kapibara_s[1]")
			sellWorkerState[1]:terminate()
		end

		if clearWorkerState[1] ~= nil then
			print("destroy clear_items_s[1]")
			clearWorkerState[1]:terminate()
		end

		if scanWorkerState[1] ~= nil then
			print("destroy scan_items_s[1]")
			scanWorkerState[1]:terminate()
		end
	end
end

