function bringVec4To(fromValue, toValue, startTime, duration)
	local elapsedTime = os.clock() - startTime

	if elapsedTime >= 0 and elapsedTime <= duration then
		local progress = elapsedTime / (duration / 100)

		return imgui.ImVec4(fromValue.x + progress * (toValue.x - fromValue.x) / 100, fromValue.y + progress * (toValue.y - fromValue.y) / 100, fromValue.z + progress * (toValue.z - fromValue.z) / 100, fromValue.w + progress * (toValue.w - fromValue.w) / 100), true
	end

	return duration < elapsedTime and toValue or fromValue, false
end

