function addToTable(destination, values)
	local found = false

	for valueIndex, value in ipairs(values) do
		if value == destination then
			found = true

			break
		end
	end

	if not found then
		table.insert(values, destination)
	end
end

function addToData(destination, key, value)
	if value == nil then
		table.insert(key, destination)
	else
		table.insert(key, value, destination)

		return true
	end
end

function loadFonts(fontSizes, rasterScale)
	local fontConfig = {}
	local iconRanges = imgui.ImFontConfig()
	local scale = math.max(1.0, math.min(1.5, tonumber(rasterScale) or 1.0))

	iconRanges.MergeMode = true
	iconRanges.PixelSnapH = true

	local var_171_2 = imgui.new.ImWchar[3](fa.min_range, fa.max_range, 0)

	local function addMarketFont(baseFontSize)
		local rasterSize = baseFontSize * scale
		if baseFontSize ~= 18 and baseFontSize ~= 20 and baseFontSize ~= 22 and baseFontSize ~= 24 and baseFontSize ~= 17 then
			return imgui.GetIO().Fonts:AddFontFromMemoryCompressedBase85TTF(logo_font, rasterSize, nil, imgui.GetIO().Fonts:GetGlyphRangesCyrillic())
		end

		return imgui.GetIO().Fonts:AddFontFromMemoryCompressedBase85TTF(menu_font, rasterSize, nil, imgui.GetIO().Fonts:GetGlyphRangesCyrillic())
	end

	for fontIndex, baseFontSize in ipairs(fontSizes) do
		if baseFontSize ~= 18 then
			-- Keep stable lookup keys (fonts[17], fonts[20], etc.) while the
			-- glyph atlas itself is built at the requested percentage.
			fontConfig[baseFontSize] = addMarketFont(baseFontSize)
		end
	end

	-- FontAwesome MergeMode always targets fonts[18], regardless of list order.
	fontConfig[18] = addMarketFont(18)
	imgui.GetIO().Fonts:AddFontFromMemoryCompressedBase85TTF(fa.get_font_data_base85(), 16 * scale, iconRanges, var_171_2)

	return fontConfig
end

