	if saveSuccess == false then
		AFKMessage(u8:decode("Ошибка сохранения конфига! Сообщите разработчику! https://t.me/freym1337"))
		print(u8:decode("Сохранение конфига ") .. tostring(fileName) .. u8:decode(" прошло не удачно! Сообщите поддержке!"))
		print(tostring(saveSuccess) .. " | " .. tostring(saveError))
		saveLog(u8:decode("Сохранение конфига ") .. tostring(fileName) .. u8:decode(" прошло не удачно! Сообщите поддержке!"))
		saveLog(tostring(saveSuccess) .. " | " .. tostring(saveError))
	end

	return saveSuccess
end

function string.nlower(text)
	local lowerText = string.lower(text)

	for character in text:gmatch(".") do
		if string.byte(character) >= 192 and string.byte(character) <= 223 or string.byte(character) == 168 then
			lowerText = string.gsub(lowerText, character, string.char(string.byte(character) == 168 and string.byte(character) + 16 or string.byte(character) + 32), 1)
		end
	end

	return lowerText
end

