	imgui.CenterText("Настройки")
	imgui.PushItemWidth(150)

	if imgui.ToggleButton("Всегда конвертировать [VC$/SA$]", alwaysConvert) then
		ini.cfg.Always_convert = alwaysConvert[0]

		save_all()
	end

