function create_dialog(dialogId, dialogTitle, dialogText, button1, button2, style)
	deAFKMessage(debug.getinfo(1, "l"), "create custom dialog")
	lua_thread.create(function()
		wait(25)

		local bitStream = raknetNewBitStream()

		raknetBitStreamWriteInt16(bitStream, dialogId)
		raknetBitStreamWriteInt8(bitStream, dialogTitle)
		raknetBitStreamWriteInt8(bitStream, tonumber(dialogText:len()))
		raknetBitStreamWriteString(bitStream, tostring(dialogText))
		raknetBitStreamWriteInt8(bitStream, tonumber(button1:len()))
		raknetBitStreamWriteString(bitStream, tostring(button1))
		raknetBitStreamWriteInt8(bitStream, tonumber(button2:len()))
		raknetBitStreamWriteString(bitStream, tostring(button2))
		raknetBitStreamEncodeString(bitStream, tostring(style))
		raknetEmulRpcReceiveBitStream(61, bitStream)
		raknetDeleteBitStream(bitStream)
	end)
end

function set_keyboard_layout_to_russian()
	local var_208_0 = "00000419"
	local var_208_1 = ffi.C.LoadKeyboardLayoutA(var_208_0, 1)

