function containsItem(items, itemName, itemEnchant)
	if itemEnchant then
		for itemIndex, itemData in ipairs(items) do
			if itemData == itemName then
				return true
			end
		end
	else
		for itemIndex, itemData in ipairs(items) do
			if itemData.name == itemName then
				return true
			end
		end
	end

	return false
end

function updateList()
	if doesFileExist(buyJsonPath) then
		local buyJsonData = readJsonFile(buyJsonPath)

		if buyJsonData ~= nil then
			normalizedItems.buy = {}

			for itemIndex, itemData in pairs(buyJsonData) do
				table.insert(normalizedItems.buy, string.nlower(itemData))
			end
		end
	end

	if doesFileExist(sellJsonPath) then
		local sellJsonData = readJsonFile(sellJsonPath)

		if sellJsonData ~= nil then
			normalizedItems.sell = {}

			for itemIndex, itemData in pairs(sellJsonData) do
				table.insert(normalizedItems.sell, string.nlower(itemData.item))
			end
		end
	end
end

