function sampGetPlayerIdByNickname(playerName)
	local localPlayerId = select(2, sampGetPlayerIdByCharHandle(PLAYER_PED))

	if tostring(playerName) == sampGetPlayerNickname(localPlayerId) then
		return localPlayerId
	end

	for playerId = 0, sampGetMaxPlayerId() do
		if sampIsPlayerConnected(playerId) and sampGetPlayerNickname(playerId) == tostring(playerName) then
			return playerId
		end
	end

	return -1
end

