priceDownloadInProgress = priceDownloadInProgress or false

function averagePriceGcStep(stepCount)
	local count = tonumber(stepCount) or 4
	for _ = 1, count do
		pcall(collectgarbage, "step", 96)
		wait(0)
	end
end

function fetchAveragePriceResponse(url, timeoutSeconds)
	if arzScriptOfflineReject("http", url) then
		return nil, nil, "offline_mode"
	end

	if not effilLoaded or not effil then
		return nil, nil, "effil unavailable"
	end

	local requestThread
	local proxyRequest = false
	local proxyThread, proxyEnabled, proxyError = arzProxyCreateHttpThread(
		"GET",
		url,
		{ headers = { ["Accept-Encoding"] = "identity" } },
		arzProxyNextRequestKey("avgprice"),
		timeoutSeconds or 90
	)

	if proxyEnabled then
		proxyRequest = true
		if not proxyThread then
			return nil, nil, "proxy request blocked: " .. tostring(proxyError)
		end
		requestThread = proxyThread
	else
		local createOk, directThread = pcall(function()
			return effil.thread(function(targetUrl)
				local requests = require("requests")
				local requestOk, response = pcall(requests.request, "GET", targetUrl, {
					headers = {
						["Accept-Encoding"] = "identity"
					}
				})

				if not requestOk then
					return false, tostring(response)
				end

				local statusCode = tonumber(response and response.status_code) or 0
				local responseText = type(response and response.text) == "string" and response.text or ""
				return true, statusCode, responseText
			end)(url)
		end)
		if not createOk or not directThread then
			return nil, nil, "cannot start request: " .. tostring(directThread)
		end
		requestThread = directThread
	end

	local startedAt = os.time()
	local timeout = tonumber(timeoutSeconds) or 90

	while true do
		if ARZ_SCRIPT_OFFLINE then
			pcall(function()
				if requestThread.cancel then requestThread:cancel() end
			end)
			return nil, nil, "offline_mode"
		end

		local statusOk, threadStatus, threadError = pcall(function()
			return requestThread:status()
		end)

		if not statusOk then
			return nil, nil, "request status failed: " .. tostring(threadStatus)
		end

		if threadError then
			return nil, nil, "request thread failed: " .. tostring(threadError)
		end

		if threadStatus == "completed" then
			local getOk, requestOk, statusOrError, responseText = pcall(function()
				return requestThread:get(0)
			end)

			if not getOk then
				return nil, nil, "request result failed: " .. tostring(requestOk)
			end

			if not requestOk then
				return nil, nil, tostring(statusOrError)
			end

			if proxyRequest then
				local response = statusOrError
				if type(response) ~= "table" then
					return nil, nil, "proxy returned invalid response"
				end
				return tonumber(response.status_code) or 0, type(response.text) == "string" and response.text or "", nil
			end

			return tonumber(statusOrError) or 0, type(responseText) == "string" and responseText or "", nil
		elseif threadStatus == "canceled" then
			return nil, nil, "request canceled"
		end

		if os.time() - startedAt >= timeout then
			pcall(function()
				if requestThread.cancel then
					requestThread:cancel()
				end
			end)
			return nil, nil, "request timeout"
		end

		wait(0)
	end
end

function get_prices()
	if priceDownloadInProgress then
		pcall(sendNotify, u8:decode("Загрузка средних цен уже идёт."))
		return
	end

	local serverName = sampGetCurrentServerName()
	if type(serverName) ~= "string" or not serverName:find("Arizona") then
		AFKMessage(u8:decode("Вы не на Аризона Рп!"))
		return
	end

	local playerIdOk, playerId = sampGetPlayerIdByCharHandle(PLAYER_PED)
	local nickname = playerIdOk and sampGetPlayerNickname(playerId) or ""
	local viceCityServerId = type(nickname) == "string" and nickname:match("%[(%-?%d+)%]") or nil
	local detectedServerSlug = viceCityServerId ~= nil and serverSlugById[viceCityServerId]
		or serverName:match("|%s*(.+)% |")
		or serverName:match("|%s*(.+)")

	local serverSlug = detectedServerSlug
	if serverSlug == nil or serverSlug == "" then
		pcall(sendNotify, u8:decode("Ошибка: не удалось определить сервер для средних цен."))
		return
	end

	if serverIdByAddress[ip] ~= 0 then
		serverSlug = string.lower(serverSlug):gsub(" ", "-")
	end

	local baseDir = getWorkingDirectory() .. "/ArzMarket/UsersInfo/"
	local jobs = {
		{
			key = "sell_",
			url = "https://raw.githubusercontent.com/FREYM1337/forumnick/main/avg_price/info_users_sell_" .. serverSlug .. ".json",
			path = baseDir .. "info_users_sell_" .. serverSlug .. ".json"
		},
		{
			key = "buy_",
			url = "https://raw.githubusercontent.com/FREYM1337/forumnick/main/avg_price/info_users_buy_" .. serverSlug .. ".json",
			path = baseDir .. "info_users_buy_" .. serverSlug .. ".json"
		},
		{
			key = "sell_vc",
			url = "https://raw.githubusercontent.com/FREYM1337/forumnick/refs/heads/main/avg_price/info_users_sell_vc.json",
			path = baseDir .. "info_users_sell_vc.json"
		},
		{
			key = "buy_vc",
			url = "https://raw.githubusercontent.com/FREYM1337/forumnick/main/avg_price/info_users_buy_vc.json",
			path = baseDir .. "info_users_buy_vc.json"
		}
	}

	priceDownloadInProgress = true
	pcall(sendNotify, u8:decode("Загрузка цен... 0/4"))

	lua_thread.create(function()
		local finishedCount = 0
		local failedCount = 0

		for _, job in ipairs(jobs) do
			local jobOk = false
			local errorText = nil
			local responseText = nil

			if not avgPriceSourceIsEnabled(job.key) then
				-- A disabled source is intentionally skipped and kept out of RAM.
				priceData[job.key] = nil
				jobOk = true
			else
				local statusCode, fetchedText, requestError = fetchAveragePriceResponse(job.url, 90)
				responseText = fetchedText

				if not avgPriceSourceIsEnabled(job.key) then
					responseText = nil
					priceData[job.key] = nil
					jobOk = true
				elseif requestError then
					errorText = "request failed: " .. tostring(requestError)
				elseif statusCode ~= 200 and statusCode ~= 304 then
					errorText = "HTTP " .. tostring(statusCode)
				elseif statusCode == 304 and (type(responseText) ~= "string" or responseText == "") then
					local cacheOk, cached = pcall(readJsonFile, job.path, {})
					if cacheOk and type(cached) == "table" and next(cached) ~= nil then
						priceData[job.key] = cached
						jobOk = true
					else
						errorText = "HTTP 304 without usable cache"
					end
				elseif type(responseText) ~= "string" or responseText == "" then
					errorText = "empty response"
				else
					print("[ArzMarket avg_price] received " .. job.key .. ": " .. tostring(#responseText) .. " bytes")

					priceData[job.key] = nil
					averagePriceGcStep(4)

					local decoded, decodeError = decodeJsonSafe(responseText)
					if type(decoded) == "table" then
						local saved, saveError = writeEncodedFile(job.path, responseText)
						priceData[job.key] = decoded

						if saved then
							jobOk = true
						else
							errorText = "cache write failed: " .. tostring(saveError)
						end
					else
						local cacheOk, cached = pcall(readJsonFile, job.path, {})
						if cacheOk and type(cached) == "table" and next(cached) ~= nil then
							priceData[job.key] = cached
						end
						errorText = "invalid JSON: " .. tostring(decodeError)
					end
				end
			end

			responseText = nil
			averagePriceGcStep(4)

			finishedCount = finishedCount + 1
			if not jobOk then
				failedCount = failedCount + 1
				print("[ArzMarket avg_price] " .. job.key .. ": " .. tostring(errorText))
			end

			local suffix = jobOk and "" or u8:decode(" | ошибка")
			pcall(sendNotify, u8:decode("Загрузка цен... ") .. finishedCount .. "/4" .. suffix)
			wait(0)
		end

		priceDownloadInProgress = false
		lowPriceGuardLoadedServerSlug = serverSlug
		lowPriceGuardLastRefreshAt = os.clock()
		averagePriceGcStep(4)

		if failedCount == 0 then
			pcall(sendNotify, u8:decode("Средние цены успешно загружены. 4/4"))
		else
			pcall(sendNotify, u8:decode("Загрузка цен завершена. Ошибок: ") .. failedCount .. "/4")
		end
	end)
end

