function script_Manager()
	download_scripts = {}

	asyncHttpRequest("GET", "https://raw.githubusercontent.com/FREYM1337/forumnick/refs/heads/main/scripts_list.json", {}, function(scriptsListResponse)
		if scriptsListResponse.status_code == 200 or scriptsListResponse.status_code == 304 then
			wait(1000)

			download_scripts[1] = decodeJson(scriptsListResponse.text)

			for scriptName, scriptData in pairs(download_scripts[1]) do
				if doesFileExist(getWorkingDirectory() .. "/ArzMarket/resource/" .. scriptName .. scriptData.unic .. ".png") then
				else
					local var_254_0 = require("moonloader").download_status

					download_id = downloadUrlToFile(scriptData.png .. ".png", getWorkingDirectory() .. "/ArzMarket/resource/" .. scriptName .. scriptData.unic .. ".png", function(downloadId, downloadStatus)
						if downloadStatus == var_254_0.STATUS_ENDDOWNLOADDATA then
						end
					end)
				end
			end
		else
			deAFKMessage(debug.getinfo(1, "l"), "error1 " .. tostring(scriptsListResponse.status_code))

			download_scripts = nil
		end
	end, function(scriptsListError)
		deAFKMessage(debug.getinfo(1, "l"), "error ")

		download_scripts = nil
	end)
	asyncHttpRequest("GET", "https://raw.githubusercontent.com/FREYM1337/forumnick/main/ArzMarketV2/mods_list.json", {}, function(modsListResponse)
		if modsListResponse.status_code == 200 or modsListResponse.status_code == 304 then
			wait(1000)

			download_scripts[2] = decodeJson(modsListResponse.text)

			for modName, modData in pairs(download_scripts[2]) do
				if doesFileExist(getWorkingDirectory() .. "/ArzMarket/resource/" .. modName .. modData.unic .. ".png") then
				else
					local var_257_0 = require("moonloader").download_status

					download_id = downloadUrlToFile(modData.png .. ".png", getWorkingDirectory() .. "/ArzMarket/resource/" .. modName .. modData.unic .. ".png", function(downloadId, downloadStatus)
						if downloadStatus == var_257_0.STATUS_ENDDOWNLOADDATA then
						end
					end)
				end
			end
		else
			deAFKMessage(debug.getinfo(1, "l"), "error1 " .. tostring(modsListResponse.status_code))

			download_scripts = nil
		end
	end, function(modsListError)
		download_scripts = nil
	end)
end

function sputnik_Manager()
	asyncHttpRequest("GET", "https://raw.githubusercontent.com/FREYM1337/forumnick/refs/heads/main/sputnik.json", {}, function(sputnikListResponse)
		if sputnikListResponse.status_code == 200 or sputnikListResponse.status_code == 304 then
			wait(1000)

			marketState.download_sputnik = decodeJson(sputnikListResponse.text)

			local sputnikDataFile = io.open("moonloader/ArzMarket/resource/sputnik/sputnik.json", "w")

			if sputnikDataFile then
				sputnikDataFile:write(sputnikListResponse.text)
				sputnikDataFile:close()
			end

			for sputnikName, sputnikData in pairs(marketState.download_sputnik) do
				if doesFileExist(getWorkingDirectory() .. "/ArzMarket/resource/sputnik/" .. sputnikName .. sputnikData.unic .. ".png") then
				else
					local var_261_1 = require("moonloader").download_status

					download_id = downloadUrlToFile(sputnikData.png .. ".png", getWorkingDirectory() .. "/ArzMarket/resource/sputnik/" .. sputnikName .. sputnikData.unic .. ".png", function(downloadId, downloadStatus)
						if downloadStatus == var_261_1.STATUS_ENDDOWNLOADDATA then
						end
					end)
				end
			end
		else
			deAFKMessage(debug.getinfo(1, "l"), "error1 " .. tostring(sputnikListResponse.status_code))

			marketState.download_sputnik = nil
		end
	end, function(sputnikListError)
		deAFKMessage(debug.getinfo(1, "l"), "error ")

		marketState.download_sputnik = nil
	end)

	for sputnikName, sputnikData in pairs(menuThemeConfig.customSputniks) do
		if doesFileExist(getWorkingDirectory() .. "/ArzMarket/resource/sputnik/" .. sputnikName .. ".png") then
		else
			local var_260_0 = require("moonloader").download_status

			download_id = downloadUrlToFile(sputnikData.png, getWorkingDirectory() .. "/ArzMarket/resource/sputnik/" .. sputnikName .. ".png", function(downloadId, downloadStatus)
				return
			end)
		end
	end
end

