function show_pricesz(itemName, itemEnchant)
	if timers[5] == nil then
		timers[5] = os.time()
		lowPriceGuardRefreshPriceData()
	end

	if priceData.buy_ == nil and priceData.buy_vc == nil and priceData.sell_ == nil and priceData.sell_vc == nil then
		return
	end

	local configuredSellPrice = 0
	local configuredBuyPrice = 0

	for itemIndex, itemData in pairs(sellList) do
		if itemData.name:gsub("%(%+%d+%)", "") == itemName then
			configuredSellPrice = itemData.price
		end
	end

	for itemIndex, itemData in pairs(buyList) do
		if itemData.name:gsub("%(%+%d+%)", "") == itemName then
			configuredBuyPrice = itemData.price
		end
	end

	imgui.PushFont(fonts[17])
	imgui.SetCursorPosX(imgui.GetCursorPos().x + 5)
	imgui.TextDisabled("Покупка VC$ за " .. ffi.string(buyVcBuffer) .. " $")
	imgui.SetCursorPosX(imgui.GetCursorPos().x + 5)
	imgui.SameLine(219)
	imgui.TextDisabled("Продажа VC$ за " .. ffi.string(sellVcBuffer) .. " $")
	imgui.SetCursorPosX(imgui.GetCursorPos().x + 5)
	imgui.SetCursorPosY(imgui.GetCursorPos().y + 5)
	imgui.Text(u8("$ ") .. moneySeparator(configuredBuyPrice) .. " скупаю")
	imgui.SameLine(219)
	imgui.Text(u8("$ ") .. moneySeparator(configuredSellPrice) .. " продаю")
	imgui.CustomSeparator(imgui.GetWindowWidth() - 10)
	imgui.SetCursorPosY(imgui.GetCursorPos().y - 4)
	imgui.Scroller("vvvvvv##" .. itemEnchant + 1, 100, 600, imgui.IsMouseDown(0) and 0 or imgui.HoveredFlags.AllowWhenBlockedByActiveItem)

	local averageExchangeRate = math.max(1, ((tonumber(ffi.string(buyVcBuffer)) or 0) + (tonumber(ffi.string(sellVcBuffer)) or 0)) / 2)

	imgui.Columns(2, "coloms##" .. itemEnchant + 1, false)

	local historyDays = 200
	local historyDates = {}

	for dayOffset = 1, historyDays do
		historyDates[dayOffset] = os.date("%Y-%m-%d", os.time() - 86400 * (dayOffset - 1))
	end

	imgui.SetColumnWidth(0, 215)
	imgui.TextDisabled("Статистика покупок")
	imgui.NextColumn()
	imgui.TextDisabled("Статистика продаж")
	imgui.NextColumn()

	for dateIndex, date in pairs(historyDates) do
		local buySaFound
		local buySaEntryIndex

		if priceData.buy_ ~= nil and priceData.buy_[itemName] ~= nil then
			for buySaIndex = 1, historyDays do
				if priceData.buy_[itemName].list[buySaIndex] and type(priceData.buy_[itemName].list[buySaIndex][2]) == "number" and priceData.buy_[itemName].list[buySaIndex][1] == date then
					buySaFound = true
					buySaEntryIndex = buySaIndex

					imgui.SetCursorPosY(imgui.GetCursorPos().y + 15)
					imgui.TextDisabled(u8(priceData.buy_[itemName].list[buySaIndex][1] .. " | SA$ " .. moneySeparator(priceData.buy_[itemName].list[buySaIndex][3]) .. " "))
					imgui.SetCursorPosX(imgui.GetCursorPos().x + 15)
					imgui.Text(u8("SA$ " .. moneySeparator(math.floor(priceData.buy_[itemName].list[buySaIndex][3] / priceData.buy_[itemName].list[buySaIndex][2])) .. " (" .. moneySeparator(priceData.buy_[itemName].list[buySaIndex][2]) .. u8:decode(" шт)")))
				end
			end
		end

		if priceData.buy_vc ~= nil and priceData.buy_vc[itemName] ~= nil then
			for buyVcIndex = 1, historyDays do
				if priceData.buy_vc[itemName].list[buyVcIndex] and type(priceData.buy_vc[itemName].list[buyVcIndex][2]) == "number" and priceData.buy_vc[itemName].list[buyVcIndex][1] == date then
					if buySaFound ~= true then
						imgui.SetCursorPosY(imgui.GetCursorPos().y + 15)
						imgui.TextDisabled(u8(priceData.buy_vc[itemName].list[buyVcIndex][1] .. " | VC$ " .. moneySeparator(priceData.buy_vc[itemName].list[buyVcIndex][3]) .. " "))
					end

					imgui.SetCursorPosX(imgui.GetCursorPos().x + 15)
					imgui.Text(u8("VC$ " .. moneySeparator(math.floor(priceData.buy_vc[itemName].list[buyVcIndex][3] / priceData.buy_vc[itemName].list[buyVcIndex][2])) .. " (" .. moneySeparator(priceData.buy_vc[itemName].list[buyVcIndex][2]) .. u8:decode(" шт)")))

