	imgui.SameLine()
	imgui.SetCursorPosX(imgui.GetWindowWidth() - 210)
	imgui.SetCursorPosY(imgui.GetCursorPos().y - 2)
	imgui.TextColoredRGB(u8:decode("{888888}Сохранение задержки: "))
	imgui.SameLine()
	imgui.SetCursorPosX(imgui.GetWindowWidth() - 35)
	imgui.SetCursorPosY(imgui.GetCursorPos().y - 4)

	if imgui.CustomCheckbox("##22", imguiNew.bool(ini.cfg.isEnableSaveDelayAutoAd), 0.1, 29) then
		ini.cfg.isEnableSaveDelayAutoAd = not ini.cfg.isEnableSaveDelayAutoAd

		save_all()
	end

	imgui.Hint("savetimer1", "Если функция включена - тайминг когда вы отправили сообщение будет оставаться сохраненным в системе.\nПоясняем, если вы отправили сообщение, затем в карточке изменили задержку, то...\nскрипт расчитает новый тайминг до следующего сообщения.\n\nЕсли функция Выключена - то задержка каждый раз будет обнуляться при изменениях задержек.", false)
	imgui.EndChild()
	imgui.PopStyleColor()
	imgui.SetCursorPosY(imgui.GetCursorPos().y + 20)
	imgui.CustomSeparator(imgui.GetWindowWidth() + 25)
	imgui.SetCursorPosY(imgui.GetCursorPos().y + 20)

	if #autoAdProfiles == 0 then
		imgui.SetCursorPosY(imgui.GetCursorPos().y + 50)
		imgui.CenterText("Нет добавленных авто-реклам")
		imgui.CenterText("Добавьте первую рекламу чтобы начать")
	else
		imgui.SetCursorPosX(20)
		imgui.TextColoredRGB(u8:decode("{ffffff}Список авто-реклам:"))
		imgui.SetCursorPosY(imgui.GetCursorPos().y + 10)

		for profileId, adProfile in pairs(autoAdProfiles) do
			local adCommand, adSettings = normalizeAutoAdProfile(adProfile)
			imgui.SetCursorPosX(15)
			imgui.PushStyleColor(imguiCol.ChildBg, adProfile.isEnabled and imgui.ImVec4(0.12, 0.22, 0.12, 0.5) or imgui.ImVec4(0.12, 0.12, 0.12, 0.5))
			imgui.PushStyleVarFloat(imgui.StyleVar.ChildRounding, 6)
			imgui.PushStyleVarFloat(imgui.StyleVar.ChildBorderSize, 1)
			imgui.BeginChild("ad_card_" .. profileId, imgui.ImVec2(imgui.GetWindowWidth() - 30, 132), true)
			imgui.SetCursorPos(imgui.ImVec2(15, 12))
			imgui.TextColoredRGB(adProfile.isEnabled and u8:decode("{00ff00}+ Активно") or u8:decode("{ff0000}- Неактивно"))
			imgui.Hint("isEnabledP" .. profileId, "После нажатия вы " .. (adProfile.isEnabled and "выключите" or "включите") .. " статус пиара.", false)

			if imgui.IsItemClicked() then
				if adProfile.isTimer > 0 and adProfile.isPiarText ~= "" then
					local canToggle = true

					if adCommand == "/ad" and not adProfile.isEnabled then
						for otherId, otherProfile in pairs(autoAdProfiles) do
							local otherCommand = normalizeAutoAdProfile(otherProfile)

							if otherId ~= profileId and otherProfile.isEnabled and otherCommand == "/ad" then
								canToggle = false
								sendNotify(u8:decode("Одновременно можно включить только один профиль /ad."))
								break
							end
						end
					end

					if canToggle then
						adProfile.isEnabled = not adProfile.isEnabled
					end

					writeJsonFile(autoAdProfiles, "moonloader/ArzMarket/vrProfile.json")
				else
					sendNotify(u8:decode("Задержка не может быть меньше 1 секунды! Текст пиара не может быть пустой!"))
				end

				if adCommand == "/ad" then
					adSettings.isRetry.osTime = os.time()
				end
			end

			imgui.SameLine()
			imgui.SetCursorPosX(103)
			imgui.TextColoredRGB(u8:decode("{cccccc} | Авто-реклама отправится через: ") .. math.max(0, adProfile.isTimer - (os.time() - adProfile.osTime)) .. u8:decode(" секунд."))
			imgui.SetCursorPos(imgui.ImVec2(15, 45))
			imgui.PushItemWidth(imgui.GetWindowWidth() - 180)

			local var_275_5 = imgui.new.char[256](u8(adProfile.isPiarText))

			if imgui.InputTextWithHintD("##text_" .. profileId, "Текст рекламного сообщения...", var_275_5, ffi.sizeof(var_275_5)) then
				adProfile.isPiarText = u8:decode(ffi.string(var_275_5))

				writeJsonFile(autoAdProfiles, "moonloader/ArzMarket/vrProfile.json")
			end

			imgui.PopItemWidth()
			imgui.Hint("text_p" .. profileId, "Текст для пиара в чате", false)
			imgui.SameLine()
			imgui.SetCursorPosX(imgui.GetWindowWidth() - 160)
			imgui.PushItemWidth(70)

			local var_275_6 = imgui.new.char[256]("" .. adProfile.isTimer)

			if imgui.InputTextWithHintD("##timer_" .. profileId, "(сек)", var_275_6, ffi.sizeof(var_275_6), imgui.InputTextFlags.CharsDecimal) and u8:decode(ffi.string(var_275_6)):match("^%d+$") then
				local var_275_7 = stringToCount(u8:decode(ffi.string(var_275_6)))

				if var_275_7 then
					adProfile.isEnabled = false
					adProfile.isTimer = var_275_7

					writeJsonFile(autoAdProfiles, "moonloader/ArzMarket/vrProfile.json")
				end
			end

			imgui.PopItemWidth()
			imgui.Hint("timer_p" .. profileId, "Задержка пиара в секундах.", false)
