				if imgui.IsMouseClicked(0) then
					AFKMessage(u8:decode("Сохранено."))

					marketState.edit_sputnik = false

					sampSetCursorMode(0)
					writeJsonFile(menuThemeConfig, menuThemePath)

					break
				end

				wait(0)
			end
		end, var_276_18)
	end

	imgui.SameLine()
	imgui.PushItemWidth(60)

	if imgui.DragInt("##sputnikSizeX", marketState.sputnikSize.x, 1, 0, select(1, getScreenResolution()), "%.0f") then
		menuThemeConfig.sputnikSize.x = marketState.sputnikSize.x[0]

		writeJsonFile(menuThemeConfig, menuThemePath)
	end

	imgui.SameLine()

	if imgui.DragInt("##sputnikSizeY", marketState.sputnikSize.y, 1, 0, select(2, getScreenResolution()), "%.0f") then
		menuThemeConfig.sputnikSize.y = marketState.sputnikSize.y[0]

		writeJsonFile(menuThemeConfig, menuThemePath)
	end
	imgui.PopItemWidth()

	imgui.SameLine()
	imgui.Text(" Размер Спутника.")
	imgui.SetCursorPosY(imgui.GetCursorPos().y + 5)

	if imgui.ToggleButton("Фразы над головой.", marketState.isEnabledSputnikWords) then
		ini.cfg.isEnabledSputnikWords = marketState.isEnabledSputnikWords[0]
		timers[28][1] = os.time() - 888
		timers[28][2] = 1

		save_all()
	end

	imgui.EndCustomInvisibleChild()
	imgui.GetWindowDrawList():AddRect(imgui.ImVec2(var_276_17.x + 5, var_276_17.y + 22), imgui.ImVec2(var_276_17.x + imgui.GetWindowWidth() / 1.04, var_276_17.y + 100), imgui.GetColorU32Vec4(imgui.ImVec4(menuThemeConfig.Border[1], menuThemeConfig.Border[2], menuThemeConfig.Border[3], menuThemeConfig.Border[4])), 5, 0, 1.8)
	imgui.PopStyleColor(4)

	imgui.GetStyle().FrameBorderSize = 0

	imgui.PopFont()
end


function renderArzPaletteSettings()
	imgui.SetCursorPosY(imgui.GetCursorPos().y + 3)
	imgui.CenterText("Оформление")
	imgui.SetCursorPosY(imgui.GetCursorPos().y + 3)
	imgui.CustomSeparator(imgui.GetWindowWidth() - 20)
	imgui.SetCursorPosY(imgui.GetCursorPos().y + 5)
	imgui.TextDisabled("Палитра цветов")
	imgui.SetCursorPosY(imgui.GetCursorPos().y + 3)

	local available = imgui.GetContentRegionAvail().x
	local gap = imgui.GetStyle().ItemSpacing.x
	local buttonWidth = math.max(120, (available - gap) / 2)
	local currentKey = tostring(menuThemeConfig.palette_key or "arzmarket_default")

	for index, themeKey in ipairs(ARZ_THEME_ORDER) do
		local preset = ARZ_THEME_PRESETS[themeKey]
		local selected = currentKey == themeKey
		if selected then
			imgui.PushStyleColor(imgui.Col.Button, imgui.ImVec4(menuThemeConfig.active_selector_color[1], menuThemeConfig.active_selector_color[2], menuThemeConfig.active_selector_color[3], 0.85))
			imgui.PushStyleColor(imgui.Col.Border, imgui.ImVec4(menuThemeConfig.Border[1], menuThemeConfig.Border[2], menuThemeConfig.Border[3], 1))
			imgui.GetStyle().FrameBorderSize = 1
		end

		if imgui.Button(u8(preset.label) .. "##arz_palette_" .. themeKey, imgui.ImVec2(buttonWidth, 34)) then
			currentKey = arzPaletteSelect(themeKey)
		end

		if selected then
			imgui.GetStyle().FrameBorderSize = borderSideEnabled[0] and 1 or 0
			imgui.PopStyleColor(2)
		end

		if index % 2 == 1 and index < #ARZ_THEME_ORDER then
			imgui.SameLine()
		end
	end

	local activePreset = ARZ_THEME_PRESETS[currentKey] or ARZ_THEME_PRESETS.arzmarket_default
	imgui.SetCursorPosY(imgui.GetCursorPos().y + 3)
	imgui.TextDisabled(u8(activePreset.hint))
	imgui.SetCursorPosY(imgui.GetCursorPos().y + 5)
	imgui.CustomSeparator(imgui.GetWindowWidth() - 20)
	imgui.SetCursorPosY(imgui.GetCursorPos().y + 5)
	renderArzCustomPaletteSettings()
	imgui.CustomSeparator(imgui.GetWindowWidth() - 20)
	imgui.SetCursorPosY(imgui.GetCursorPos().y + 5)
end

function menu_settings()
	imgui.CustomInvisibleChild("menu_settings", imgui.ImVec2(-1, -1), true, imgui.WindowFlags.NoScrollWithMouse)
	imgui.Scroller("menu_settings1", 100, 600, imgui.HoveredFlags.AllowWhenBlockedByActiveItem)

	imgui.GetStyle().FrameBorderSize = borderSideEnabled[0] and 1 or 0

	imgui.PushFont(fonts[18])

	if modificationState.settingsInterfaceOpen then
		if imgui.Button("<  Основные настройки", imgui.ImVec2(math.min(250 * getMenuUiScale(), imgui.GetContentRegionAvail().x), 30)) then
			modificationState.settingsInterfaceOpen = false
			imgui.PopFont()
			imgui.EndCustomInvisibleChild()
			return
		end
		imgui.SetCursorPosY(imgui.GetCursorPos().y + 4)
		imgui.CustomSeparator(imgui.GetContentRegionAvail().x)
		imgui.SetCursorPosY(imgui.GetCursorPos().y + 4)
	end

	renderArzPaletteSettings()


	if imgui.ToggleButton("Размытие фона за меню", backgroundBlurEnabled) then
		-- One blur mode only: blur the game scene behind the menu.
		-- Legacy left/right flags are kept in sync for config compatibility,
		-- but no window/child draw list is blurred anymore.
		leftMenuBlurEnabled[0] = backgroundBlurEnabled[0]
		rightMenuBlurEnabled[0] = backgroundBlurEnabled[0]
		ini.cfg.background_blure = backgroundBlurEnabled[0]
		ini.cfg.left_menu_blur = backgroundBlurEnabled[0]
		ini.cfg.right_menu_blur = backgroundBlurEnabled[0]
		modificationState.requestBackgroundBlurReset()

		save_all()
	end


	if imgui.ToggleButton("Стиль переключателей", buttonStyleEnabled) then
		ini.cfg.button_style = buttonStyleEnabled[0]

		save_all()
	end

	if imgui.ToggleButton("Включить обводку элементов", borderSideEnabled) then
		ini.cfg.border_side = borderSideEnabled[0]

		save_all()
	end

	if imgui.ToggleButton("Тип обводки экрана", rgbWindowEnabled) then
		ini.cfg.rgb_window = rgbWindowEnabled[0]

		save_all()
	end

	if imgui.ToggleButton("Плавные открытия в меню", alphaMenuEnabled) then
		ini.cfg.alpha_menuS = alphaMenuEnabled[0]

		save_all()
	end


	imgui.Text("Размер интерфейса")
	imgui.TextDisabled("Текст, кнопки и элементы. Размер окна - мышью за правый нижний угол.")
	local appliedMenuScalePercent = math.max(100, math.min(150, math.floor(tonumber(ini.cfg.menu_scale_percent) or 100)))
	local menuScaleApplyWidth = 115
	local menuScaleGap = imgui.GetStyle().ItemSpacing.x
	local menuScaleAvailable = imgui.GetContentRegionAvail().x
	imgui.PushItemWidth(math.max(220 * getMenuUiScale(), menuScaleAvailable - menuScaleApplyWidth - menuScaleGap))
	imgui.SliderInt("##menu_scale_percent", menuScalePercent, 100, 150, "%d%%")
	imgui.PopItemWidth()

	if menuScalePercent[0] ~= appliedMenuScalePercent then
		imgui.SameLine()
		if imgui.Button("Применить", imgui.ImVec2(menuScaleApplyWidth, 0)) then
			local currentScrollY = math.max(0, tonumber(imgui.GetScrollY()) or 0)
			local currentScrollMax = math.max(0, tonumber(imgui.GetScrollMaxY()) or 0)
			local currentScrollRatio = currentScrollMax > 0 and math.max(0, math.min(1, currentScrollY / currentScrollMax)) or nil

			windowThemeConfig.pendingAppearanceRestore = {
				active = true,
				scrollY = currentScrollY,
				scrollRatio = currentScrollRatio,
				createdAt = os.time()
			}
			pcall(writeJsonFile, windowThemeConfig, windowThemePath)

			ini.cfg.lastCrrSelect = 3
			ini.cfg.menu_scale_percent = math.max(100, math.min(150, math.floor(tonumber(menuScalePercent[0]) or 100)))
			if modificationState and modificationState.persistMainWindowSize then
				pcall(modificationState.persistMainWindowSize, true)
			end
			save_all()
			thisScript():reload()
			return
		end
	end

	imgui.Text("Общая прозрачность интерфейса")
	imgui.TextDisabled("20% - почти прозрачный, 100% - полностью непрозрачный.")
	imgui.PushItemWidth(math.max(220 * getMenuUiScale(), imgui.GetContentRegionAvail().x * 0.55))
	if imgui.SliderInt("##menu_opacity_percent", menuOpacityPercent, 20, 100, "%d%%") then
		ini.cfg.menu_opacity_percent = math.max(20, math.min(100, math.floor(tonumber(menuOpacityPercent[0]) or 100)))
		save_all()
	end
	imgui.PopItemWidth()

	imgui.SliderFloat(" Скорость смена цвета [Контур]", rainbowSpeed, 0, 5)
	if imgui.SliderFloat(" Сила размытия", blurStrength, 0.5, 4.0) then
		local newBlurStrength = math.max(0.5, math.min(4.0, tonumber(blurStrength[0]) or 2.0))
		local previousBlurStrength = tonumber(ini.cfg.blur_strength) or 2.0
		ini.cfg.blur_strength = newBlurStrength

		if newBlurStrength < previousBlurStrength - 0.001 then
			modificationState.requestBackgroundBlurReset()
		end

		save_all()
	end

	imgui.PopFont()
	imgui.GetStyle().FrameBorderSize = 0

	if (tonumber(modificationState.appearanceRestoreFrames) or 0) > 0
		and modificationState.appearanceRestoreScrollY ~= nil then
		local maxScroll = math.max(0, tonumber(imgui.GetScrollMaxY()) or 0)
		local targetScroll = math.max(0, tonumber(modificationState.appearanceRestoreScrollY) or 0)
		local ratio = tonumber(modificationState.appearanceRestoreScrollRatio)

		-- UI scaling changes content height, so restore the relative scroll point.
		if ratio and maxScroll > 0 then
			targetScroll = maxScroll * math.max(0, math.min(1, ratio))
		elseif maxScroll > 0 then
			targetScroll = math.min(targetScroll, maxScroll)
		else
			targetScroll = 0
		end

		imgui.SetScrollY(targetScroll)
		modificationState.appearanceRestoreFrames = modificationState.appearanceRestoreFrames - 1
		if modificationState.appearanceRestoreFrames <= 0 then
			modificationState.appearanceRestoreScrollY = nil
			modificationState.appearanceRestoreScrollRatio = nil
		end
	end

	imgui.EndCustomInvisibleChild()
end

function openUrl(primaryUrl, alternativeUrl, primaryTitle, alternativeTitle, preferAlternative)
	if primaryUrl == nil then
		return
	end

	deAFKMessage(debug.getinfo(1, "l"), "open url > " .. tostring(primaryUrl) .. " | " .. tostring(alternativeUrl))

	if primaryUrl == nil or alternativeUrl == nil then
		get_cef("window.cef.Open('" .. tostring(primaryUrl) .. "', 1);")
	else
		marketState.youtubeLink, marketState.rutubeLink = {
			primaryUrl,
			primaryTitle
		}, {
			alternativeUrl,
			alternativeTitle
		}
		marketState.isOldMethodLink = preferAlternative
		marketState.videoSelector = true
	end
end

function sampev.onSendDialogResponse(dialogId, button, listIndex, inputText)
	if dialogId == LOW_PRICE_GUARD_DIALOG_ID then
		local pendingSide = LOW_PRICE_GUARD_PENDING_FORCE and LOW_PRICE_GUARD_PENDING_FORCE.side or nil
		local pendingCommand = LOW_PRICE_GUARD_PENDING_FORCE and LOW_PRICE_GUARD_PENDING_FORCE.command or nil
		LOW_PRICE_GUARD_PENDING_FORCE.side = nil
		LOW_PRICE_GUARD_PENDING_FORCE.command = nil

		if button == 1 and type(pendingSide) == "string" and type(pendingCommand) == "string" and pendingCommand ~= "" then
			LOW_PRICE_GUARD_FORCE_ONCE_SIDE = pendingSide
			LOW_PRICE_GUARD_FORCE_ONCE_EXPIRES = getGameTimer() + 2500
			lua_thread.create(function()
				wait(80)
				sampProcessChatInput(pendingCommand)
			end)
		end

		return false
	end
	if dialogId ~= 2 then
		timers[37][1] = {
			inputText,
			os.time()
		}
	end

	if marketState.autoCraft.visible and marketState.autoCraft.dialogId == dialogId and button == 1 then
		deAFKMessage("input craft > " .. inputText)

		local var_281_0 = tonumber(inputText:match("(%d+)"))

		if var_281_0 and var_281_0 > 1000 then
			deAFKMessage("start craft system > 1000 | " .. var_281_0)

			marketState.autoCraft.interfaceEditor = true
			marketState.autoCraft.autoCount = var_281_0
		elseif var_281_0 and var_281_0 <= 1000 then
			deAFKMessage("auto craft system disabled")

			marketState.autoCraft.interfaceEditor = false
			marketState.autoCraft.autoCount = var_281_0
		end
	end

	if marketState.openAfterCloseMenu then
		marketState.openAfterCloseMenu = false

		openCrr()
	end

	if ini.cfg.active_lavka_number ~= -1 and inputText == u8:decode("- [ArzMarket] Найти свою лавку. [") .. ini.cfg.active_lavka_number .. "]" and activeLavkaId ~= -1 and button == 1 then
		AFKMessage(u8:decode("Метка вашей лавки отображена на карте."))
		SendToServer("/findilavka " .. ini.cfg.active_lavka_number)
		sampSendDialogResponsed(last_dialog_id, 0, 0)

		return false
	end

	if marketState.SellOrBuyIdRemove == dialogId and button == 1 then
		marketState.SellOrBuyIdRemove = true
	end

	if marketState.SellOrBuyId == dialogId and button == 1 then
		marketState.SellOrBuyId = nil
		marketState.custom_Sell_Buy, marketState.customParams = true, inputText

		deAFKMessage(debug.getinfo(1, "l"), "[step 4/2] enable custom SELL_BUY")
	end

	if inputText:find(u8:decode("Открыть меню ArzMarket")) and button == 1 then
		openCrr()
	end

	if selectedItemInfo[1] ~= nil then
		selectedItemInfo[1] = nil
		averagePriceWindowVisible[0] = false
		premiumPriceDialogVisible[0] = false
		OnClose = true
	end

	if telegramUi.nalog_message[0] and inputText ~= "" then
		lastDialogInput[2] = tostring(inputText)
	end
end

function openCrr()
	kifir = 1
	menuOpen = not menuOpen
	menuVisible[0] = menuOpen

	if menuOpen then
		zzztime = os.clock()
	else
		if modificationState and modificationState.persistMainWindowSize then
			pcall(modificationState.persistMainWindowSize, true)
		end
		resetIO()
	end
end

function sampev.onSendClickTextDraw(textdrawId)
	timers[37][2] = {
		textdrawId,
		os.time()
	}
	last_textdraw_id = textdrawId

	if clearWorkerState[2] and textdrawId ~= 65535 then
		AFKMessage(u8:decode("Отключите очистку товара, тогда инвентарь будет доступен"))

		return false
	end

	if (is_invent_open ~= nil or marketState.custom_is_invent_open[1] ~= nil) and textdrawId == 65535 then
		is_invent_open = nil
		marketState.custom_is_invent_open[1] = nil
		invent_proper_check = nil
		invent_proper_checks = nil
		tblid = 0
		scannedInventoryEntries = {}
		clearInventoryEntries = {}
	end

	if (scanButtonVisible[0] or lavkaScanButtonVisible[0] or traderChatVisible[0] or clearSellButtonVisible[0]) and textdrawId == 65535 then
		if scanWorkerState[2] then
			if last_dialog_id ~= nil then
				sampSendDialogResponsed(last_dialog_id, 0, 0)
			end

			lets_gooooo = false

			if dialogWorkerState[1] ~= nil then
				lets_go = true
			end
		end

		if clearWorkerState[2] then
			if last_dialog_id ~= nil then
				sampSendDialogResponsed(last_dialog_id, 0, 0)
			end

			lets_gooooo_clear = false

			if dialogWorkerState[1] ~= nil then
				lets_go = true
			end

			clear_busy = false
		end

		traderChatVisible[0] = false
		scanButtonVisible[0] = false
		clearSellButtonVisible[0] = false
		lavkaScanButtonVisible[0] = false
		OnClose = true
	end
end

function sampev.onTextDrawSetString(textdrawId, text)
	timers[37][10] = {
		text,
		os.time()
	}

	if text == "PURCHASE" or text == "\x8CPO\x83A\x84A" then
		clearTextdrawState[4] = 1
		scanTextdrawState[4] = 1
	end

	if text == "SALE" or text == "CKY\x8CKA" then
		clearTextdrawState[4] = 0
		scanTextdrawState[4] = 0
	end

	if textdrawId == scanTextdrawState[1] or textdrawId == clearTextdrawState[1] then
		scannedInventoryEntries = {}
		clearInventoryEntries = {}

		if clearWorkerState[2] then
			if last_dialog_id ~= nil then
				sampSendDialogResponsed(last_dialog_id, 0, 0)
			end

			lets_gooooo_clear = false

			if dialogWorkerState[1] ~= nil then
				lets_go = true
			end

			clear_busy = false
		end

		clearTextdrawState[2] = text
		scanTextdrawState[2] = text
	end
end

function sampev.onTextDrawHide(textdrawId)
	if InventoryTriggerID == textdrawId then
		InventoryTriggerID = nil
		lavkaRadiusButtonVisible[0] = false
		OnClose = true
	end
end

function sampev.onShowTextDraw(textdrawId, textdrawData)
	if textdrawData.text:find("INFORMATION") or textdrawData.text == "\x85H\x81OPMA\x89\x85\x95" then
		deAFKMessage(debug.getinfo(1, "l"), "check information")

		information_id = textdrawId - 1
	end

	if textdrawData.text == "ON_SALE" or textdrawData.text == "HA_\x8CPO\x83A\x84E" then
		deAFKMessage(debug.getinfo(1, "l"), u8:decode("Открытие инвента"))

		is_invent_open = textdrawId
	end

	if is_invent_open ~= nil and tostring(textdrawData.position.y) == "365.22088623047" and tostring(textdrawData.position.x) == "250.25" and not tradeAutomationVisible[0] then
		clearSellButtonVisible[0] = true
		ClearTriggerID = textdrawId
		ClearListX, ClearListY = convertGameScreenCoordsToWindowScreenCoords(textdrawData.position.x + 43, textdrawData.position.y + 1)
		clearInventoryEntries = {}
		clearTextdrawState[1], clearTextdrawState[2] = textdrawId, textdrawData.text
	end

	if clearTextdrawState[1] ~= nil and not tradeAutomationVisible[0] and shopSlotIndexByPosition[textdrawData.position.x .. ", " .. textdrawData.position.y] then
		for entryIndex, inventoryEntry in pairs(clearInventoryEntries) do
			if inventoryEntry[2] == shopSlotIndexByPosition[textdrawData.position.x .. ", " .. textdrawData.position.y] then
				clearInventoryEntries[entryIndex][2] = 1337
			end
		end

		add_slot(clearInventoryEntries, {
			textdrawId,
			shopSlotIndexByPosition[textdrawData.position.x .. ", " .. textdrawData.position.y],
			textdrawData.modelId
		})
	end

	if traderEnabled[0] and textdrawData.position.x == 250.25 and tostring(textdrawData.position.y) == "267.41101074219" then
		trade_menu = vector3d(convertGameScreenCoordsToWindowScreenCoords(textdrawData.position.x - 135, textdrawData.position.y - 1))
		trader_name = textdrawData.text

		showTraderChat(trader_name)
	end


	if (textdrawData.text == "CLOSE" or textdrawData.text == "\x88AKP\x91\x8F\x92") and is_invent_open ~= nil then
		invent_proper_checks = textdrawData.position.y - 6
	end

	if (textdrawData.text == "INVENTORY" or textdrawData.text == "\x85H\x8BEH\x8FAP\x92") and is_invent_open ~= nil then
		tblid = 0
		scannedInventoryEntries = {}
		clearInventoryEntries = {}
		buttons_id = textdrawId
		invent_proper_check = textdrawData.position.x - 4
	end

	if textdrawData.text == "SHOP" or textdrawData.text == "MA\x82A\x88\x85H" then
		scanButtonVisible[0] = true
	end

	if (textdrawData.text == "CLOSE" or textdrawData.text == "\x88AKP\x91\x8F\x92") and tostring(textdrawData.position.y) == "233.57301330566" and tostring(textdrawData.position.x) == "441.10983276367" then
		lavkaRadiusButtonVisible[0] = true
		InventoryTriggerID = textdrawId
		InventoryTriggerX, InventoryTriggerY = convertGameScreenCoordsToWindowScreenCoords(textdrawData.position.x - 20, textdrawData.position.y + 12)
	end

	if (textdrawData.text == "INVENTORY" or textdrawData.text == "\x85H\x8BEH\x8FAP\x92") and textdrawData.position.x == 346.25 and tostring(textdrawData.position.y) == "369.68316650391" then
		wkafX, wkafY = convertGameScreenCoordsToWindowScreenCoords(textdrawData.position.x - 55, textdrawData.position.y - 1)
		lavkaScanButtonVisible[0] = true
	end

	if tostring(textdrawData.position.x) == "250.25" and tostring(textdrawData.position.y) == "365.22088623047" and scanButtonVisible[0] then
		kvadratX, kvadraty = convertGameScreenCoordsToWindowScreenCoords(textdrawData.position.x + 43, textdrawData.position.y + 1)
		scannedInventoryEntries = {}
		clearInventoryEntries = {}
		scanTextdrawState[1], scanTextdrawState[2] = textdrawId, textdrawData.text
	end

	if invent_proper_check ~= nil and invent_proper_checks ~= nil then
		if invent_proper_check < textdrawData.position.x and invent_proper_checks > textdrawData.position.y and tradeAutomationVisible[0] then
			if inventorySlotIndexByPosition[textdrawData.position.x .. ", " .. textdrawData.position.y] then
				add_slot(scannedInventoryEntries, {
					textdrawId,
					inventorySlotIndexByPosition[textdrawData.position.x .. ", " .. textdrawData.position.y] + tblid,
					textdrawData.selectable
				})
			end

			if tradeAutomationVisible[0] and fpsUpSell[0] then
				return false
			end
		end
	elseif scanTextdrawState[1] ~= nil then
		if textdrawData.text == "PURCHASE" or textdrawData.text == "\x8CPO\x83A\x84A" then
			scanTextdrawState[4] = 1
		end

		if textdrawData.text == "SALE" or textdrawData.text == "CKY\x8CKA" then
			scanTextdrawState[4] = 0
		end

		if shopSlotIndexByPosition[textdrawData.position.x .. ", " .. textdrawData.position.y] then
			add_slot(scannedInventoryEntries, {
				textdrawId,
				shopSlotIndexByPosition[textdrawData.position.x .. ", " .. textdrawData.position.y],
				textdrawData.selectable
			})
		end
	end
end

function showTraderChat(traderName)
	deAFKMessage("showTraderChat(" .. traderName .. ")")

	trader_name = traderName

	if traderName:match("%((%d+)%)") then
		trader_name = traderName:gsub("%((%d+)%)", "[%1]")
	end

	trade_chatM = {}
	traderChatVisible[0] = true

	local chatLogPath = ""

	for fileName in lfs.dir(os.getenv("USERPROFILE") .. "\\Documents\\GTA San Andreas User Files\\SAMP\\arizona\\chatlog\\") do
		if fileName:match("(%d%d%d%d%-%d%d%-%d%d)") == os.date("%Y-%m-%d", os.time()) then
			chatLogPath = os.getenv("USERPROFILE") .. "\\Documents\\GTA San Andreas User Files\\SAMP\\arizona\\chatlog\\" .. fileName
		end
	end

	local selectedChatLogPath = chatLogPath

	deAFKMessage(debug.getinfo(1, "l"), " last msg " .. chatLogPath)

	if doesFileExist(selectedChatLogPath) == true then
		for chatLine in io.lines(selectedChatLogPath) do
			local timeText, chatMessage = string.match(chatLine, "^%[(%d+:%d+:%d+)%] (.+)")

			if timeText and chatMessage then
				local recentMessage = checkMessageTime("[" .. timeText .. "] " .. chatMessage)

				if recentMessage ~= false then
					local playerName, playerId, colorCode, messageText = u8:decode(recentMessage):match(u8:decode("([^%s]+)%[(%d+)%]%s+говорит:%s*{([^}]+)}%s+(.*)"))

					if playerName == trader_name and colorCode == "B7AFAF" and messageText ~= nil then
						local wrappedLines = wrap_text(messageText, 30)

						for messageIndex, message in ipairs(wrappedLines) do
							deAFKMessage(debug.getinfo(1, "l"), " [EVENT] wrap_text " .. messageIndex .. " | " .. message)
							table.insert(trade_chatM, messageIndex == 1 and playerName .. "[" .. playerId .. u8:decode("] говорит: {B7AFAF}") .. message or "{B7AFAF}" .. message)

							if marketState.ChatTrade[1] == 1 then
								marketState.ChatTrade[2] = true
							end
						end
					end
				end
			end
		end
	end
end

function add_slot(entries, entry)
	table.insert(entries, entry)
end

function sampev.onPlaySound(soundId, position)
	if soundId == 6801 and (tradeAutomation.sell or scanWorkerState[1] ~= nil) and dialogWorkerState[1] ~= nil then
		lets_go = true
	end
end

function wait_dialog()
	local attemptCount = 0

	while true do
		if not tradeAutomation.sell and not scanWorkerState[2] and not clearWorkerState[2] then
			if dialogWorkerState[1] ~= nil then
				lets_go = true
			end

			deAFKMessage(debug.getinfo(1, "l"), "_______________________thread bug stop check!! " .. tostring(attemptCount))
			return
		end

		sampSendClickTextdraw(dialogWorkerState[2])

		if attemptCount > 1 and scanWorkerState[2] and last_dialog_id ~= nil then
			sampSendDialogResponsed(last_dialog_id, 0, 0)
		end

		if attemptCount > 1 and clearWorkerState[2] and last_dialog_id ~= nil then
			sampSendDialogResponsed(last_dialog_id, 0, 0)
		end

		attemptCount = attemptCount + 1

		wait(1000)
	end
end

function extractTimeFromMessage(message)
	local timeText = message:match("%[(%d+:%d+:%d+)%]")

	if not timeText then
		return nil
	end

	local hourText, minuteText, secondText = timeText:gsub("%[%s*(.-)%s*%]", "%1"):match("^(%d+):(%d+):(%d+)$")
	local hour = tonumber(hourText)
	local minute = tonumber(minuteText)
	local second = tonumber(secondText)
	local currentDate = os.date("*t")
	local messageDate = {
		year = currentDate.year,
		month = currentDate.month,
		day = currentDate.day,
		hour = hour,
		min = minute,
		sec = second
	}

	return os.time(messageDate)
end

function checkMessageTime(message)
	local messageTime = extractTimeFromMessage(message)

	if not messageTime then
		return
	end

	if os.time() - messageTime <= 120 then
		return message
	end

	return false
end

