					table.insert(dialogLines, line)
				end
			end

			local radioStation = autoAdProfiles[marketState.send_adControl.uid].settingsAd["1"].isRadioStation
			local var_298_3 = {}

			for lineIndex, lineText in ipairs(dialogLines) do
				local plainLine = lineText:gsub("{[A-Fa-f0-9]+}", "")
				local hours = 0
				local minutes = 0
				local seconds = 0

				if plainLine:match(u8:decode("(%d+)%s*час%.?%s*(%d+)%s*мин%.?%s*(%d+)%s*сек%.?")) == nil then
					local minuteText, secondText = plainLine:match(u8:decode("(%d+)%s*мин%.?%s*(%d+)%s*сек%.?"))

					if minuteText and secondText then
						minutes, seconds = tonumber(minuteText), tonumber(secondText)
					else
						local secondsText = plainLine:match(u8:decode("(%d+)%s*сек%.?"))

						if secondsText then
							seconds = tonumber(secondsText)
						end
					end
				else
					hours, minutes, seconds = plainLine:match(u8:decode("(%d+)%s*час%.?%s*(%d+)%s*мин%.?%s*(%d+)%s*сек%.?"))
					hours, minutes, seconds = tonumber(hours) or 0, tonumber(minutes) or 0, tonumber(seconds) or 0
				end

				local totalSeconds = hours * 3600 + minutes * 60 + seconds

				if totalSeconds == 0 then
					totalSeconds = 999999
				end

				var_298_3[lineIndex] = totalSeconds
			end

			local selectedIndex = 1
			local shortestDuration = math.huge

