function sampev.onSendCommand(command)
	timers[37][4] = {
		command,
		os.time()
	}

	if command == "/rec" or command == "/reconnect" then
		if invalidateLavkaHelperGrid then
			invalidateLavkaHelperGrid(true)
		end
	end

	if command:find("id") then
		timers[17] = os.time()
	end

	if command:match("^/premhost") then
		ini.cfg.priumUrlChange = not ini.cfg.priumUrlChange

		AFKMessage(u8:decode("Хост таблицы изменен: ") .. tostring(ini.cfg.priumUrlChange))
		AFKMessage(u8:decode("Теперь перезайдите в игру полностью и проблема будет решена!"))
		save_all()

		return false
	end

	if command == "/crr" then
		deAFKMessage(debug.getinfo(1, "l"), "open menu [onSendCommand]")

		kifir = 1
		menuOpen = not menuOpen


		menuVisible[0] = menuOpen

		if replaceWindowEnabled[0] then
			var_0_71[0] = not var_0_71[0]
		end

		if menuOpen == true then
			zzztime = os.clock()
		elseif menuOpen == false then
			resetIO()
		end

		return false
	end
end

function IsUseMarket(playerName, playerId)
	local serverAddress, serverPort = sampGetCurrentServerAddress()

	if serverIdByAddress[serverAddress] and not playerName:find("{......}") then
		local var_308_2, var_308_3 = playerName:match("%[(%-?%d+)%](%S+)")

		deAFKMessage(debug.getinfo(1, "l"), "" .. (serverIdByAddress[serverAddress] == 0 and "[" .. tonumber(var_308_2) .. "]" .. var_308_3 .. "[" .. playerId .. "]" or "[" .. serverIdByAddress[serverAddress] .. "]" .. playerName .. "[" .. playerId .. "]"))

		if playerName ~= sampGetPlayerNickname(select(2, sampGetPlayerIdByCharHandle(PLAYER_PED))) and var_308_3 ~= sampGetPlayerNickname(select(2, sampGetPlayerIdByCharHandle(PLAYER_PED))) then
			asyncHttpRequest("GET", serverIdByAddress[serverAddress] == 0 and marketState.host .. "/api/IsUseMarket/[" .. tonumber(var_308_2) .. "]" .. var_308_3 .. "[" .. playerId .. "]" or marketState.host .. "/api/IsUseMarket/[" .. serverIdByAddress[serverAddress] .. "]" .. playerName .. "[" .. playerId .. "]", {}, function(marketUsageResponse)
				if marketUsageResponse.status_code == 200 or marketUsageResponse.status_code == 304 then
					deAFKMessage(debug.getinfo(1, "l"), "result.text 200 / 304 " .. type(marketUsageResponse.text) .. " " .. marketUsageResponse.text)

					if marketUsageResponse.text == "0" then
						AFKMessage(u8:decode("Игрок ") .. playerName .. u8:decode(" {ff6666}не использует{ffffff} Arizona Market"))
					elseif marketUsageResponse.text == "1" then
						AFKMessage(u8:decode("Игрок ") .. playerName .. u8:decode(" {33AA33}использует{ffffff} Arizona Market"))
					elseif tonumber(marketUsageResponse.text) > 1 then
						AFKMessage(u8:decode("Игрок ") .. playerName .. u8:decode(" {ff6666}не использует{ffffff} Arizona Market. Последний раз был в сети ") .. marketUsageResponse.text .. u8:decode(" минут назад."))
					end
				else
					deAFKMessage(debug.getinfo(1, "l"), "error1 " .. tostring(marketUsageResponse.status_code))
				end
			end, function(marketUsageError)
				deAFKMessage(debug.getinfo(1, "l"), "error ")
			end)
		end
	end
end

TRADE_SCOPE_OWN_SHOP = "own_shop"
TRADE_SCOPE_FOREIGN_SHOP = "foreign_shop"
TRADE_SCOPE_UNKNOWN = "unknown"

TRADE_CLASS_OWN_SHOP_SELL = "OWN_SHOP_SELL"
TRADE_CLASS_OWN_SHOP_BUY = "OWN_SHOP_BUY"
TRADE_CLASS_FOREIGN_SHOP_PURCHASE = "FOREIGN_SHOP_PURCHASE"
TRADE_CLASS_FOREIGN_SHOP_SALE = "FOREIGN_SHOP_SALE"
TRADE_CLASS_UNKNOWN = "UNKNOWN"

TRADE_PATTERN_CLASS = {
	[1] = TRADE_CLASS_OWN_SHOP_SELL,
	[2] = TRADE_CLASS_FOREIGN_SHOP_SALE,
	[3] = TRADE_CLASS_OWN_SHOP_BUY,
	[4] = TRADE_CLASS_FOREIGN_SHOP_PURCHASE
}

TRADE_CONTEXT_TTL = 300
TRADE_ACTION_TTL = 30

function getTradeContextState()
	marketState.copyLavkaFunc.foreignContext = type(marketState.copyLavkaFunc.foreignContext) == "table" and marketState.copyLavkaFunc.foreignContext or {}
	local context = marketState.copyLavkaFunc.foreignContext
	context.owner = context.owner == "self" and "self" or context.owner == "other" and "other" or "unknown"
	context.active = context.active == true
	context.actionExpiresAt = tonumber(context.actionExpiresAt) or 0
	context.openedAt = tonumber(context.openedAt) or 0
	context.expiresAt = tonumber(context.expiresAt) or 0
	context.source = tostring(context.source or "")
	context.lastReason = tostring(context.lastReason or "")
	return context
end

function resetTradeContext(reason)
	local context = getTradeContextState()
	context.owner = "unknown"
	context.active = false
	context.side = nil
	context.shopIdentity = nil
	context.action = nil
	context.actionExpiresAt = 0
	context.openedAt = 0
	context.expiresAt = 0
	context.source = "reset"
	context.lastReason = tostring(reason or "")
end

function markTradeShopContext(owner, side, shopIdentity, source)
	local context = getTradeContextState()
	local now = os.time()
	local previousOwner = context.owner
	local wasActive = context.active == true
	local nextOwner = owner == "self" and "self" or owner == "other" and "other" or "unknown"
	local ownerChanged = previousOwner ~= nextOwner or not wasActive

	context.owner = nextOwner
	context.active = context.owner ~= "unknown"
	if ownerChanged then
		context.side = nil
		context.shopIdentity = nil
		context.action = nil
		context.actionExpiresAt = 0
		context.openedAt = now
	end
	context.side = (side == "sell" or side == "buy") and side or context.side
	if shopIdentity ~= nil then
		context.shopIdentity = tostring(shopIdentity)
	end
	context.expiresAt = now + TRADE_CONTEXT_TTL
	context.source = tostring(source or "runtime")
	context.lastReason = ""
	return context
end

function markOwnShopContext(source)
	return markTradeShopContext("self", nil, activeLavkaId ~= -1 and activeLavkaId or nil, source or "own_shop")
end

function markForeignShopContext(side, shopIdentity, source)
	return markTradeShopContext("other", side, shopIdentity, source or "foreign_shop")
end

function markPlayerTradeAction(action, source)
	local context = getTradeContextState()
	if context.owner ~= "other" then
		return false
	end
	if action ~= "buy_from_shop" and action ~= "sell_to_shop" then
		return false
	end
	context.action = action
	context.actionExpiresAt = os.time() + TRADE_ACTION_TTL
	context.expiresAt = math.max(tonumber(context.expiresAt) or 0, os.time() + TRADE_CONTEXT_TTL)
	context.source = tostring(source or context.source or "action")
	return true
end

function tradeContextRecentOwnShopManagement()
	local recent = timers[37] and timers[37][1]
	if type(recent) ~= "table" then
		return false
	end
	local message = tostring(recent[1] or "")
	local messageTime = tonumber(recent[2]) or 0
	if messageTime + 1 <= os.time() then
		return false
	end
	return message:find(u8:decode("Управление продажей товаров")) ~= nil
		or message:find(u8:decode("Прекратить покупку товара")) ~= nil
end

function tradeContextTick()
	local context = getTradeContextState()
	if not context.active then
		return
	end
	if context.expiresAt > 0 and os.time() > context.expiresAt then
		resetTradeContext("timeout")
		return
	end
	if context.action ~= nil and context.actionExpiresAt > 0 and os.time() > context.actionExpiresAt then
		context.action = nil
		context.actionExpiresAt = 0
	end
	if doesCharExist and doesCharExist(PLAYER_PED) and isCharDead and isCharDead(PLAYER_PED) then
		resetTradeContext("player_dead")
	end
end

function getTradeContextForMessage()
	tradeContextTick()
	return getTradeContextState()
end

function tradeClassToScope(transactionClass)
	if transactionClass == TRADE_CLASS_OWN_SHOP_SELL or transactionClass == TRADE_CLASS_OWN_SHOP_BUY then
		return TRADE_SCOPE_OWN_SHOP
	end
	if transactionClass == TRADE_CLASS_FOREIGN_SHOP_PURCHASE or transactionClass == TRADE_CLASS_FOREIGN_SHOP_SALE then
		return TRADE_SCOPE_FOREIGN_SHOP
	end
	return TRADE_SCOPE_UNKNOWN
end

function classifyTradeTransaction(tradeEvent, context)
	local transactionClass = TRADE_PATTERN_CLASS[tonumber(tradeEvent.pattern_index)] or TRADE_CLASS_UNKNOWN
	context = type(context) == "table" and context or getTradeContextForMessage()
	tradeEvent.context_owner = tostring(context.owner or "unknown")
	tradeEvent.context_side = context.side
	tradeEvent.context_action = context.action
	tradeEvent.context_source = context.source
	tradeEvent.context_confirmed = false

	if transactionClass == TRADE_CLASS_FOREIGN_SHOP_PURCHASE then
		tradeEvent.context_confirmed = context.owner == "other" and (context.action == nil or context.action == "buy_from_shop")
	elseif transactionClass == TRADE_CLASS_FOREIGN_SHOP_SALE then
		tradeEvent.context_confirmed = context.owner == "other" and (context.action == nil or context.action == "sell_to_shop")
	elseif transactionClass == TRADE_CLASS_OWN_SHOP_SELL or transactionClass == TRADE_CLASS_OWN_SHOP_BUY then
		-- Own-shop transactions may happen while the player is not viewing their booth,
		-- so the explicit server message remains authoritative for these two classes.
		tradeEvent.context_confirmed = context.owner == "self"
	end

	return transactionClass
end

function shouldCountTradeInBusinessStats(transactionClass)
	return transactionClass == TRADE_CLASS_OWN_SHOP_SELL or transactionClass == TRADE_CLASS_OWN_SHOP_BUY
end

function shouldSendTradeTelegram(transactionClass)
	return shouldCountTradeInBusinessStats(transactionClass)
end

function tradeEventExtractCount(itemText)
	itemText = tostring(itemText or "")
	local count = tonumber(itemText:match(u8:decode("%((%d+) шт%.%)$")))
	if not count or count < 1 then
		return 1
	end
	return math.floor(count)
end

function tradeEventBaseItemName(itemText)
	itemText = tostring(itemText or "")
	return (itemText:gsub(u8:decode("%s*%(%d+ шт%.%)$"), ""))
end

function parseTradeMessage(rawMessage, matchedPattern, patternIndex)
	if type(matchedPattern) ~= "table" or type(matchedPattern.text) ~= "string" then
		return nil
	end
	local captures = { rawMessage:match(matchedPattern.text) }
	if #captures < 3 then
		return nil
	end
	local nameFirst = rawMessage:find(u8:decode("купил у вас")) ~= nil
	local tradeData = splitArguments(captures, nameFirst)
	if type(tradeData) ~= "table" or not tradeData.item then
		return nil
	end
	local count = tradeEventExtractCount(tradeData.item)
	local money = tonumber(tradeData.money) or 0
	local direction = matchedPattern.key == 2 and "sell" or matchedPattern.key == 3 and "buy" or "unknown"
	return {
		direction = direction,
		scope = TRADE_SCOPE_UNKNOWN,
		transaction_class = TRADE_CLASS_UNKNOWN,
		item_name = tradeEventBaseItemName(tradeData.item),
		item_text = tradeData.item,
		count = count,
		unit_price = count > 0 and math.floor(money / count) or money,
		money = money,
		player_name = tostring(tradeData.name or ""),
		raw_message = rawMessage,
		timestamp = os.time(),
		ViceCity = tradeData.ViceCity or " ",
		pattern_index = patternIndex,
		pattern_key = matchedPattern.key,
		trade_data = tradeData
	}
end

function ensureTradeDayLog()
	local dateKey = os.date("%d.%m.%Y")
	if type(jsonLog[dateKey]) ~= "table" then
		jsonLog[dateKey] = {
			{}, 0, 0, 0, 0, {}, {}, {}, {}, {}, {}, {}, 0, 0, {}, 0, 0
		}
	end
	jsonLog[dateKey][1] = type(jsonLog[dateKey][1]) == "table" and jsonLog[dateKey][1] or {}
	for index = 2, 5 do
		jsonLog[dateKey][index] = tonumber(jsonLog[dateKey][index]) or 0
	end
	return dateKey, jsonLog[dateKey]
end

function updateOwnBuyContinueFromTrade(tradeEvent)
	if tradeEvent.transaction_class ~= TRADE_CLASS_OWN_SHOP_BUY or #buyList == 0 then
		return
	end
	local baseItemName = tostring(tradeEvent.item_name or "")
	for itemIndex, itemData in pairs(buyList) do
		if type(itemData) == "table" then
			if tostring(itemData.continue) == "nil" then
				itemData.continue = itemData.count
				deAFKMessage(debug.getinfo(1, "l"), "[con dbug tradeEvent] nil in cfg")
			end
			if tostring(itemData.name or ""):gsub(" ", "") == baseItemName:gsub(" ", "") then
				local remainingCount = (tonumber(itemData.continue) or 0) - (tonumber(tradeEvent.count) or 1)
				if remainingCount > -1 then
					buyList[itemIndex].continue = remainingCount
					if loadedBuyConfig and loadedBuyConfig ~= "" then
						configFileNames.buy = loadedBuyConfig:match("(.+)%.json") and loadedBuyConfig or loadedBuyConfig .. ".json"
						createConfig("buy-cfg/" .. configFileNames.buy, buyList, "buy-cfg", configFileNames.buy)
					end
				end
				break
			end
		end
	end
end

function handleTradeRuntimeEffects(tradeEvent)
	if not shouldCountTradeInBusinessStats(tradeEvent.transaction_class) then
		return
	end
	if tradeEvent.transaction_class == TRADE_CLASS_OWN_SHOP_BUY then
		if type(manualPurchasedRemember) == "function" then
			manualPurchasedRemember(tradeEvent.item_name, tradeEvent.count)
		end
		cycleTradeOnBought(tradeEvent.item_name, tradeEvent.count)
		removeFromMarketBuyCount(tradeEvent.item_name, tradeEvent.count)
		updateOwnBuyContinueFromTrade(tradeEvent)
	elseif tradeEvent.transaction_class == TRADE_CLASS_OWN_SHOP_SELL then
		removeFromMarketSellCount(tradeEvent.item_name, tradeEvent.count)
		cycleTradeOnSold(tradeEvent.item_name, tradeEvent.count)
	end
end

function appendBusinessTradeLog(tradeEvent, formattedLogMessage, dayLog)
	if not shouldCountTradeInBusinessStats(tradeEvent.transaction_class) then
		return false
	end
	local line = formatArizonaMoneyInText(formattedLogMessage)
	if #recentMoneyLines >= 10 then
		recentMoneyLines = {}
	end
	table.insert(recentMoneyLines, line)
	table.insert(dayLog[1], line)
	return true
end

function appendPersonalTradeDebug(tradeEvent, formattedLogMessage)
	saveLog("[ArzMarket][PersonalTrade] class=" .. tostring(tradeEvent.transaction_class)
		.. " context=" .. tostring(tradeEvent.context_owner)
		.. " action=" .. tostring(tradeEvent.context_action)
		.. " confirmed=" .. tostring(tradeEvent.context_confirmed)
		.. " item=" .. tostring(tradeEvent.item_name)
		.. " money=" .. tostring(tradeEvent.money)
		.. " text=" .. tostring(formatArizonaMoneyInText(formattedLogMessage)))
end

function updateTradeStatistics(tradeEvent, dayLog)
	if not shouldCountTradeInBusinessStats(tradeEvent.transaction_class) then
		return false
	end
	local bucket = (#tradeEvent.ViceCity == 3) and (tradeEvent.pattern_key + 2) or tradeEvent.pattern_key
	if bucket < 2 or bucket > 5 then
		return false
	end
	dayLog[bucket] = (tonumber(dayLog[bucket]) or 0) + (tonumber(tradeEvent.money) or 0)
	return true
end

function sendTradeTelegramNotification(tradeEvent, formattedLogMessage, dayLog)
	if not shouldSendTradeTelegram(tradeEvent.transaction_class) or not telegramUi.notf_buysell[0] then
		return false
	end
	local messageText = formattedLogMessage
	if telegramUi.stats[0] then
		messageText = messageText .. u8:decode("\n\nПродали за день: $") .. moneySeparator(dayLog[2])
			.. u8:decode("\nСкупили за день: $") .. moneySeparator(dayLog[3])
			.. u8:decode("\n\nПродали за день: VC$") .. moneySeparator(dayLog[4])
			.. u8:decode("\nСкупили за день: VC$") .. moneySeparator(dayLog[5])
			.. u8:decode("\nОсталось денег на руках: ") .. moneySeparator(getPlayerMoney())
	end
	sendTelegramNotification(formatArizonaMoneyInText(messageText))
	return true
end

function processTradeEvent(tradeEvent)
	if type(tradeEvent) ~= "table" then
		return false
	end

	local context = getTradeContextForMessage()
	tradeEvent.transaction_class = classifyTradeTransaction(tradeEvent, context)
	tradeEvent.scope = tradeClassToScope(tradeEvent.transaction_class)
	handleTradeRuntimeEffects(tradeEvent)

	local formattedLogMessage = getTypeMessageMarket(tradeEvent.raw_message, tradeEvent.trade_data)
	if not formattedLogMessage then
		return false
	end

	local counted = false
	local telegramSent = false
	local businessLogged = false
	if shouldCountTradeInBusinessStats(tradeEvent.transaction_class) then
		local dateKey, dayLog = ensureTradeDayLog()
		businessLogged = appendBusinessTradeLog(tradeEvent, formattedLogMessage, dayLog)
		counted = updateTradeStatistics(tradeEvent, dayLog)
		telegramSent = sendTradeTelegramNotification(tradeEvent, formattedLogMessage, dayLog)
		writeJsonFile(jsonLog, "moonloader\\ArzMarket\\Log.json")
	else
		appendPersonalTradeDebug(tradeEvent, formattedLogMessage)
	end

	saveLog("[ArzMarket][TradeScope] class=" .. tostring(tradeEvent.transaction_class)
		.. " scope=" .. tostring(tradeEvent.scope)
		.. " context=" .. tostring(tradeEvent.context_owner)
		.. " action=" .. tostring(tradeEvent.context_action)
		.. " confirmed=" .. tostring(tradeEvent.context_confirmed)
		.. " businessLog=" .. tostring(businessLogged)
		.. " counted=" .. tostring(counted)
		.. " telegram=" .. tostring(telegramSent)
		.. " item=" .. tostring(tradeEvent.item_name)
		.. " money=" .. tostring(tradeEvent.money))

	if tradeEvent.scope == TRADE_SCOPE_FOREIGN_SHOP then
		local activeContext = getTradeContextState()
		if activeContext.owner == "other" then
			activeContext.action = nil
			activeContext.actionExpiresAt = 0
			activeContext.expiresAt = os.time() + TRADE_CONTEXT_TTL
		end
	end
	return true
end

function sampev.onServerMessage(color, message)
	marketState.remoteShop:handleServerMessage(message, color)

	timers[37][5] = {
		message,
		os.time()
	}

	if message:find(u8:decode("успешно выставлен на продажу")) then
		if type(manualPurchasedConfirmListed) == "function" then
			manualPurchasedConfirmListed(message)
		end
		cycleTradeOnSellListed(message)
	end
	if message:find(u8:decode("Вы начали скупку товара")) then
		cycleTradeOnBuyStarted(message)
	end

	if not ARZ_INI_WRITE_LOCKED and marketState.myUidCheck[1] == true and message:match("UID: (%d+)") then
		local incomingUid = message:match("UID: (%d+)")
		local savedUid = arzAuthFreezeUid(incomingUid)
		marketState.myUidCheck = { false, savedUid or incomingUid, os.time() }
		save_all()
		return false
	end

	if marketState.autoLavka and (message:find(u8:decode("поскольку он сломан")) or message:find(u8:decode("вас нет надетого на вас переносного ларька")) or message:find(u8:decode("У Вас уже установлена лавка"))) and color == -10270721 then
		marketState.autoLavka = false

