function Percent(value, percent)
	return math.floor(value * (1 - percent / 100))
end

function parseArizonaMoney(text)
	text = tostring(text)

	local moneyText = text:gsub("%.", ""):match(":CASHV?:%s*(%d+)")

	return tonumber(moneyText) or 0
end

function parseArizonaViceCity(text)
	text = tostring(text)

	if text:find(":CASHV:") then
		return " VC"
	end

	return " "
end

function clearArizonaFormat(text)
	local currencyMarkers = {
		":CASHV:",
		":CASH:"
	}

	for markerIndex, currencyMarker in ipairs(currencyMarkers) do
		text = text:gsub(currencyMarker .. "%s*", "")
	end

	deAFKMessage("clearArizonaFormat(" .. text .. ")")

	return text
end

function formatArizonaMoneyInText(text)
	return (text:gsub("(:CASHV?:%s*[%d%.]+)", function(moneyFragment)
		return (moneyFragment:find(":CASHV:") ~= nil and "VC$" or "$") .. moneySeparator(parseArizonaMoney(moneyFragment))
	end))
end

function splitArguments(captures, nameFirst)
	return {
		name = nameFirst and captures[1] or captures[2],
		item = nameFirst and captures[2] or captures[1],
		ViceCity = parseArizonaViceCity(captures[3]),
		money = parseArizonaMoney(captures[3])
	}
end

function getTypeMessageMarket(message, tradeData)
	local messageFormats = {
		[u8:decode("Вы купили")] = u8:decode("%s %s продал \"%s\" за%s$%s"),
		[u8:decode("купил у вас")] = u8:decode("%s %s купил \"%s\" за%s$%s"),
		[u8:decode("Вы успешно продали")] = u8:decode("%s [Чужая Лавка] %s купил \"%s\" за%s$%s"),
		[u8:decode("Вы успешно купили")] = u8:decode("%s [Чужая Лавка] %s продал \"%s\" за%s$%s")
	}

	for messagePrefix, messageFormat in pairs(messageFormats) do
		if message:find(messagePrefix) then
			local tradeType = (messagePrefix == u8:decode("купил у вас") or messagePrefix == u8:decode("Вы успешно купили")) and "sell" or (messagePrefix == u8:decode("Вы купили") or messagePrefix == u8:decode("Вы успешно продали")) and "buy" or ""

			if tradeType ~= "" and tradeData.item then
				local itemCount = type(tradeData.item:match(u8:decode(".%((%d+) шт%.%)$"))) ~= "nil" and stringToCount(tradeData.item:match(u8:decode(".%((%d+) шт%.%)$"))) or 1

				if type(itemCount) == "number" then
					timers[33] = {
						true,
						tradeData.money,
						tradeData.item:gsub(u8:decode(".%(%d+ шт%.%)$"), ""),
						tradeData.name,
						tradeType,
						itemCount
					}
				end
			end

			local currencyLabel = #tradeData.ViceCity == 3 and "VC" or ""

			return string.format(messageFormat, os.date("[%H:%M:%S]"), tradeData.name, tradeData.item, " " .. currencyLabel, moneySeparator(tradeData.money))
		end
	end
end

function stringToCount(text)
	local digits = ""

	for digit in text:gmatch("%d") do
		digits = digits .. digit
	end

	return tonumber(digits)
end

function calculate_similarity(leftText, rightText)
	return 100 * (1 - calculate_percentage(leftText, rightText) / math.max(#leftText, #rightText))
end

function calculate_percentage(leftText, rightText)
	local leftLength = string.len(leftText)
	local rightLength = string.len(rightText)
	local distanceMatrix = {}
	local var_322_3 = 0

	if leftLength == 0 then
		return rightLength
	elseif rightLength == 0 then
		return leftLength
	elseif leftText == rightText then
		return 0
	end

	for leftIndex = 0, leftLength do
		distanceMatrix[leftIndex] = {}
		distanceMatrix[leftIndex][0] = leftIndex
	end

	for rightIndex = 0, rightLength do
		distanceMatrix[0][rightIndex] = rightIndex
	end

	for leftIndex = 1, leftLength do
		for rightIndex = 1, rightLength do
			local substitutionCost = leftText:byte(leftIndex) == rightText:byte(rightIndex) and 0 or 1

			distanceMatrix[leftIndex][rightIndex] = math.min(distanceMatrix[leftIndex - 1][rightIndex] + 1, distanceMatrix[leftIndex][rightIndex - 1] + 1, distanceMatrix[leftIndex - 1][rightIndex - 1] + substitutionCost)
		end
	end

	return distanceMatrix[leftLength][rightLength]
end

function writeKey(value, valueName)
	if ARZ_INI_WRITE_LOCKED then return false, "auth data receiving is stopped" end
	if not value or type(value) ~= "string" then
		return false, "auth value must be a string"
	end

	if valueName == "premiumTokenAuth" then
		local frozen = arzAuthFreezeCfgString("authPremiumTokenAuth", value, "reg_premiumTokenAuth")
		if frozen then return true end
		return false, "premiumTokenAuth is empty"
	elseif valueName == "UserTempKey" then
		local frozen = arzAuthFreezeCfgString("authUserTempKey", value, "reg_UserTempKey")
		if frozen then return true end
		return false, "UserTempKey is empty"
	end
	return false, "unsupported auth value"
end

function clearArzMarketAuthorizationData()
	local registryOk = true
	local registryKeyHandle = ffi.new("HKEY[1]")
	local openResultCode = advapi32.RegOpenKeyExA(ffi.cast("HKEY", 2147483649), "Software\\ArzMarket\\info", 0, 2, registryKeyHandle)

	if openResultCode == 0 then
		local deletePremiumResult = advapi32.RegDeleteValueA(registryKeyHandle[0], "premiumTokenAuth")
		local deleteTempResult = advapi32.RegDeleteValueA(registryKeyHandle[0], "UserTempKey")

		advapi32.RegCloseKey(registryKeyHandle[0])

		if deletePremiumResult ~= 0 and deletePremiumResult ~= 2 then
			registryOk = false
		end
		if deleteTempResult ~= 0 and deleteTempResult ~= 2 then
			registryOk = false
		end
	elseif openResultCode ~= 2 then
		registryOk = false
	end

	ini.cfg.premiumTokenAuth = -1
	ini.cfg.lastUpdatePremiumToken = -1
	ini.cfg.myServerToken = ""
	if type(arzManualServerTokenBufferSet) == "function" then arzManualServerTokenBufferSet("") end
	ini.cfg.myServerId = ""
	ini.cfg.authNickname = ""
	ini.cfg.authUid = ""
	ini.cfg.authPremiumTokenAuth = ""
	ini.cfg.authUserTempKey = ""
	ini.cfg.authRealNameMode1 = ""
	ini.cfg.authRealNameMode2 = ""
	ini.cfg.authSelfInfoId = ""
	ini.cfg.authSelfInfoUsername = ""
	ini.cfg.authSelfInfoExp = ""
	ini.cfg.authSelfInfoOsTime = ""
	ini.cfg.marketAuthKey = ""

	local optionalAuthIniFields = {
		"marketAuthKey",
		"marketAuthToken",
		"premiumToken",
		"premiumAuthToken",
		"userToken",
		"userAuthToken",
		"serverToken",
		"authKey"
	}

	for _, section in pairs(ini) do
		if type(section) == "table" then
			for _, fieldName in ipairs(optionalAuthIniFields) do
				if section[fieldName] ~= nil then
					section[fieldName] = ""
				end
			end
		end
	end

	marketState.premiumKeys = {}
	marketState.premiumUserInfo = {}
	marketState.premiumTokenAuth = imguiNew.char[256]()
	marketState.lastUpdatePremiumToken = -1
	marketState.isPremiumAuthedStatus = false
	marketState.VisibleKey = false
	marketState.onPremUsersLoad = false
	marketState.marketplaceQueue = -1
	marketState.marketplaceSave = {}
	marketState.lavka_summ = 0
	marketState.isMenuActive = -1
	marketState.myUidCheck = {
		false,
		nil,
		os.time()
	}
	marketState.premItems = {}

	if marketState.marketAuthKey ~= nil then
		marketState.marketAuthKey = ""
	end
	if marketState.marketAuthToken ~= nil then
		marketState.marketAuthToken = ""
	end
	if marketState.userToken ~= nil then
		marketState.userToken = ""
	end
	if marketState.serverToken ~= nil then
		marketState.serverToken = ""
	end

	isStartLoadPremium = nil
	isUpdateNick = nil
	download_marketplace = nil
	marketplaceView = {}

	local uidCachePath = "moonloader/ArzMarket/UsersInfo/info_user_uid.txt"
	local selfInfoPath = "moonloader/ArzMarket/UsersInfo/info_users_SelfInfo.json"

	if doesFileExist(uidCachePath) then
		os.remove(uidCachePath)
	end
	if doesFileExist(selfInfoPath) then
		os.remove(selfInfoPath)
	end
	local oldFreezePath = "moonloader/ArzMarket/UsersInfo/auth_frozen.json"
	if doesFileExist(oldFreezePath) then pcall(os.remove, oldFreezePath) end
	ARZ_AUTH_FREEZE = {}

	-- Manual clear is explicit and may write once even while the automatic lock is active.
	if ARZ_INI_WRITE_LOCKED then arzIniPersistWriteLock(true) end
	arzIniSave(true)
	if ARZ_INI_WRITE_LOCKED then arzIniCaptureLockSnapshot() end

	return registryOk
end

