	local offlineWidth = imgui.CalcTextSize(offlineText).x + buttonPadding

	if imgui.Button(stopReceivingText, imgui.ImVec2(stopWidth, 27)) then
		local ok, receivingStopped = arzToggleReceivingAccountData()
