	end

	imgui.SameLine()
	if imgui.Button(clearDataText, imgui.ImVec2(clearWidth, 27)) then
		if clearArzMarketAuthorizationData() then
			sendNotify(u8:decode("Данные авторизации очищены."))
		else
			sendNotify(u8:decode("Данные очищены, но часть записей реестра удалить не удалось."))
		end
		arzRefreshAuthorizationTokenBuffers()
	end

	imgui.SameLine()
	if imgui.Button(offlineText, imgui.ImVec2(offlineWidth, 27)) then
		if arzScriptOfflineSet(not ARZ_SCRIPT_OFFLINE) then
			sendNotify(ARZ_SCRIPT_OFFLINE and u8:decode("Офлайн включён.") or u8:decode("Офлайн выключен."))
		else
			sendNotify("Offline mode state change failed.")
		end
	end

	-- Responsive warning for the authorization section.
	imgui.Spacing()
	imgui.Spacing()

	local warningText = "НИЧЕГО НЕ МЕНЯЙТЕ В ЭТОМ РАЗДЕЛЕ, ЕСЛИ НЕ ИСПОЛЬЗУЕТЕ ПРОГРАММУ ДЛЯ ОБХОДА БАНА"
	local warningAvailWidth = math.max(imgui.GetContentRegionAvail().x, 1)
	local warningScale

	if warningAvailWidth < 560 then
		warningScale = 1.15
	elseif warningAvailWidth < 850 then
		warningScale = 1.30
	elseif warningAvailWidth < 1150 then
		warningScale = 1.45
	else
		warningScale = 1.60
	end

	local warningLineGap = math.floor(4 + warningScale * 4)
	imgui.PushStyleColor(imgui.Col.Text, imgui.ImVec4(1.0, 0.12, 0.12, 1.0))
	imgui.SetWindowFontScale(warningScale)
	imgui.PushTextWrapPos(imgui.GetCursorPos().x + warningAvailWidth / warningScale)
	imgui.TextWrapped(warningText)
	imgui.PopTextWrapPos()
	imgui.SetWindowFontScale(1.0)
	imgui.PopStyleColor()
	imgui.Dummy(imgui.ImVec2(0, warningLineGap))
end

function removeDuplicates(values)
	local seenValues = {}
	local writeIndex = 1

	for readIndex = 1, #values do
		local value = values[readIndex]

		if not seenValues[value] then
			seenValues[value] = true
			values[writeIndex] = value
			writeIndex = writeIndex + 1
		end
	end

	for clearIndex = writeIndex, #values do
		values[clearIndex] = nil
	end

	return values
end

function copyTbl(sourceTable)
	local copiedTables = {}

	local function copyValue(value)
		if type(value) ~= "table" then
			return value
		end

		if copiedTables[value] then
			return copiedTables[value]
		end

		local copiedTable = {}

		copiedTables[value] = copiedTable

		for key, entryValue in pairs(value) do
			copiedTable[copyValue(key)] = copyValue(entryValue)
		end

		return copiedTable
	end

	return copyValue(sourceTable)
end

function auto_load_config()
	if loadedSellConfig ~= "" then
		if doesFileExist("moonloader/ArzMarket/sell-cfg/" .. loadedSellConfig) then
			sellList = loadConfig("moonloader/ArzMarket/sell-cfg/" .. loadedSellConfig)

			if type(sellList) == "nil" then
				AFKMessage(u8:decode("К сожалению конфиг был поврежден. Загрузить его не получится."))

				sellList = {}
				ini.cfg.load_config_sell = ""
				loadedSellConfig = ""

				save_all()
			end
		elseif doesFileExist("moonloader/ArzMarket/sell-cfg/" .. loadedSellConfig .. ".cfg") then
			pltcfg("moonloader/ArzMarket/sell-cfg/" .. loadedSellConfig .. ".cfg", 1)
		end
	end

	if loadedBuyConfig ~= "" then
		if doesFileExist("moonloader/ArzMarket/buy-cfg/" .. loadedBuyConfig) then
			buyList = loadConfig("moonloader/ArzMarket/buy-cfg/" .. loadedBuyConfig)

			if type(buyList) == "nil" then
				AFKMessage(u8:decode("К сожалению конфиг был поврежден. Загрузить его не получится."))

				buyList = {}
				ini.cfg.load_config_buy = ""
				loadedBuyConfig = ""

				save_all()
			end
		elseif doesFileExist("moonloader/ArzMarket/buy-cfg/" .. loadedBuyConfig .. ".cfg") then
			pltcfg("moonloader/ArzMarket/buy-cfg/" .. loadedBuyConfig .. ".cfg", 2)
		end
	end

	if replaceWindowEnabled[0] and activeLavkaId ~= -1 then
		replaceLoggerVisible[0] = true
	end

	if json_vlad == nil or json_vlads == nil then
		json_vlads = readJsonFile(sellJsonPath)
		json_vlad = readJsonFile(buyJsonPath)
	end
end

function off_sell_buy()
	local wasSelling = tradeAutomation.sell == true
	tradeAutomationVisible[0] = false

	if wasSelling and sell_alitems_d ~= nil then
