function vc_converter()
	if alwaysConvert[0] then
		local buyRate = tonumber(ffi.string(buyVcBuffer)) or 0
		local sellRate = tonumber(ffi.string(sellVcBuffer)) or 0
		if buyRate <= 0 or sellRate <= 0 then
			alwaysConvert[0] = false
			ini.cfg.Always_convert = false
			save_all()
			AFKMessage("VC conversion disabled: exchange rates must be greater than zero.")
			return
		end
		for itemIndex, itemData in pairs(sellList) do
			if not viceCityMode then
				sellList[itemIndex].price_vc = math.floor(sellList[itemIndex].price / buyRate)
			else
				sellList[itemIndex].price = math.floor(sellList[itemIndex].price_vc * sellRate)
			end
		end

		for itemIndex, itemData in pairs(buyList) do
			if not viceCityMode then
				buyList[itemIndex].price_vc = math.floor(buyList[itemIndex].price / buyRate)
			else
				buyList[itemIndex].price = math.floor(buyList[itemIndex].price_vc * sellRate)
			end
		end

		if alwaysConvertBlock[0] then
			alwaysConvert[0] = false
			ini.cfg.Always_convert = alwaysConvert[0]

			save_all()
		end
	end
end

function save_all()
	-- Locked mode restores every frozen INI value, including cfg.myServerToken,
	-- before any ordinary save.
	if not ARZ_INI_WRITE_LOCKED then
		arzAuthFreezeProtectIni()
	end
	return arzIniSave(false)
end

