function wrap_text(text, maxLineLength)
	maxLineLength = maxLineLength or 30

	local wrappedLines = {}
	local words = {}

	for word in text:gmatch("%S+") do
		table.insert(words, word)
	end

	local currentLine = ""

	for wordIndex, word in ipairs(words) do
		if maxLineLength < #currentLine + #word + 1 then
			table.insert(wrappedLines, currentLine .. " ...")

			currentLine = word
		elseif #currentLine > 0 then
			currentLine = currentLine .. " " .. word
		else
			currentLine = word
		end
	end

	if #currentLine > 0 then
		table.insert(wrappedLines, currentLine)
	end

	return wrappedLines
end

function AnsiToUtf8(text)
	local utf8Text = ""
	local var_336_1

	for byteIndex = 1, text and text:len() or 0 do
		local byteValue = text:byte(byteIndex)

		if byteValue < 128 then
			utf8Text = utf8Text .. string.char(byteValue)
		elseif byteValue > 239 then
			utf8Text = utf8Text .. "\xD1" .. string.char(byteValue - 112)
		elseif byteValue > 191 then
			utf8Text = utf8Text .. "\xD0" .. string.char(byteValue - 48)
		elseif ansi_decode[byteValue] then
			utf8Text = utf8Text .. ansi_decode[byteValue]
		else
			utf8Text = utf8Text .. "_"
		end
	end

	return utf8Text
end

