function get_cef(cefCode)
	local bitStream = raknetNewBitStream()

	raknetBitStreamWriteInt8(bitStream, 17)
	raknetBitStreamWriteInt32(bitStream, 0)
	raknetBitStreamWriteInt16(bitStream, #cefCode)
	raknetBitStreamWriteInt8(bitStream, is_encoded and 1 or 0)

	if is_encoded then
		raknetBitStreamEncodeString(bitStream, cefCode)
	else
		raknetBitStreamWriteString(bitStream, cefCode)
	end

	raknetEmulPacketReceiveBitStream(220, bitStream)
	raknetDeleteBitStream(bitStream)
end

function send_cef(cefMessage)
	deAFKMessage(tostring(cefMessage))

	local bitStream = raknetNewBitStream()

	raknetBitStreamWriteInt8(bitStream, 220)
	raknetBitStreamWriteInt8(bitStream, 18)
	raknetBitStreamWriteInt16(bitStream, #cefMessage)
	raknetBitStreamWriteString(bitStream, cefMessage)
	raknetBitStreamWriteInt32(bitStream, 0)
	raknetSendBitStream(bitStream)
	raknetDeleteBitStream(bitStream)
end

