function addButtonStorageScan()
    get_cef([=[
(function(){
  if (window.__arzStorageScanner && window.__arzStorageScanner.running) {
    if (window.__arzStorageScanner.ensure) window.__arzStorageScanner.ensure();
    return;
  }
  var state = window.__arzStorageScanner = window.__arzStorageScanner || {};
  state.running = true; state.closedSent = false;

  function visible(el){
    if (!el) return false;
    var r = el.getBoundingClientRect(), s = window.getComputedStyle(el);
    return r.width > 2 && r.height > 2 && s.display !== 'none' && s.visibility !== 'hidden' && parseFloat(s.opacity || '1') > 0.01;
  }
  function classify(text){
    text = String(text || '').toUpperCase();
    if (text.indexOf('\u0411\u0410\u0413\u0410\u0416\u041d\u0418\u041a') !== -1) return 'vehicle_trunk';
    if (text.indexOf('\u0428\u041a\u0410\u0424') !== -1) return 'house_closet';
    if (text.indexOf('\u0421\u041a\u041b\u0410\u0414') !== -1) return 'warehouse';
    if (text.indexOf('\u041e\u0411\u042a\u0415\u041a\u0422') !== -1) return 'house_object';
    return null;
  }
  function findStorage(){
    var nodes = document.querySelectorAll('div,span,p,h1,h2,h3'), best = null;
    for (var i = 0; i < nodes.length; i++) {
      var node = nodes[i]; if (!visible(node)) continue;
      var text = String(node.textContent || '').trim(); if (!text || text.length > 64) continue;
      var kind = classify(text); if (!kind) continue;
      var host = node;
      for (var depth = 0; depth < 9 && host && host !== document.body; depth++, host = host.parentElement) {
        var rect = host.getBoundingClientRect();
        if (visible(host) && rect.width >= 280 && rect.width <= Math.min(900, window.innerWidth * 0.72) && rect.height >= 260 && rect.height <= window.innerHeight * 0.98) {
          var area = rect.width * rect.height;
          if (!best || area < best.area) best = {host:host, kind:kind, rect:rect, area:area};
          break;
        }
      }
    }
    return best;
  }
  function send(action, kind){
    if (window.cef && window.cef.SendMessage) window.cef.SendMessage('arzMarketAction|' + action + '|' + String(kind || 'unknown'), 0);
  }
  function removeButton(sendClosed){
    var old = document.getElementById('arzmarket_storage_scan_button');
    if (old && old.parentNode) old.parentNode.removeChild(old);
    if (sendClosed && !state.closedSent) { state.closedSent = true; send('storageClosed', state.kind || 'unknown'); }
  }
  function place(btn, found){
    var r = found.host.getBoundingClientRect();
    btn.style.left = Math.round(r.left + 16) + 'px';
    btn.style.top = Math.round(Math.max(r.top + 70, r.bottom - 50)) + 'px';
    btn.style.width = Math.round(Math.max(180, r.width - 32)) + 'px';
  }
  function ensure(){
    var found = findStorage(); if (!found) return false;
    state.kind = found.kind; state.host = found.host; state.closedSent = false;
    var btn = document.getElementById('arzmarket_storage_scan_button');
    if (!btn) {
      btn = document.createElement('button'); btn.id = 'arzmarket_storage_scan_button'; btn.type = 'button';
      btn.textContent = '\u0421\u041a\u0410\u041d\u0418\u0420\u041e\u0412\u0410\u0422\u042c';
      btn.style.cssText = 'position:fixed;z-index:2147483646;height:38px;border:1px solid rgba(255,255,255,.38);border-radius:6px;background:linear-gradient(90deg,#30477e,#bd3d69);color:#fff;font:600 14px Arial,sans-serif;letter-spacing:.2px;cursor:pointer;box-shadow:0 3px 12px rgba(0,0,0,.35);';
      btn.addEventListener('click', function(ev){
        ev.preventDefault(); ev.stopPropagation();
        btn.textContent = '\u0421\u041a\u0410\u041d\u0418\u0420\u041e\u0412\u0410\u041d\u0418\u0415...';
        btn.style.pointerEvents = 'none'; btn.style.opacity = '0.72';
        send('storageScan', state.kind || 'unknown');
        setTimeout(function(){ if (document.getElementById('arzmarket_storage_scan_button')) { btn.textContent='\u0421\u041a\u0410\u041d\u0418\u0420\u041e\u0412\u0410\u0422\u042c'; btn.style.pointerEvents='auto'; btn.style.opacity='1'; } }, 3000);
      }, true);
      document.body.appendChild(btn); send('storageVisible', state.kind);
    }
    place(btn, found); return true;
  }
  state.ensure = ensure;
  var attempts = 0, finder = setInterval(function(){ attempts++; if (ensure() || attempts >= 80) { clearInterval(finder); if (attempts >= 80 && !document.getElementById('arzmarket_storage_scan_button')) state.running=false; } }, 50);
  if (state.watch) clearInterval(state.watch);
  state.watch = setInterval(function(){
    var btn = document.getElementById('arzmarket_storage_scan_button'); if (!btn) return;
    var found = findStorage();
    if (!found) { removeButton(true); state.running=false; clearInterval(state.watch); state.watch=null; return; }
    state.kind=found.kind; state.host=found.host; place(btn, found);
  }, 180);
})();
]=])
end

