function SendToServer(message)
	local bitStream = raknetNewBitStream()

	if message:sub(1, 1) == "/" then
		raknetBitStreamWriteInt32(bitStream, #message)
		raknetBitStreamWriteString(bitStream, message)
		raknetSendRpc(50, bitStream)
	else
		raknetBitStreamWriteInt8(bitStream, #message)
		raknetBitStreamWriteString(bitStream, message)
		raknetSendRpc(101, bitStream)
	end

	raknetDeleteBitStream(bitStream)
end

function onSendRpc(rpcId, bitStream)
	if rpcId == 52 and resetTradeContext then
		resetTradeContext("spawn_request")
	end
	if not ARZ_INI_WRITE_LOCKED and rpcId == 52 then
		deAFKMessage("spawn req")
		marketState.myUidCheck[1] = true
		marketState.myUidCheck[3] = os.time() - 3
	end
end

function onReceivePacket(packetId, bitStream)
	if packetId == 33 or packetId == 32 or packetId == 34 then
		LOW_PRICE_GUARD_FORCE_ONCE_SIDE = nil
		LOW_PRICE_GUARD_FORCE_ONCE_EXPIRES = 0
		if LOW_PRICE_GUARD_PENDING_FORCE then
			LOW_PRICE_GUARD_PENDING_FORCE.side = nil
			LOW_PRICE_GUARD_PENDING_FORCE.command = nil
		end
		marketState.copyLavkaFunc.askServer = true
		if resetTradeContext then
			resetTradeContext("network_" .. tostring(packetId))
		end

		if packetId == 34 and ini.cfg.premiumTokenAuth == -1 then
			marketState.onPremUsersLoad = true
		end

		if marketState.autoLavka then
			sendNotify(u8:decode("Авто лавка отключена."))

			marketState.autoLavka = false
		end

		if marketplacePayload.enabled == true then
			MarketPlace_Clear = true
			marketplacePayload.enabled = false

			deAFKMessage(debug.getinfo(1, "l"), "MarketPlace_items.enabled = false")
		end

		if lavkaHelperHandleNetworkPacket then
			lavkaHelperHandleNetworkPacket(packetId)
		end

		if packetId == 32 or packetId == 33 then
			AUTO_AD_RECONNECT_STATE.paused = true
			AUTO_AD_RECONNECT_STATE.pendingResume = false
			AUTO_AD_RECONNECT_STATE.resumeAfter = 0
			marketState.send_adControl = { uid = -1, active = false, timer = os.time() }
			if resetForeignShopRuntime then
				resetForeignShopRuntime("disconnect:" .. tostring(packetId))
			end
			if storageFinder and storageFinder.resetSession then
				pcall(storageFinder.resetSession, "disconnect:" .. tostring(packetId))
			end
		elseif packetId == 34 then
			AUTO_AD_RECONNECT_STATE.paused = true
			AUTO_AD_RECONNECT_STATE.pendingResume = true
			AUTO_AD_RECONNECT_STATE.resumeAfter = os.time() + 2
			if resetForeignShopRuntime then
				resetForeignShopRuntime("connect accepted")
			end
			if storageFinder and storageFinder.resetSession then
				pcall(storageFinder.resetSession, "connect accepted")
			end
		end

		ip = sampGetCurrentServerAddress()
	end

	if telegramUi.connect_message[0] then
		local var_348_0 = {
			[32] = {
				u8:decode("Сервер закрыл соединение.")
			},
			[33] = {
				u8:decode("Подключение разорвано.")
			},
			[34] = {
				u8:decode("Подключились. Входим в игру...")
			},
			[37] = {
				u8:decode("Неверный пароль от сервера")
			}
		}

		if var_348_0[packetId] then
			if packetId == 37 then
				if telegramUi.wrongpassword[0] then
					sendTelegramNotification(var_348_0[packetId][1])
				end
			else
				if packetId == 34 and telegramUi.wrongpasswordconnect[0] then
					telegramUi.messageAfterConnect = true
				end

				sendTelegramNotification(var_348_0[packetId][1])
			end
		end
	end

	if packetId == 34 and ini.cfg.premiumTokenAuth ~= -1 then
		isUpdateNick = 3
	end

	if packetId == 34 and activeLavkaId ~= -1 then
		ip = sampGetCurrentServerAddress()
		replaceLoggerVisible[0] = false
		activeLavkaId = -1
		ini.cfg.active_lavka = -1

		save_all()
	end
end

function decodeText(text)
	local characterMap = {
		p = "\xF0",
		a = "\xE0",
		� = "\xE1",
		["$"] = "\xF6",
		� = "\xD7",
		� = "\xE6",
		o = "\xEE",
		� = "\xC4",
		P = "\xD0",
		� = "\xCF",
		� = "\xDA",
		� = "\xE4",
		� = "\xE9",
		� = "\xD9",
		O = "\xCE",
		C = "\xD1",
		� = "\xF2",
		� = "\xE3",
		� = "\xCB",
		Y = "\xD3",
		["?"] = "\xF4",
		� = "\xD6",
		M = "\xCC",
		k = "\xEA",
		� = "\xEC",
		� = "\xEB",
		� = "\xC7",
		y = "\xF3",
		� = "\xED",
		X = "\xD5",
		x = "\xF5",
		K = "\xCA",
		� = "\xD2",
		� = "\xF7",
		� = "\xDF",
		� = "\xEF",
		� = "\xD8",
		� = "\xF8",
		� = "\xC8",
		� = "\xE2",
		� = "\xF9",
		� = "\xE8",
		H = "\xCD",
		� = "\xC6",
		� = "\xFC",
		� = "\xDC",
		� = "\xFA",
		� = "\xC3",
		e = "\xE5",
		A = "\xC0",
		� = "\xFB",
		� = "\xDB",
		� = "\xFD",
		� = "\xDD",
		� = "\xFE",
		� = "\xD4",
		E = "\xC5",
		c = "\xF1",
		� = "\xDE",
		� = "\xFF",
		� = "\xE7",
		� = "\xC2",
		� = "\xC1"
	}
	local decodedText = ""
	local characterIndex = 1

	while characterIndex <= #text do
		local character = text:sub(characterIndex, characterIndex)

		if characterMap[character] then
			decodedText = decodedText .. characterMap[character]
		else
			decodedText = decodedText .. character
		end

		characterIndex = characterIndex + 1
	end

	return decodedText
end

function resetIO()
	local inputWasReset = false

	if type(arizona) == "cdata" then
		deAFKMessage(debug.getinfo(1, "l"), "[dbug] close imgui buttons")

		for keyIndex = 0, 511 do
			if imgui.GetIO().KeysDown[keyIndex] then
				deAFKMessage(debug.getinfo(1, "l"), " KeysDown " .. keyIndex)

				inputWasReset = true
				imgui.GetIO().KeysDown[keyIndex] = false
			end
		end

		for mouseButton = 0, 4 do
			if imgui.GetIO().MouseDown[mouseButton] and mouseButton ~= 0 then
				deAFKMessage(debug.getinfo(1, "l"), " MouseDown " .. mouseButton)

				inputWasReset = true
				imgui.GetIO().MouseDown[mouseButton] = false
			end
		end

		if imgui.GetIO().KeyCtrl then
			imgui.GetIO().KeyCtrl = false

			deAFKMessage(debug.getinfo(1, "l"), " KeyCtrl ")

			inputWasReset = true
		end

		if imgui.GetIO().KeyShift then
			imgui.GetIO().KeyShift = false

			deAFKMessage(debug.getinfo(1, "l"), " KeyShift ")

			inputWasReset = true
		end

		if imgui.GetIO().KeyAlt then
			imgui.GetIO().KeyAlt = false

			deAFKMessage(debug.getinfo(1, "l"), " KeyAlt ")

			inputWasReset = true
		end

		if imgui.GetIO().KeySuper then
			imgui.GetIO().KeySuper = false

			deAFKMessage(debug.getinfo(1, "l"), " KeySuper ")

			inputWasReset = true
		end
	end

	return inputWasReset
end

TELEGRAM_LAST_ERROR_NOTICE_AT = 0
TELEGRAM_ORIGINAL_THREADS = {}
TELEGRAM_SEND_QUEUE = {}
TELEGRAM_SEND_ACTIVE = false
TELEGRAM_SHUTTING_DOWN = false
TELEGRAM_REQUEST_SERIAL = 0
TELEGRAM_MAX_QUEUE = 50
TELEGRAM_LAST_RESULT = {
	ok = nil,
	host = "",
	error = "",
	status = 0,
	at = 0
}
TELEGRAM_OFFICIAL_TIMEOUT = 25
TELEGRAM_RESERVE_TIMEOUT = 10

function telegramOriginalCleanup()
	TELEGRAM_SHUTTING_DOWN = true
	TELEGRAM_SEND_ACTIVE = false
	TELEGRAM_SEND_QUEUE = {}

	for requestId, requestThread in pairs(TELEGRAM_ORIGINAL_THREADS or {}) do
		if requestThread ~= nil then
			-- Never block MoonLoader/AutoReboot while a network worker is stuck in C code.
			pcall(function()
				if requestThread.cancel then requestThread:cancel(0) end
			end)
		end
		TELEGRAM_ORIGINAL_THREADS[requestId] = nil
	end
end

function telegramOriginalAsyncHttpRequest(method, url, requestOptions, onSuccess, onError, timeoutSeconds)
	requestOptions = requestOptions or {}
	requestOptions.headers = requestOptions.headers or {}
	requestOptions.headers["Accept-Encoding"] = ini.cfg.bannedByRkn == true and zzlibLoaded == true and "gzip, deflate" or nil

	onSuccess = onSuccess or function() end
	onError = onError or function() end
	timeoutSeconds = math.max(3, tonumber(timeoutSeconds) or 25)

	if TELEGRAM_SHUTTING_DOWN then
		return nil, "script_terminating"
	end

	if not effilLoaded or effil == nil or type(effil.thread) ~= "function" then
		return nil, "effil_unavailable"
	end

	local requestThread = effil.thread(function(method, url, requestOptions)
		local requests = require("requests")
		local requestSucceeded, response = pcall(requests.request, method, url, requestOptions)

		if not requestSucceeded then
			return false, response
		end

		if type(response) ~= "table" then
			return false, "invalid_response_object"
		end

		local isGzipEncoded = response.headers and response.headers["content-encoding"] and response.headers["content-encoding"]:find("gzip")
		local zzlibAvailable
		local zzlib

		if isGzipEncoded then
			zzlibAvailable, zzlib = pcall(require, "zzlib")
		end

		if not zzlibAvailable and isGzipEncoded then
			return false, "gzip_without_zzlib"
		end

		if isGzipEncoded and response.text and type(response.text) == "string" and #response.text > 2 then
			local decompressedText = response.text
			local wasDecompressed = false

			if response.text:byte(1) == 31 and response.text:byte(2) == 139 then
				decompressedText = zzlib.gunzip(response.text)
				wasDecompressed = true
			end

			if wasDecompressed and decompressedText then
				response.text = decompressedText
				response.original_size = #response.text
				response.decompressed = true
			end
		end

		response.json, response.xml = nil
		return true, response
	end)(method, url, requestOptions)

	TELEGRAM_REQUEST_SERIAL = (tonumber(TELEGRAM_REQUEST_SERIAL) or 0) + 1
	local requestId = tostring(os.clock()) .. ":tg:" .. tostring(TELEGRAM_REQUEST_SERIAL)
	TELEGRAM_ORIGINAL_THREADS[requestId] = requestThread

	local function cleanupRequest()
		TELEGRAM_ORIGINAL_THREADS[requestId] = nil
	end

	lua_thread.create(function()
		local startedAt = os.time()

		while true do
			if TELEGRAM_SHUTTING_DOWN then
				pcall(function()
					if requestThread.cancel then requestThread:cancel(0) end
				end)
				cleanupRequest()
				return
			end

			if startedAt + timeoutSeconds < os.time() then
				pcall(function()
					if requestThread.cancel then requestThread:cancel(0) end
				end)
				cleanupRequest()
				pcall(onError, "timeout")
				return
			end

			local statusOk, threadStatus, threadError = pcall(function()
				return requestThread:status()
			end)

			if not statusOk then
				cleanupRequest()
				pcall(onError, tostring(threadStatus))
				return
			end

			if threadError then
				cleanupRequest()
				pcall(onError, tostring(threadError))
				return
			end

			if threadStatus == "completed" then
				local getOk, requestSucceeded, response = pcall(function()
					return requestThread:get(0)
				end)
				cleanupRequest()

				if getOk and requestSucceeded then
					pcall(onSuccess, response)
				else
					pcall(onError, tostring(getOk and response or requestSucceeded))
				end
				return
			elseif threadStatus == "cancelled" or threadStatus == "canceled" then
				cleanupRequest()
				pcall(onError, "cancelled")
				return
			elseif threadStatus == "failed" then
				cleanupRequest()
				pcall(onError, tostring(threadError or "thread_failed"))
				return
			end

			wait(0)
		end
	end)

	return requestThread
end

function telegramUrlEncode(value)
	value = tostring(value or "")
	local encoded = string.gsub(value, "([^%w-_ %.~=])", function(character)
		return string.format("%%%02X", string.byte(character))
	end)
	return string.gsub(encoded, " ", "+")
end

function telegramResponseSucceeded(response)
	if type(response) ~= "table" then
		return false, "invalid_response", 0
	end

	local status = tonumber(response.status_code or response.status or 0) or 0
	local body = type(response.text) == "string" and response.text or ""
	local decoded = nil

	if body ~= "" then
		local decodeOk, decodeResult = pcall(decodeJsonSafe, body)
		if decodeOk and type(decodeResult) == "table" then
			decoded = decodeResult
		end
	end

	if decoded and decoded.ok == true and (status == 0 or (status >= 200 and status < 300)) then
		return true, "", status
	end

	if decoded and decoded.ok == false then
		return false, tostring(decoded.description or ("telegram_api_error_" .. tostring(status))), status
	end

	if status < 200 or status >= 300 then
		return false, "http_" .. tostring(status), status
	end

	-- Telegram Bot API always returns a JSON object with the boolean field "ok".
	return false, "invalid_telegram_json", status
end

function telegramBuildTargets()
	local targets = {}

	if ini.cfg.telegram_reserve == true then
		targets[#targets + 1] = {
			host = "api-telegram.arz.market",
			timeout = TELEGRAM_RESERVE_TIMEOUT
		}
	end

	targets[#targets + 1] = {
		host = "api.telegram.org",
		timeout = TELEGRAM_OFFICIAL_TIMEOUT
	}

	return targets
end

function telegramCompleteJob(job, ok, host, errorMessage, status)
	TELEGRAM_SEND_ACTIVE = false

	TELEGRAM_LAST_RESULT.ok = ok == true
	TELEGRAM_LAST_RESULT.host = tostring(host or "")
	TELEGRAM_LAST_RESULT.error = tostring(errorMessage or "")
	TELEGRAM_LAST_RESULT.status = tonumber(status) or 0
	TELEGRAM_LAST_RESULT.at = os.time()

	if ok then
		print("[ArzMarket][Telegram] sent via " .. tostring(host))
		if job and job.diagnostic then
			sendNotify("Telegram: OK (" .. tostring(host) .. ")")
		end
	else
		local message = "[ArzMarket][Telegram] send failed: " .. tostring(errorMessage)
		print(message)

		if job and job.diagnostic then
			sendNotify("Telegram error: " .. tostring(errorMessage))
		end
	end

	if not TELEGRAM_SHUTTING_DOWN then
		telegramProcessSendQueue()
	end
end

function telegramHandleJobFailure(job, target, errorMessage, status)
	job.targetIndex = (tonumber(job.targetIndex) or 1) + 1

	if job.targets and job.targets[job.targetIndex] then
		print(
			"[ArzMarket][Telegram] " .. tostring(target and target.host or "?")
			.. " failed (" .. tostring(errorMessage) .. "), fallback -> "
			.. tostring(job.targets[job.targetIndex].host)
		)
		return telegramStartJob(job)
	end

	return telegramCompleteJob(
		job,
		false,
		target and target.host or "",
		errorMessage or "request_failed",
		status or 0
	)
end

function telegramStartJob(job)
	if TELEGRAM_SHUTTING_DOWN then
		TELEGRAM_SEND_ACTIVE = false
		return
	end

	if type(job) ~= "table" or type(job.targets) ~= "table" then
		return telegramCompleteJob(job, false, "", "invalid_job", 0)
	end

	job.targetIndex = tonumber(job.targetIndex) or 1
	local target = job.targets[job.targetIndex]
	if type(target) ~= "table" or type(target.host) ~= "string" or target.host == "" then
		return telegramCompleteJob(job, false, "", "invalid_target", 0)
	end

	-- Keep Telegram request shape identical to the original ArzMarket.
	-- The original script sends chat_id/text in the query string and uses an empty request body.
	local url = "https://" .. target.host
		.. "/bot" .. tostring(job.token)
		.. "/sendMessage?chat_id=" .. telegramUrlEncode(job.chatId)
		.. "&text=" .. telegramUrlEncode(job.message)

	local requestThread, requestError = telegramOriginalAsyncHttpRequest(
		"POST",
		url,
		{},
		function(response)
			local ok, errorMessage, status = telegramResponseSucceeded(response)
			if ok then
				return telegramCompleteJob(job, true, target.host, "", status)
			end
			return telegramHandleJobFailure(job, target, errorMessage, status)
		end,
		function(errorMessage)
			return telegramHandleJobFailure(job, target, tostring(errorMessage or "request_failed"), 0)
		end,
		target.timeout
	)

	if requestThread == nil then
		return telegramHandleJobFailure(job, target, requestError or "request_not_started", 0)
	end

	return requestThread
end

function telegramProcessSendQueue()
	if TELEGRAM_SHUTTING_DOWN or TELEGRAM_SEND_ACTIVE then
		return
	end

	if type(TELEGRAM_SEND_QUEUE) ~= "table" or #TELEGRAM_SEND_QUEUE == 0 then
		return
	end

	local job = table.remove(TELEGRAM_SEND_QUEUE, 1)
	if type(job) ~= "table" then
		return telegramProcessSendQueue()
	end

	TELEGRAM_SEND_ACTIVE = true
	return telegramStartJob(job)
end

function telegramWorkingOriginalAsyncHttpRequest(method, url, requestOptions, onSuccess, onError, saveSelfInfo)
	local requestId = "" .. os.clock()

	marketState.asyncData[requestId] = os.time()
	requestOptions = requestOptions or {}
	requestOptions.headers = requestOptions.headers or {}
	requestOptions.headers["Accept-Encoding"] = ini.cfg.bannedByRkn == true and zzlibLoaded == true and "gzip, deflate" or nil

	local requestThread = effil.thread(function(method, url, requestOptions)
		local requests = require("requests")
		local requestSucceeded, response = pcall(requests.request, method, url, requestOptions)

		if not requestSucceeded then
			return false, response
		end

		local isGzipEncoded = response.headers
			and response.headers["content-encoding"]
			and response.headers["content-encoding"]:find("gzip")

		local zzlibAvailable
		local zzlib

		if isGzipEncoded then
			zzlibAvailable, zzlib = pcall(require, "zzlib")
		end

		if not zzlibAvailable and isGzipEncoded then
			return false, response
		end

		if isGzipEncoded and response.text and type(response.text) == "string" and #response.text > 2 then
			local decompressedText = false
			local wasDecompressed = false

			if response.text:byte(1) == 31 and response.text:byte(2) == 139 then
				decompressedText = zzlib.gunzip(response.text)
				wasDecompressed = true
			else
				decompressedText = response.text
				wasDecompressed = false
			end

			if wasDecompressed and decompressedText then
				response.text = decompressedText
				response.original_size = #response.text
				response.decompressed = true
			else
				response.decompression_error = tostring(decompressedText)
			end
		end

		response.json, response.xml = nil
		return true, response
	end)(method, url, requestOptions)

	onSuccess = onSuccess or function()
		return
	end
	onError = onError or function()
		return
	end

	lua_thread.create(function(requestId)
		local currentThread = requestThread

		while true do
			local threadStatus, threadError = currentThread:status()

			if marketState.asyncData[requestId] + 45 < os.time() then
				marketState.asyncData[requestId] = nil
				print("reject rkn")
				return onError(threadStatus)
			end

			if not threadError then
				if threadStatus == "completed" then
					local requestSucceeded, response = currentThread:get(0)

					if requestSucceeded then
						if saveSelfInfo == 1
							and response.text ~= ""
							and response.text:find("username")
							and response.text:find("exp")
							and response.text:find("osTime")
						then
							local selfInfoFile = io.open("moonloader/ArzMarket/UsersInfo/info_users_SelfInfo.json", "w")
							if selfInfoFile then
								selfInfoFile:write(response.text)
								selfInfoFile:close()
							end
						end

						onSuccess(response)
					else
						print("rejected0")
						onError(response)
					end

					return
				elseif threadStatus == "canceled" then
					print("rejected1")
					return onError(threadStatus)
				end
			else
				print("rejected2 (zzlib)")
				return onError(threadError)
			end

			wait(0)
		end
	end, requestId)
end

function sendTelegramNotification(message)
	local utf8Message = u8(message)

	if telegramNotifyEnabled[0] == false then
		return
	end

	local plainMessage = utf8Message:gsub("{......}", "")
	local urlEncodedMessage = string.gsub(plainMessage, "([^%w-_ %.~=])", function(character)
		return string.format("%%%02X", string.byte(character))
	end)
	local telegramMessage = string.gsub(urlEncodedMessage, " ", "+")

	telegramWorkingOriginalAsyncHttpRequest(
		"POST",
		"https://"
			.. (ini.cfg.telegram_reserve and "api-telegram.arz.market" or "api.telegram.org")
			.. "/bot"
			.. ffi.string(telegramUi.token)
			.. "/sendMessage?chat_id="
			.. ffi.string(telegramUi.chat_id)
			.. "&text="
			.. telegramMessage
	)
end

function rainbowText(text, speed)
	local characters = (function(text)
		local characters = {}

		for character in text:gmatch(".") do
			characters[#characters + 1] = character
		end

		return characters
	end)(text)

	for characterIndex, character in ipairs(characters) do
		local red, green, blue = rainbows(speed, 1 / #characters * characterIndex)

		characters[characterIndex] = string.format("{%06X}%s", join_rgb(red * 255, green * 255, blue * 255), character)
	end

	return table.concat(characters, "")
end

function rainbows(speed, phaseOffset)
	phaseOffset = phaseOffset or 0

	local var_355_0 = os.clock() + phaseOffset
	local var_355_1 = math.floor(math.sin(var_355_0 * speed + 0) * 127 + 128) / 255
	local var_355_2 = math.floor(math.sin(var_355_0 * speed + 2) * 127 + 128) / 255
	local var_355_3 = math.floor(math.sin(var_355_0 * speed + 4) * 127 + 128) / 255
	local var_355_4 = 0.14
	local var_355_5 = 0.2
	local var_355_6 = math.max(var_355_1, var_355_4)
	local var_355_7 = math.max(var_355_2, var_355_4)
	local var_355_8 = math.max(var_355_3, var_355_4)
	local var_355_9 = (var_355_6 + var_355_7 + var_355_8) / 3
	local var_355_10 = math.clamp(var_355_6, var_355_9 - var_355_5, var_355_9 + var_355_5)
	local var_355_11 = math.clamp(var_355_7, var_355_9 - var_355_5, var_355_9 + var_355_5)
	local var_355_12 = math.clamp(var_355_8, var_355_9 - var_355_5, var_355_9 + var_355_5)

	return var_355_10, var_355_11, var_355_12, 1
end

function math.clamp(value, minimum, maximum)
	return math.max(minimum, math.min(maximum, value))
end

function join_rgb(red, green, blue)
	local blueChannel = blue
	local greenBlue = bit.bor(blueChannel, bit.lshift(green, 8))

	return (bit.bor(greenBlue, bit.lshift(red, 16)))
end

function asyncHttpRequest(method, url, requestOptions, onSuccess, onError, saveSelfInfo)
	-- Telegram follows the original ArzMarket network path and is intentionally
	-- isolated from our later offline/proxy transport additions.
	local isOriginalTelegramTransport = type(url) == "string" and (
		url:find("https://api.telegram.org/", 1, true) == 1
		or url:find("https://api-telegram.arz.market/", 1, true) == 1
	)

	if not isOriginalTelegramTransport and arzScriptOfflineReject("http", url) then
		if type(onError) == "function" then
			lua_thread.create(function()
				wait(0)
				pcall(onError, "offline_mode")
			end)
		end
		return nil, "offline_mode"
	end

	marketState.asyncRequestSerial = (tonumber(marketState.asyncRequestSerial) or 0) + 1
	local requestId = tostring(os.clock()) .. ":" .. tostring(marketState.asyncRequestSerial)

	marketState.asyncData[requestId] = os.time()

	local function clearAsyncRequestState()
		marketState.asyncData[requestId] = nil
		if type(marketState.asyncThreads) == "table" then
			marketState.asyncThreads[requestId] = nil
		end
	end

	requestOptions = requestOptions or {}
	requestOptions.headers = requestOptions.headers or {}
	requestOptions.headers["Accept-Encoding"] = ini.cfg.bannedByRkn == true and zzlibLoaded == true and "gzip, deflate" or nil

	local requestThread
	local proxyThread, proxyEnabled, proxyError
	if isOriginalTelegramTransport then
		-- Original ArzMarket sends Telegram directly through requests.lua in effil.
		-- Do not route Telegram through the later proxy/curl layer and never spawn cmd.exe.
		proxyThread, proxyEnabled, proxyError = nil, false, nil
	else
		proxyThread, proxyEnabled, proxyError = arzProxyCreateHttpThread(
			method,
			url,
			requestOptions,
			arzProxyNextRequestKey("http"),
			45
		)
	end

	if proxyEnabled then
		if not proxyThread then
			clearAsyncRequestState()
			if type(onError) == "function" then
				lua_thread.create(function()
					wait(0)
					pcall(onError, "proxy_required: " .. tostring(proxyError))
				end)
			end
			return nil, "proxy_required: " .. tostring(proxyError)
		end
		requestThread = proxyThread
	else
		requestThread = effil.thread(function(method, url, requestOptions)
			local requests = require("requests")
			local requestSucceeded, response = pcall(requests.request, method, url, requestOptions)

			if not requestSucceeded then
				return false, response
			end

			local isGzipEncoded = response.headers and response.headers["content-encoding"] and response.headers["content-encoding"]:find("gzip")
			local zzlibAvailable
			local zzlib

			if isGzipEncoded then
				zzlibAvailable, zzlib = pcall(require, "zzlib")
			end

			if not zzlibAvailable and isGzipEncoded then
				return false, response
			end

			if isGzipEncoded and response.text and type(response.text) == "string" and #response.text > 2 then
				local var_359_6 = false
				local decompressedText = false
				local wasDecompressed

				if response.text:byte(1) == 31 and response.text:byte(2) == 139 then
					decompressedText = zzlib.gunzip(response.text)
					wasDecompressed = true
				else
					decompressedText = response.text
					wasDecompressed = false
				end

				if wasDecompressed and decompressedText then
					response.text = decompressedText
					response.original_size = #response.text
					response.decompressed = true
				else
					response.decompression_error = tostring(decompressedText)
				end
			end

			response.json, response.xml = nil

			return true, response
		end)(method, url, requestOptions)
	end

	marketState.asyncThreads = marketState.asyncThreads or {}
	marketState.asyncThreads[requestId] = requestThread

	onSuccess = onSuccess or function()
		return
	end
	onError = onError or function()
		return
	end

	lua_thread.create(function(requestId)
		local requestThread = requestThread

		while true do
			if ARZ_SCRIPT_OFFLINE and not isOriginalTelegramTransport then
				pcall(function()
					if requestThread.cancel then requestThread:cancel() end
				end)
				clearAsyncRequestState()
				return
			end

			local threadStatus, threadError = requestThread:status()

			local requestStartedAt = marketState.asyncData[requestId]
			if requestStartedAt == nil then
				return
			end

			if requestStartedAt + 45 < os.time() then
				clearAsyncRequestState()

				print("reject rkn")

				return onError(threadStatus)
			end

			if not threadError then
				if threadStatus == "running" and marketState.marketplaceTimeOut == nil and url:find("getMarketplace") and timers[39][1] + 1 < os.time() then
					timers[39][1] = os.time()
					timers[39][2] = timers[39][2] + 1

					deAFKMessage("timer[39] + 1 " .. timers[39][2])
					print("timer[39] + 1 | " .. timers[39][2])

					if timers[39][2] > 9 then
						marketState.marketplaceTimeOut = true
						clearAsyncRequestState()

						onError(threadError)

						return
					end
				end

				if threadStatus == "running" and url:find("getAllPremiumItems") and ini.cfg.priumUrlChange == false and timers[40][1] + 1 < os.time() then
					timers[40] = {
						os.time(),
						timers[40][2] + 1
					}

					print("premiumitems error counter > " .. timers[40][2])

					if timers[40][2] > 15 then
						clearAsyncRequestState()
						AFKMessage(u8:decode("К сожалению таблицу цен загрузить не получилось из за ограничения вашего провайдера."))
						AFKMessage(u8:decode("Для решения вашей проблемы возможно поможет команда /premhost, напишите ее в чат игры"))
						onError(threadError)

						return
					end
				end

				if threadStatus == "completed" then
					local requestSucceeded, response = requestThread:get(0)
					clearAsyncRequestState()

					if requestSucceeded then
						if not ARZ_INI_WRITE_LOCKED and saveSelfInfo == 1 and response.text ~= "" and response.text:find("username") and response.text:find("exp") and response.text:find("osTime") then
							arzAuthFreezeSelfInfo(response.text)
						end
						onSuccess(response)
					else
						print("rejected0")
						onError(response)
					end

					return
				elseif threadStatus == "canceled" then
					clearAsyncRequestState()
					print("rejected1")

					return onError(threadStatus)
				end
			else
				clearAsyncRequestState()
				print("rejected2 (zzlib)")

				return onError(threadError)
			end

			wait(0)
		end
	end, requestId)
end

